window.SHAKESPEARE_CHINESE["part0043"]={"id":"part0043","title":"维纳斯与阿都尼","translator":"张谷若","translatorCredit":"张谷若 译","attributionStatus":"explicit","kind":"poetry-or-collection","englishId":"venus_and_adonis","sections":[{"id":"part0043-section-000","label":"书前与译者","kind":"preface","blocks":[{"id":"part0043-00000","html":"\n\u003ch1 id=\"epub-part0043-a1047\" class=\"epub-front\">莎士比亚全集 Ⅺ\u003c/h1>\n","text":"\n莎士比亚全集 Ⅺ\n","sourceAnchor":"a1047","tag":"h1"},{"id":"part0043-00001","html":"\u003ch2 id=\"epub-part0043-a1048\" class=\"epub-calibre9\">维纳斯与阿都尼\u003c/h2>\n","text":"维纳斯与阿都尼\n","sourceAnchor":"a1048","tag":"h2"},{"id":"part0043-00002","html":"\u003cp class=\"epub-center\">鄙夫俗士，望敝屣而下拜；我则求：\u003c/p>\n","text":"鄙夫俗士，望敝屣而下拜；我则求：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00003","html":"\u003cp class=\"epub-center\">阿波罗饮我以缪斯泉水流溢之玉杯。\u003c/p>\n","text":"阿波罗饮我以缪斯泉水流溢之玉杯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00004","html":"\u003cp class=\"epub-center\">张谷若 译\u003c/p>\n","text":"张谷若 译\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00005","html":"\u003cp class=\"epub-center\">\u003cimg src=\"data/chinese-collection/images/00221.jpeg\" alt=\"\" loading=\"lazy\" class=\"epub-calibre2 epub-image\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00006","html":"\u003cp class=\"epub-center\">献与扫桑普顿伯爵兼提齐菲尔男爵亨利·娄赛斯雷阁下\u003c/p>\n","text":"献与扫桑普顿伯爵兼提齐菲尔男爵亨利·娄赛斯雷阁下\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00007","html":"\u003cp class=\"epub-left\">阁下，\u003c/p>\n","text":"阁下，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00008","html":"\u003cp class=\"epub-calibre1\">仆今以鄙俚粗陋之诗篇，献于阁下，其冒昧干渎，自不待言；而仆以此荏弱之柔条纤梗，竟谬欲缘附桢干栋梁以自固，其将招物议之非难，亦不待言。然苟阁下不惜纡尊，笑而纳此芹献，则非特仆之为荣，亦已过当，且誓将以有生之暇日，竭其勤恳之微力，从事差可不负阁下青睐之作以自励。设此初次问世之篇章，不堪入目，则有负阁下之栽培，诚惶恐之不暇，更何敢再事此硗瘠砚田之耕耘，以重其以芜杂之词亵渎清听之罪乎？窃不自谅，以为凡此一切，皆阁下之睿智及明鉴是赖，即阁下之所欲，与世人之所期待，亦莫不以此是赖也。\u003c/p>\n","text":"仆今以鄙俚粗陋之诗篇，献于阁下，其冒昧干渎，自不待言；而仆以此荏弱之柔条纤梗，竟谬欲缘附桢干栋梁以自固，其将招物议之非难，亦不待言。然苟阁下不惜纡尊，笑而纳此芹献，则非特仆之为荣，亦已过当，且誓将以有生之暇日，竭其勤恳之微力，从事差可不负阁下青睐之作以自励。设此初次问世之篇章，不堪入目，则有负阁下之栽培，诚惶恐之不暇，更何敢再事此硗瘠砚田之耕耘，以重其以芜杂之词亵渎清听之罪乎？窃不自谅，以为凡此一切，皆阁下之睿智及明鉴是赖，即阁下之所欲，与世人之所期待，亦莫不以此是赖也。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00009","html":"\u003cp class=\"epub-right\">阁下犬马仆\u003c/p>\n","text":"阁下犬马仆\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00010","html":"\u003cp class=\"epub-right\">威廉·莎士比亚\u003c/p>\n","text":"威廉·莎士比亚\n","sourceAnchor":null,"tag":"p"}]},{"id":"part0043-section-001","label":"维纳斯与阿都尼","kind":"heading","blocks":[{"id":"part0043-00011","html":"\u003ch3 id=\"epub-part0043-a1049\" class=\"epub-calibre11\">维纳斯与阿都尼\u003c/h3>\n","text":"维纳斯与阿都尼\n","sourceAnchor":"a1049","tag":"h3"},{"id":"part0043-00012","html":"\u003cp class=\"epub-calibre1\">太阳刚刚东升，圆圆的脸又大又红，\u003c/p>\n","text":"太阳刚刚东升，圆圆的脸又大又红，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00013","html":"\u003cp class=\"epub-calibre1\">泣露的清晓也刚刚别去，犹留遗踪，\u003c/p>\n","text":"泣露的清晓也刚刚别去，犹留遗踪，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00014","html":"\u003cp class=\"epub-calibre1\">双颊绯红的阿都尼，就已驰逐匆匆。\u003c/p>\n","text":"双颊绯红的阿都尼，就已驰逐匆匆。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00015","html":"\u003cp class=\"epub-calibre1\">他爱好的是追猎，他嗤笑的是谈情。\u003c/p>\n","text":"他爱好的是追猎，他嗤笑的是谈情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00016","html":"\u003cp class=\"epub-calibre1\">维纳斯偏把单思害，急急忙忙，紧紧随定，\u003c/p>\n","text":"维纳斯偏把单思害，急急忙忙，紧紧随定，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00017","html":"\u003cp class=\"epub-calibre1\">拚却女儿羞容，凭厚颜，要演一出凰求凤。\u003c/p>\n","text":"拚却女儿羞容，凭厚颜，要演一出凰求凤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00018","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00019","html":"\u003cp class=\"epub-calibre1\">她先夸他美，说，“你比我还美好几倍。\u003c/p>\n","text":"她先夸他美，说，“你比我还美好几倍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00020","html":"\u003cp class=\"epub-calibre1\">地上百卉你为魁，芬芳清逸绝无对。\u003c/p>\n","text":"地上百卉你为魁，芬芳清逸绝无对。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00021","html":"\u003cp class=\"epub-calibre1\">仙子比你失颜色，壮男比你空雄伟。\u003c/p>\n","text":"仙子比你失颜色，壮男比你空雄伟。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00022","html":"\u003cp class=\"epub-calibre1\">你洁白胜过白鸽子，娇红胜过红玫瑰。\u003c/p>\n","text":"你洁白胜过白鸽子，娇红胜过红玫瑰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00023","html":"\u003cp class=\"epub-calibre1\">造化生你，自斗智慧，使你一身，俊秀荟萃。\u003c/p>\n","text":"造化生你，自斗智慧，使你一身，俊秀荟萃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00024","html":"\u003cp class=\"epub-calibre1\">她说，‘你若一旦休，便天地同尽，万物共毁。’\u003c/p>\n","text":"她说，‘你若一旦休，便天地同尽，万物共毁。’\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00025","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00026","html":"\u003cp class=\"epub-calibre1\">“你这奇异的英华，请你屈尊先下骏马。\u003c/p>\n","text":"“你这奇异的英华，请你屈尊先下骏马。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00027","html":"\u003cp class=\"epub-calibre1\">且把昂然的马首鞍头络，缰绳鞍头搭。\u003c/p>\n","text":"且把昂然的马首鞍头络，缰绳鞍头搭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00028","html":"\u003cp class=\"epub-calibre1\">你若赏脸肯贬身价，那我的温存浃洽，\u003c/p>\n","text":"你若赏脸肯贬身价，那我的温存浃洽，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00029","html":"\u003cp class=\"epub-calibre1\">有万般未经人知的甜蜜，作你的酬答。\u003c/p>\n","text":"有万般未经人知的甜蜜，作你的酬答。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00030","html":"\u003cp class=\"epub-calibre1\">咱们到这永无嘶嘶蛇鸣的地方先坐下，\u003c/p>\n","text":"咱们到这永无嘶嘶蛇鸣的地方先坐下，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00031","html":"\u003cp class=\"epub-calibre1\">坐定后，要紧紧相偎倚，我好把你来吻杀。\u003c/p>\n","text":"坐定后，要紧紧相偎倚，我好把你来吻杀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00032","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00033","html":"\u003cp class=\"epub-calibre1\">“我这吻，决不会因过多而腻得你恶心，\u003c/p>\n","text":"“我这吻，决不会因过多而腻得你恶心，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00034","html":"\u003cp class=\"epub-calibre1\">它若越多，它就越会惹得你饥渴难忍。\u003c/p>\n","text":"它若越多，它就越会惹得你饥渴难忍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00035","html":"\u003cp class=\"epub-calibre1\">它叫你的嘴唇时红时白，变化无穷尽。\u003c/p>\n","text":"它叫你的嘴唇时红时白，变化无穷尽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00036","html":"\u003cp class=\"epub-calibre1\">十吻犹似一吻新，一吻就甜过二十吻。\u003c/p>\n","text":"十吻犹似一吻新，一吻就甜过二十吻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00037","html":"\u003cp class=\"epub-calibre1\">如果在这样消遣光阴的娱乐中共厮混，\u003c/p>\n","text":"如果在这样消遣光阴的娱乐中共厮混，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00038","html":"\u003cp class=\"epub-calibre1\">那么，炎夏迟迟的长日，都要去得像一瞬。”\u003c/p>\n","text":"那么，炎夏迟迟的长日，都要去得像一瞬。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00039","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00040","html":"\u003cp class=\"epub-calibre1\">她这样讲，并捉住他汗津津的手不放。\u003c/p>\n","text":"她这样讲，并捉住他汗津津的手不放。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00041","html":"\u003cp class=\"epub-calibre1\">（汗津津的，表示他精力充沛、血气盛旺）\u003c/p>\n","text":"（汗津津的，表示他精力充沛、血气盛旺）\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00042","html":"\u003cp class=\"epub-calibre1\">风情激得她颤声叫这汗是玉液琼浆，\u003c/p>\n","text":"风情激得她颤声叫这汗是玉液琼浆，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00043","html":"\u003cp class=\"epub-calibre1\">世上给女神治相思的灵药，数它最强。\u003c/p>\n","text":"世上给女神治相思的灵药，数它最强。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00044","html":"\u003cp class=\"epub-calibre1\">爱焰给了她一股力量，弄得她如痴如狂，\u003c/p>\n","text":"爱焰给了她一股力量，弄得她如痴如狂，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00045","html":"\u003cp class=\"epub-calibre1\">叫她勇气勃勃地，把他从马上揪到地上。\u003c/p>\n","text":"叫她勇气勃勃地，把他从马上揪到地上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00046","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00047","html":"\u003cp class=\"epub-calibre1\">她一只手挽住了缰绳，把骏马轻拢，\u003c/p>\n","text":"她一只手挽住了缰绳，把骏马轻拢，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00048","html":"\u003cp class=\"epub-calibre1\">另一只胳膊把那嫩孩子紧紧挟定。\u003c/p>\n","text":"另一只胳膊把那嫩孩子紧紧挟定。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00049","html":"\u003cp class=\"epub-calibre1\">只见他又红脸，又噘嘴，老那么心硬，\u003c/p>\n","text":"只见他又红脸，又噘嘴，老那么心硬，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00050","html":"\u003cp class=\"epub-calibre1\">似木石无灵，不懂什么叫男女风情。\u003c/p>\n","text":"似木石无灵，不懂什么叫男女风情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00051","html":"\u003cp class=\"epub-calibre1\">她脸又红，心又热，似一团炭火，熊熊融融，\u003c/p>\n","text":"她脸又红，心又热，似一团炭火，熊熊融融，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00052","html":"\u003cp class=\"epub-calibre1\">他脸也红，心却冷，只羞似霞烘，严如霜凝。\u003c/p>\n","text":"他脸也红，心却冷，只羞似霞烘，严如霜凝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00053","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00054","html":"\u003cp class=\"epub-calibre1\">她轻快敏捷地——使她这样的是爱力——\u003c/p>\n","text":"她轻快敏捷地——使她这样的是爱力——\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00055","html":"\u003cp class=\"epub-calibre1\">把镂饰的缰绳在皴裂的树枝上拴起。\u003c/p>\n","text":"把镂饰的缰绳在皴裂的树枝上拴起。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00056","html":"\u003cp class=\"epub-calibre1\">马已经这样系牢，她就连忙打主意，\u003c/p>\n","text":"马已经这样系牢，她就连忙打主意，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00057","html":"\u003cp class=\"epub-calibre1\">想把骑马那个人的心也牢牢紧系。\u003c/p>\n","text":"想把骑马那个人的心也牢牢紧系。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00058","html":"\u003cp class=\"epub-calibre1\">她像愿意人家对她那样，推他仰卧在地。\u003c/p>\n","text":"她像愿意人家对她那样，推他仰卧在地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00059","html":"\u003cp class=\"epub-calibre1\">爱既无法使他就范，她就用力把他控制。\u003c/p>\n","text":"爱既无法使他就范，她就用力把他控制。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00060","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00061","html":"\u003cp class=\"epub-calibre1\">他一倒在尘埃，她也卧下和他并排。\u003c/p>\n","text":"他一倒在尘埃，她也卧下和他并排。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00062","html":"\u003cp class=\"epub-calibre1\">他们用胳膊和胯骨支身，侧卧相挨。\u003c/p>\n","text":"他们用胳膊和胯骨支身，侧卧相挨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00063","html":"\u003cp class=\"epub-calibre1\">他直皱眉头，她就直抚摸他的两腮。\u003c/p>\n","text":"他直皱眉头，她就直抚摸他的两腮。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00064","html":"\u003cp class=\"epub-calibre1\">他开口骂，她就用吻把他的嘴堵塞。\u003c/p>\n","text":"他开口骂，她就用吻把他的嘴堵塞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00065","html":"\u003cp class=\"epub-calibre1\">她一边吻，一边把情话续续断断讲起来。\u003c/p>\n","text":"她一边吻，一边把情话续续断断讲起来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00066","html":"\u003cp class=\"epub-calibre1\">“你要是骂，我就堵住了你，叫你有口难开。”\u003c/p>\n","text":"“你要是骂，我就堵住了你，叫你有口难开。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00067","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00068","html":"\u003cp class=\"epub-calibre1\">他又烦躁、又害臊，闹得两腮似火烧。\u003c/p>\n","text":"他又烦躁、又害臊，闹得两腮似火烧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00069","html":"\u003cp class=\"epub-calibre1\">她就用泪往他处女一般热的脸上浇。\u003c/p>\n","text":"她就用泪往他处女一般热的脸上浇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00070","html":"\u003cp class=\"epub-calibre1\">接着又叹息像轻风袅，金发像日色耀，\u003c/p>\n","text":"接着又叹息像轻风袅，金发像日色耀，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00071","html":"\u003cp class=\"epub-calibre1\">把污在他脸上的泪痕，给他吹干拂掉。\u003c/p>\n","text":"把污在他脸上的泪痕，给他吹干拂掉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00072","html":"\u003cp class=\"epub-calibre1\">他骂她轻佻，说她不知自好，净卖弄风骚。\u003c/p>\n","text":"他骂她轻佻，说她不知自好，净卖弄风骚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00073","html":"\u003cp class=\"epub-calibre1\">他还要絮叨，她就用嘴堵得他语咽声销。\u003c/p>\n","text":"他还要絮叨，她就用嘴堵得他语咽声销。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00074","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00075","html":"\u003cp class=\"epub-calibre1\">空腹的苍鹰，饿得眼疾心急，馋涎欲滴，\u003c/p>\n","text":"空腹的苍鹰，饿得眼疾心急，馋涎欲滴，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00076","html":"\u003cp class=\"epub-calibre1\">抓住小鸟，用利喙把毛、肉、骨头一齐撕。\u003c/p>\n","text":"抓住小鸟，用利喙把毛、肉、骨头一齐撕。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00077","html":"\u003cp class=\"epub-calibre1\">鼓翼助威势，贪婪猛吞噬，忙忙又急急，\u003c/p>\n","text":"鼓翼助威势，贪婪猛吞噬，忙忙又急急，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00078","html":"\u003cp class=\"epub-calibre1\">饥胃填不满，食物咽不尽，就无停止时。\u003c/p>\n","text":"饥胃填不满，食物咽不尽，就无停止时。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00079","html":"\u003cp class=\"epub-calibre1\">她就像这样，把他的额、腮、下颏吻个不已，\u003c/p>\n","text":"她就像这样，把他的额、腮、下颏吻个不已，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00080","html":"\u003cp class=\"epub-calibre1\">因为她吻完了一遍，又从头儿开始吻起。\u003c/p>\n","text":"因为她吻完了一遍，又从头儿开始吻起。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00081","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00082","html":"\u003cp class=\"epub-calibre1\">他无奈只好不抵抗，要他情愿却难想。\u003c/p>\n","text":"他无奈只好不抵抗，要他情愿却难想。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00083","html":"\u003cp class=\"epub-calibre1\">他躺在那儿直喘息，气都扑到她脸上。\u003c/p>\n","text":"他躺在那儿直喘息，气都扑到她脸上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00084","html":"\u003cp class=\"epub-calibre1\">她把这气吸，像强者吃弱者的肉那样。\u003c/p>\n","text":"她把这气吸，像强者吃弱者的肉那样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00085","html":"\u003cp class=\"epub-calibre1\">她说这就是天降的云液，神赐的玉浆；\u003c/p>\n","text":"她说这就是天降的云液，神赐的玉浆；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00086","html":"\u003cp class=\"epub-calibre1\">她恨不得她的双颊就是花园，花发草长，\u003c/p>\n","text":"她恨不得她的双颊就是花园，花发草长，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00087","html":"\u003cp class=\"epub-calibre1\">好来承受这样甘霖的灌溉，琼露的滋养。\u003c/p>\n","text":"好来承受这样甘霖的灌溉，琼露的滋养。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00088","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00089","html":"\u003cp class=\"epub-calibre1\">你曾见过小鸟落了网罗，无法能逃脱？\u003c/p>\n","text":"你曾见过小鸟落了网罗，无法能逃脱？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00090","html":"\u003cp class=\"epub-calibre1\">阿都尼在她怀里，就像小鸟落了网罗。\u003c/p>\n","text":"阿都尼在她怀里，就像小鸟落了网罗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00091","html":"\u003cp class=\"epub-calibre1\">他懊恼，半因羞涩，半因不敢强挣硬夺。\u003c/p>\n","text":"他懊恼，半因羞涩，半因不敢强挣硬夺。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00092","html":"\u003cp class=\"epub-calibre1\">他的两眼越含嗔，他的美貌越增颜色。\u003c/p>\n","text":"他的两眼越含嗔，他的美貌越增颜色。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00093","html":"\u003cp class=\"epub-calibre1\">本来就满了槽的河水，再加上大雨滂沱，\u003c/p>\n","text":"本来就满了槽的河水，再加上大雨滂沱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00094","html":"\u003cp class=\"epub-calibre1\">势必溢出河槽，往两岸泛滥，把四处淹没。\u003c/p>\n","text":"势必溢出河槽，往两岸泛滥，把四处淹没。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00095","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00096","html":"\u003cp class=\"epub-calibre1\">她一直地苦诉衷怀，迷人地苦诉衷怀，\u003c/p>\n","text":"她一直地苦诉衷怀，迷人地苦诉衷怀，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00097","html":"\u003cp class=\"epub-calibre1\">因为她要对迷人的两耳，把心事表白。\u003c/p>\n","text":"因为她要对迷人的两耳，把心事表白。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00098","html":"\u003cp class=\"epub-calibre1\">但是他却老闹脾气，老皱眉头，老不耐，\u003c/p>\n","text":"但是他却老闹脾气，老皱眉头，老不耐，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00099","html":"\u003cp class=\"epub-calibre1\">有时羞得脸通红，又有时气得脸灰白。\u003c/p>\n","text":"有时羞得脸通红，又有时气得脸灰白。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00100","html":"\u003cp class=\"epub-calibre1\">脸红时她最爱，脸白时她就爱上更加爱，\u003c/p>\n","text":"脸红时她最爱，脸白时她就爱上更加爱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00101","html":"\u003cp class=\"epub-calibre1\">那比起她所最爱的来，更叫她笑逐颜开。\u003c/p>\n","text":"那比起她所最爱的来，更叫她笑逐颜开。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00102","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00103","html":"\u003cp class=\"epub-calibre1\">不管他羞答答，怒冲冲，她看着都动情。\u003c/p>\n","text":"不管他羞答答，怒冲冲，她看着都动情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00104","html":"\u003cp class=\"epub-calibre1\">她指着她那永远纤柔、白嫩的手作证，\u003c/p>\n","text":"她指着她那永远纤柔、白嫩的手作证，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00105","html":"\u003cp class=\"epub-calibre1\">说她决不离开他那柔软温暖的酥胸，\u003c/p>\n","text":"说她决不离开他那柔软温暖的酥胸，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00106","html":"\u003cp class=\"epub-calibre1\">除非他被她的眼泪所驯服，言听计从；\u003c/p>\n","text":"除非他被她的眼泪所驯服，言听计从；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00107","html":"\u003cp class=\"epub-calibre1\">因为她早就已经泪如雨倾，满脸上纵横。\u003c/p>\n","text":"因为她早就已经泪如雨倾，满脸上纵横。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00108","html":"\u003cp class=\"epub-calibre1\">甜甜一吻，就能把本来没有完的债还清。\u003c/p>\n","text":"甜甜一吻，就能把本来没有完的债还清。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00109","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00110","html":"\u003cp class=\"epub-calibre1\">他听她作了这样誓词，便把下颏仰起。\u003c/p>\n","text":"他听她作了这样誓词，便把下颏仰起。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00111","html":"\u003cp class=\"epub-calibre1\">但他正要把她所求的东西勉强赐给，\u003c/p>\n","text":"但他正要把她所求的东西勉强赐给，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00112","html":"\u003cp class=\"epub-calibre1\">却像在水里那样，稍一探头窥伺，\u003c/p>\n","text":"却像在水里那样，稍一探头窥伺，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00113","html":"\u003cp class=\"epub-calibre1\">看见有人瞭望，就又一下钻回了水底。\u003c/p>\n","text":"看见有人瞭望，就又一下钻回了水底。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00114","html":"\u003cp class=\"epub-calibre1\">因此她虽把双唇噘起，准备他对她还礼，\u003c/p>\n","text":"因此她虽把双唇噘起，准备他对她还礼，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00115","html":"\u003cp class=\"epub-calibre1\">他却把嘴转到另一边，同时把眼睛一闭。90\u003c/p>\n","text":"他却把嘴转到另一边，同时把眼睛一闭。90\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00116","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00117","html":"\u003cp class=\"epub-calibre1\">夏日炎炎中路上的人，即便渴得要晕，\u003c/p>\n","text":"夏日炎炎中路上的人，即便渴得要晕，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00118","html":"\u003cp class=\"epub-calibre1\">也从来没有像她那样，急于一润渴吻。\u003c/p>\n","text":"也从来没有像她那样，急于一润渴吻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00119","html":"\u003cp class=\"epub-calibre1\">她只闻香却难到口，这心痒叫人怎忍。\u003c/p>\n","text":"她只闻香却难到口，这心痒叫人怎忍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00120","html":"\u003cp class=\"epub-calibre1\">她泪水如浴似淋，却救不得心火如焚。\u003c/p>\n","text":"她泪水如浴似淋，却救不得心火如焚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00121","html":"\u003cp class=\"epub-calibre1\">“哎呀，”她喊道，“你这孩子心如铁石真好狠，\u003c/p>\n","text":"“哎呀，”她喊道，“你这孩子心如铁石真好狠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00122","html":"\u003cp class=\"epub-calibre1\">我不过只求你一吻，又何必这样苦悭吝。\u003c/p>\n","text":"我不过只求你一吻，又何必这样苦悭吝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00123","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00124","html":"\u003cp class=\"epub-calibre1\">“我也曾有一度被追求得忙，像你这样。\u003c/p>\n","text":"“我也曾有一度被追求得忙，像你这样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00125","html":"\u003cp class=\"epub-calibre1\">追我的非别个，是战神，威凛然，貌昂藏。\u003c/p>\n","text":"追我的非别个，是战神，威凛然，貌昂藏。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00126","html":"\u003cp class=\"epub-calibre1\">他在战场上，从未低过头，出名的强项。\u003c/p>\n","text":"他在战场上，从未低过头，出名的强项。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00127","html":"\u003cp class=\"epub-calibre1\">他到处战无不胜，从来就没打过败仗。\u003c/p>\n","text":"他到处战无不胜，从来就没打过败仗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00128","html":"\u003cp class=\"epub-calibre1\">然而他却是我的俘虏，甘心作我的厮养。\u003c/p>\n","text":"然而他却是我的俘虏，甘心作我的厮养。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00129","html":"\u003cp class=\"epub-calibre1\">他向我求过现在你能不求而获的欢畅。\u003c/p>\n","text":"他向我求过现在你能不求而获的欢畅。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00130","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00131","html":"\u003cp class=\"epub-calibre1\">“他那伤痕斑斑的盾，百战犹完的甲，\u003c/p>\n","text":"“他那伤痕斑斑的盾，百战犹完的甲，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00132","html":"\u003cp class=\"epub-calibre1\">还有长矛，都曾在我的祭坛上闲挂，\u003c/p>\n","text":"还有长矛，都曾在我的祭坛上闲挂，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00133","html":"\u003cp class=\"epub-calibre1\">他为我，学会了蹁跹舞步，诸般戏耍，\u003c/p>\n","text":"他为我，学会了蹁跹舞步，诸般戏耍，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00134","html":"\u003cp class=\"epub-calibre1\">他为我，学会了打情骂俏，斗口磨牙，\u003c/p>\n","text":"他为我，学会了打情骂俏，斗口磨牙，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00135","html":"\u003cp class=\"epub-calibre1\">耳里厌闻战鼓喧闹，眼里厌看旌旗飘飒；\u003c/p>\n","text":"耳里厌闻战鼓喧闹，眼里厌看旌旗飘飒；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00136","html":"\u003cp class=\"epub-calibre1\">在我的绣榻上安营，在我的玉臂间厮杀。\u003c/p>\n","text":"在我的绣榻上安营，在我的玉臂间厮杀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00137","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00138","html":"\u003cp class=\"epub-calibre1\">“这样，以威势服人的还得服我的威势。\u003c/p>\n","text":"“这样，以威势服人的还得服我的威势。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00139","html":"\u003cp class=\"epub-calibre1\">一根红玫瑰链子，就拴得他匍匐在地。\u003c/p>\n","text":"一根红玫瑰链子，就拴得他匍匐在地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00140","html":"\u003cp class=\"epub-calibre1\">多么硬的钢铁，在他手里都成了烂泥。\u003c/p>\n","text":"多么硬的钢铁，在他手里都成了烂泥。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00141","html":"\u003cp class=\"epub-calibre1\">然而我对他鄙夷，他却只有奴颜婢膝。\u003c/p>\n","text":"然而我对他鄙夷，他却只有奴颜婢膝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00142","html":"\u003cp class=\"epub-calibre1\">你现在能使制伏了战神的我低声下气，\u003c/p>\n","text":"你现在能使制伏了战神的我低声下气，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00143","html":"\u003cp class=\"epub-calibre1\">请不必骄傲夸耀，回答我的爱才是正理。\u003c/p>\n","text":"请不必骄傲夸耀，回答我的爱才是正理。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00144","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00145","html":"\u003cp class=\"epub-calibre1\">“你只把你的香唇触到我的嘴唇上，\u003c/p>\n","text":"“你只把你的香唇触到我的嘴唇上，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00146","html":"\u003cp class=\"epub-calibre1\">（我的嘴唇也很红，虽然没有你的香），\u003c/p>\n","text":"（我的嘴唇也很红，虽然没有你的香），\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00147","html":"\u003cp class=\"epub-calibre1\">那这个吻的甜蜜，咱们就能同受共享。\u003c/p>\n","text":"那这个吻的甜蜜，咱们就能同受共享。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00148","html":"\u003cp class=\"epub-calibre1\">抬起头来！地上有什么吸引你的眼光？\u003c/p>\n","text":"抬起头来！地上有什么吸引你的眼光？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00149","html":"\u003cp class=\"epub-calibre1\">往我瞳人里望，那儿有你的倩影深深藏。\u003c/p>\n","text":"往我瞳人里望，那儿有你的倩影深深藏。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00150","html":"\u003cp class=\"epub-calibre1\">眼和眼既然成对，唇和唇为何不能成双？\u003c/p>\n","text":"眼和眼既然成对，唇和唇为何不能成双？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00151","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00152","html":"\u003cp class=\"epub-calibre1\">“你接吻不惯？那你就闭上眼，不要看。\u003c/p>\n","text":"“你接吻不惯？那你就闭上眼，不要看。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00153","html":"\u003cp class=\"epub-calibre1\">我也闭上眼。这样，白天就仿佛夜晚。\u003c/p>\n","text":"我也闭上眼。这样，白天就仿佛夜晚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00154","html":"\u003cp class=\"epub-calibre1\">只要有一女一男，‘爱’就能取乐追欢。\u003c/p>\n","text":"只要有一女一男，‘爱’就能取乐追欢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00155","html":"\u003cp class=\"epub-calibre1\">你要放胆，咱们尽管畅玩，没人看见。\u003c/p>\n","text":"你要放胆，咱们尽管畅玩，没人看见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00156","html":"\u003cp class=\"epub-calibre1\">咱们身下这紫络的二月兰，决不会多言，\u003c/p>\n","text":"咱们身下这紫络的二月兰，决不会多言，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00157","html":"\u003cp class=\"epub-calibre1\">它们也不懂得，咱们为什么要如此这般。\u003c/p>\n","text":"它们也不懂得，咱们为什么要如此这般。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00158","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00159","html":"\u003cp class=\"epub-calibre1\">“你迷人的嘴上黄毛嫩，说你还是童孩。\u003c/p>\n","text":"“你迷人的嘴上黄毛嫩，说你还是童孩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00160","html":"\u003cp class=\"epub-calibre1\">但你却早就有秀色可餐，有英华堪采。\u003c/p>\n","text":"但你却早就有秀色可餐，有英华堪采。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00161","html":"\u003cp class=\"epub-calibre1\">行乐须及时，莫疑猜，机会错过不复来。\u003c/p>\n","text":"行乐须及时，莫疑猜，机会错过不复来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00162","html":"\u003cp class=\"epub-calibre1\">丽质应该传代，及身而止，只暴殄美材。\u003c/p>\n","text":"丽质应该传代，及身而止，只暴殄美材。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00163","html":"\u003cp class=\"epub-calibre1\">好花盛开，就该尽先摘，慎莫待美景难再，\u003c/p>\n","text":"好花盛开，就该尽先摘，慎莫待美景难再，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00164","html":"\u003cp class=\"epub-calibre1\">否则一瞬间，它就要凋零萎谢，落在尘埃。\u003c/p>\n","text":"否则一瞬间，它就要凋零萎谢，落在尘埃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00165","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00166","html":"\u003cp class=\"epub-calibre1\">“我若头秃脸麻，形容老丑，鸡皮鹤发；\u003c/p>\n","text":"“我若头秃脸麻，形容老丑，鸡皮鹤发；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00167","html":"\u003cp class=\"epub-calibre1\">我若性情粗暴，行动乖戾，举止欠雅；\u003c/p>\n","text":"我若性情粗暴，行动乖戾，举止欠雅；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00168","html":"\u003cp class=\"epub-calibre1\">患风湿，长癣疥，枯瘦干瘪，嗓音粗哑；\u003c/p>\n","text":"患风湿，长癣疥，枯瘦干瘪，嗓音粗哑；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00169","html":"\u003cp class=\"epub-calibre1\">千人厌，万人弃，先天不育，两眼昏花：\u003c/p>\n","text":"千人厌，万人弃，先天不育，两眼昏花：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00170","html":"\u003cp class=\"epub-calibre1\">那你退缩原也不差；因我和你本难配搭。\u003c/p>\n","text":"那你退缩原也不差；因我和你本难配搭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00171","html":"\u003cp class=\"epub-calibre1\">但这既都不在话下，到底什么叫你惊怕？\u003c/p>\n","text":"但这既都不在话下，到底什么叫你惊怕？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00172","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00173","html":"\u003cp class=\"epub-calibre1\">“你在我额上，决不会找出来半条皱纹。\u003c/p>\n","text":"“你在我额上，决不会找出来半条皱纹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00174","html":"\u003cp class=\"epub-calibre1\">我的眼水汪汪碧波欲流，转盼多风韵。\u003c/p>\n","text":"我的眼水汪汪碧波欲流，转盼多风韵。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00175","html":"\u003cp class=\"epub-calibre1\">我的美丽像春日，年年不老，岁岁更新。\u003c/p>\n","text":"我的美丽像春日，年年不老，岁岁更新。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00176","html":"\u003cp class=\"epub-calibre1\">我的肌肤丰润，连骨髓里都春情欲焚。\u003c/p>\n","text":"我的肌肤丰润，连骨髓里都春情欲焚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00177","html":"\u003cp class=\"epub-calibre1\">我这腻滑的手，你若肯握一握表示亲近，\u003c/p>\n","text":"我这腻滑的手，你若肯握一握表示亲近，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00178","html":"\u003cp class=\"epub-calibre1\">它就要在你手里，如酥欲融，化去不复存。\u003c/p>\n","text":"它就要在你手里，如酥欲融，化去不复存。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00179","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00180","html":"\u003cp class=\"epub-calibre1\">“我也会闲谈答话，作悦耳的解语花；\u003c/p>\n","text":"“我也会闲谈答话，作悦耳的解语花；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00181","html":"\u003cp class=\"epub-calibre1\">我也会学精灵，在绿莎上细步轻踏；\u003c/p>\n","text":"我也会学精灵，在绿莎上细步轻踏；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00182","html":"\u003cp class=\"epub-calibre1\">我也会学水中仙子，飘飘披着长发，\u003c/p>\n","text":"我也会学水中仙子，飘飘披着长发，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00183","html":"\u003cp class=\"epub-calibre1\">用平沙作舞茵，却不见有脚踪留下。\u003c/p>\n","text":"用平沙作舞茵，却不见有脚踪留下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00184","html":"\u003cp class=\"epub-calibre1\">爱之为物，本是火的精华，空灵、倏忽、飘洒，\u003c/p>\n","text":"爱之为物，本是火的精华，空灵、倏忽、飘洒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00185","html":"\u003cp class=\"epub-calibre1\">并非重浊而下沉，却是轻清上浮而欲化。\u003c/p>\n","text":"并非重浊而下沉，却是轻清上浮而欲化。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00186","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00187","html":"\u003cp class=\"epub-calibre1\">“你看我身下陂陀上的樱草，虽然荏弱，\u003c/p>\n","text":"“你看我身下陂陀上的樱草，虽然荏弱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00188","html":"\u003cp class=\"epub-calibre1\">却能像粗壮的大树，把我的身子轻托。\u003c/p>\n","text":"却能像粗壮的大树，把我的身子轻托。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00189","html":"\u003cp class=\"epub-calibre1\">拉着我的辇周天游遍的，是两只鹁鸽：\u003c/p>\n","text":"拉着我的辇周天游遍的，是两只鹁鸽：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00190","html":"\u003cp class=\"epub-calibre1\">它们弱小，却能叫我整天价到处行乐。\u003c/p>\n","text":"它们弱小，却能叫我整天价到处行乐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00191","html":"\u003cp class=\"epub-calibre1\">爱既这样轻盈柔和，那么，你这个小哥哥，\u003c/p>\n","text":"爱既这样轻盈柔和，那么，你这个小哥哥，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00192","html":"\u003cp class=\"epub-calibre1\">却为什么，把它看作是沉重得难以负荷？\u003c/p>\n","text":"却为什么，把它看作是沉重得难以负荷？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00193","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00194","html":"\u003cp class=\"epub-calibre1\">“难道你会无端爱上了自己的面孔？\u003c/p>\n","text":"“难道你会无端爱上了自己的面孔？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00195","html":"\u003cp class=\"epub-calibre1\">难道你的右手会抓住了左手谈情？\u003c/p>\n","text":"难道你的右手会抓住了左手谈情？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00196","html":"\u003cp class=\"epub-calibre1\">那样，你只好自爱自，自弃自，一场空，\u003c/p>\n","text":"那样，你只好自爱自，自弃自，一场空，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00197","html":"\u003cp class=\"epub-calibre1\">自陷自设的情网，自怨解脱不可能。\u003c/p>\n","text":"自陷自设的情网，自怨解脱不可能。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00198","html":"\u003cp class=\"epub-calibre1\">那耳喀索斯\u003ca id=\"epub-part0043-w001\">\u003c/a>\u003ca href=\"#epub-part0043-m001\" data-source-anchor=\"m001\">\u003csup class=\"epub-calibre13\">[1]\u003c/sup>\u003c/a>就这样自己作了自己的爱宠，\u003c/p>\n","text":"那耳喀索斯[1]就这样自己作了自己的爱宠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00199","html":"\u003cp class=\"epub-calibre1\">后来还为吻泉水中自己的影子送了命。\u003c/p>\n","text":"后来还为吻泉水中自己的影子送了命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00200","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00201","html":"\u003cp class=\"epub-calibre1\">“蜡炬点起光明来，珠翠盛饰增仪态，\u003c/p>\n","text":"“蜡炬点起光明来，珠翠盛饰增仪态，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00202","html":"\u003cp class=\"epub-calibre1\">珍馐美味为适口，绮年玉貌宜欢爱，\u003c/p>\n","text":"珍馐美味为适口，绮年玉貌宜欢爱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00203","html":"\u003cp class=\"epub-calibre1\">欲嗅芳芬芳馨折，欲采果实果树栽。\u003c/p>\n","text":"欲嗅芳芬芳馨折，欲采果实果树栽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00204","html":"\u003cp class=\"epub-calibre1\">生而只为己，辜负天地好生的本怀。\u003c/p>\n","text":"生而只为己，辜负天地好生的本怀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00205","html":"\u003cp class=\"epub-calibre1\">种因种生，种复生种，天生丽质也无例外；\u003c/p>\n","text":"种因种生，种复生种，天生丽质也无例外；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00206","html":"\u003cp class=\"epub-calibre1\">父母生了你，你再生子女，本你分内应该。\u003c/p>\n","text":"父母生了你，你再生子女，本你分内应该。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00207","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00208","html":"\u003cp class=\"epub-calibre1\">“如果你不繁殖，供给大地生息之资，\u003c/p>\n","text":"“如果你不繁殖，供给大地生息之资，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00209","html":"\u003cp class=\"epub-calibre1\">那大地为什么就该繁殖，供你生息？\u003c/p>\n","text":"那大地为什么就该繁殖，供你生息？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00210","html":"\u003cp class=\"epub-calibre1\">按照自然的大道理，你必须留后嗣：\u003c/p>\n","text":"按照自然的大道理，你必须留后嗣：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00211","html":"\u003cp class=\"epub-calibre1\">这样，一旦你死去，你仍旧可以不死；\u003c/p>\n","text":"这样，一旦你死去，你仍旧可以不死；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00212","html":"\u003cp class=\"epub-calibre1\">这样，你虽然死去，却实在仍旧永存于世：\u003c/p>\n","text":"这样，你虽然死去，却实在仍旧永存于世：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00213","html":"\u003cp class=\"epub-calibre1\">因为有和你一样的生命，永远延续不止。”\u003c/p>\n","text":"因为有和你一样的生命，永远延续不止。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00214","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00215","html":"\u003cp class=\"epub-calibre1\">说到这里，害单思的爱神津津汗湿，\u003c/p>\n","text":"说到这里，害单思的爱神津津汗湿，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00216","html":"\u003cp class=\"epub-calibre1\">因为他们躺的地方，阴影已经渐移。\u003c/p>\n","text":"因为他们躺的地方，阴影已经渐移。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00217","html":"\u003cp class=\"epub-calibre1\">日神在中午正热的时候，也有倦意，\u003c/p>\n","text":"日神在中午正热的时候，也有倦意，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00218","html":"\u003cp class=\"epub-calibre1\">眼里冒火，看着下方这对男顽女痴。\u003c/p>\n","text":"眼里冒火，看着下方这对男顽女痴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00219","html":"\u003cp class=\"epub-calibre1\">他恨不得阿都尼能替他把车马来驾驶，\u003c/p>\n","text":"他恨不得阿都尼能替他把车马来驾驶，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00220","html":"\u003cp class=\"epub-calibre1\">自己却像阿都尼，在爱神的香怀里偎倚。\u003c/p>\n","text":"自己却像阿都尼，在爱神的香怀里偎倚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00221","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00222","html":"\u003cp class=\"epub-calibre1\">这时候，阿都尼心烦意厌，身懒体慵；\u003c/p>\n","text":"这时候，阿都尼心烦意厌，身懒体慵；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00223","html":"\u003cp class=\"epub-calibre1\">满眼都是不快活，一脸全是不高兴；\u003c/p>\n","text":"满眼都是不快活，一脸全是不高兴；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00224","html":"\u003cp class=\"epub-calibre1\">紧锁眉头，眯得一双秀目朦朦胧胧；\u003c/p>\n","text":"紧锁眉头，眯得一双秀目朦朦胧胧；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00225","html":"\u003cp class=\"epub-calibre1\">像云雾满空，遮断了蓝蔚，迷迷蒙蒙。\u003c/p>\n","text":"像云雾满空，遮断了蓝蔚，迷迷蒙蒙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00226","html":"\u003cp class=\"epub-calibre1\">他阴郁地喊，“别再什么情不情！我不爱听。\u003c/p>\n","text":"他阴郁地喊，“别再什么情不情！我不爱听。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00227","html":"\u003cp class=\"epub-calibre1\">太阳晒到了我脸上来了，我得活动活动。”\u003c/p>\n","text":"太阳晒到了我脸上来了，我得活动活动。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00228","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00229","html":"\u003cp class=\"epub-calibre1\">“哎呀，”维纳斯喊道，“你年纪轻，心可真狠，\u003c/p>\n","text":"“哎呀，”维纳斯喊道，“你年纪轻，心可真狠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00230","html":"\u003cp class=\"epub-calibre1\">居然用这样毫无道理的借口图脱身！\u003c/p>\n","text":"居然用这样毫无道理的借口图脱身！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00231","html":"\u003cp class=\"epub-calibre1\">我要吹出像天风的气，叫它习习成阵，\u003c/p>\n","text":"我要吹出像天风的气，叫它习习成阵，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00232","html":"\u003cp class=\"epub-calibre1\">把要西去的红日，扇得清冷冷、凉森森。\u003c/p>\n","text":"把要西去的红日，扇得清冷冷、凉森森。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00233","html":"\u003cp class=\"epub-calibre1\">我要用头发把你遮住，叫它沉沉生幽阴。\u003c/p>\n","text":"我要用头发把你遮住，叫它沉沉生幽阴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00234","html":"\u003cp class=\"epub-calibre1\">如果头发也晒着了，我就用眼泪把它淋。\u003c/p>\n","text":"如果头发也晒着了，我就用眼泪把它淋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00235","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00236","html":"\u003cp class=\"epub-calibre1\">“天上照耀的太阳虽然正是最热之时，\u003c/p>\n","text":"“天上照耀的太阳虽然正是最热之时，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00237","html":"\u003cp class=\"epub-calibre1\">但是我却也给你把它完全都遮住。\u003c/p>\n","text":"但是我却也给你把它完全都遮住。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00238","html":"\u003cp class=\"epub-calibre1\">太阳的火对我并没有什么不舒服。\u003c/p>\n","text":"太阳的火对我并没有什么不舒服。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00239","html":"\u003cp class=\"epub-calibre1\">使我如燃欲焚的火本从你眼里射出。\u003c/p>\n","text":"使我如燃欲焚的火本从你眼里射出。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00240","html":"\u003cp class=\"epub-calibre1\">我若不是长生不死，那我这副柔肠媚骨，\u003c/p>\n","text":"我若不是长生不死，那我这副柔肠媚骨，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00241","html":"\u003cp class=\"epub-calibre1\">早就要在天上人间二火之间，遭到焚如。\u003c/p>\n","text":"早就要在天上人间二火之间，遭到焚如。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00242","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00243","html":"\u003cp class=\"epub-calibre1\">“难道你的心真正比石还顽，比铁还硬？\u003c/p>\n","text":"“难道你的心真正比石还顽，比铁还硬？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00244","html":"\u003cp class=\"epub-calibre1\">石经雨滴也会磨损，铁经火炼也能熔。\u003c/p>\n","text":"石经雨滴也会磨损，铁经火炼也能熔。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00245","html":"\u003cp class=\"epub-calibre1\">莫非你不是妇人生，竟连爱情都不懂？\u003c/p>\n","text":"莫非你不是妇人生，竟连爱情都不懂？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00246","html":"\u003cp class=\"epub-calibre1\">也不知道爱不见答，能给人多大苦痛？\u003c/p>\n","text":"也不知道爱不见答，能给人多大苦痛？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00247","html":"\u003cp class=\"epub-calibre1\">哎哟，如果你妈也会像你这样冥顽无情，\u003c/p>\n","text":"哎哟，如果你妈也会像你这样冥顽无情，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00248","html":"\u003cp class=\"epub-calibre1\">那她到死都要孤零，你就没有机会下生。\u003c/p>\n","text":"那她到死都要孤零，你就没有机会下生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00249","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00250","html":"\u003cp class=\"epub-calibre1\">“我是不是神，竟会叫你这样鄙视厌恨？\u003c/p>\n","text":"“我是不是神，竟会叫你这样鄙视厌恨？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00251","html":"\u003cp class=\"epub-calibre1\">我对你求爱，里面会含什么危险成分？\u003c/p>\n","text":"我对你求爱，里面会含什么危险成分？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00252","html":"\u003cp class=\"epub-calibre1\">不过区区一吻，难道会于你双唇有损？\u003c/p>\n","text":"不过区区一吻，难道会于你双唇有损？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00253","html":"\u003cp class=\"epub-calibre1\">说呀，好人，说好听的，否则不敢有劳您。\u003c/p>\n","text":"说呀，好人，说好听的，否则不敢有劳您。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00254","html":"\u003cp class=\"epub-calibre1\">我只求你一吻，我回敬你，也决不过一吻。\u003c/p>\n","text":"我只求你一吻，我回敬你，也决不过一吻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00255","html":"\u003cp class=\"epub-calibre1\">你若愿我接个双吻，那另一吻就算利润。\u003c/p>\n","text":"你若愿我接个双吻，那另一吻就算利润。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00256","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00257","html":"\u003cp class=\"epub-calibre1\">“呸！不喘气的画中人物，冰冷冷的顽石，\u003c/p>\n","text":"“呸！不喘气的画中人物，冰冷冷的顽石，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00258","html":"\u003cp class=\"epub-calibre1\">装潢涂饰的偶像，冥顽不灵的死形体，\u003c/p>\n","text":"装潢涂饰的偶像，冥顽不灵的死形体，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00259","html":"\u003cp class=\"epub-calibre1\">精妙工致的雕刻，却原来中看不中吃。\u003c/p>\n","text":"精妙工致的雕刻，却原来中看不中吃。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00260","html":"\u003cp class=\"epub-calibre1\">样子虽然像人，却不像妇人所生所育。\u003c/p>\n","text":"样子虽然像人，却不像妇人所生所育。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00261","html":"\u003cp class=\"epub-calibre1\">你并不是个男子，虽然面貌也像个男子；\u003c/p>\n","text":"你并不是个男子，虽然面貌也像个男子；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00262","html":"\u003cp class=\"epub-calibre1\">因为男子对于接吻，求之不得，哪会畏避？”\u003c/p>\n","text":"因为男子对于接吻，求之不得，哪会畏避？”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00263","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00264","html":"\u003cp class=\"epub-calibre1\">这话说完，烦躁把她娓娓的语声咽断，\u003c/p>\n","text":"这话说完，烦躁把她娓娓的语声咽断，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00265","html":"\u003cp class=\"epub-calibre1\">越来越强烈的爱，激动得她有口难言。\u003c/p>\n","text":"越来越强烈的爱，激动得她有口难言。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00266","html":"\u003cp class=\"epub-calibre1\">她脸发烧、眼冒火，一齐喷出满腹幽怨。\u003c/p>\n","text":"她脸发烧、眼冒火，一齐喷出满腹幽怨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00267","html":"\u003cp class=\"epub-calibre1\">风情月债本归她管，自家公案却难办。\u003c/p>\n","text":"风情月债本归她管，自家公案却难办。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00268","html":"\u003cp class=\"epub-calibre1\">她一会嗫嚅欲开口，一会又涕泗流满面，\u003c/p>\n","text":"她一会嗫嚅欲开口，一会又涕泗流满面，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00269","html":"\u003cp class=\"epub-calibre1\">另一会就哽噎得要说的话打断难接连。\u003c/p>\n","text":"另一会就哽噎得要说的话打断难接连。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00270","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00271","html":"\u003cp class=\"epub-calibre1\">她有时摇自己的头，又有时拉他的手，\u003c/p>\n","text":"她有时摇自己的头，又有时拉他的手，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00272","html":"\u003cp class=\"epub-calibre1\">有时往他脸上瞧，又有时就往地上瞅，\u003c/p>\n","text":"有时往他脸上瞧，又有时就往地上瞅，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00273","html":"\u003cp class=\"epub-calibre1\">另有时就像箍住了一般，用力把他搂。\u003c/p>\n","text":"另有时就像箍住了一般，用力把他搂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00274","html":"\u003cp class=\"epub-calibre1\">她愿把他老这样搂，他却要她放他走。\u003c/p>\n","text":"她愿把他老这样搂，他却要她放他走。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00275","html":"\u003cp class=\"epub-calibre1\">他在她怀里硬挣强夺想要脱身的时候，\u003c/p>\n","text":"他在她怀里硬挣强夺想要脱身的时候，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00276","html":"\u003cp class=\"epub-calibre1\">她就把百合般的纤指一个一个紧紧扣。\u003c/p>\n","text":"她就把百合般的纤指一个一个紧紧扣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00277","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00278","html":"\u003cp class=\"epub-calibre1\">“心肝，”她说，“我既筑起这一道象牙围篱，\u003c/p>\n","text":"“心肝，”她说，“我既筑起这一道象牙围篱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00279","html":"\u003cp class=\"epub-calibre1\">把你这样在里面团团围定，紧紧圈起，\u003c/p>\n","text":"把你这样在里面团团围定，紧紧圈起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00280","html":"\u003cp class=\"epub-calibre1\">那我就是你的苑囿，你就是我的幼麑。\u003c/p>\n","text":"那我就是你的苑囿，你就是我的幼麑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00281","html":"\u003cp class=\"epub-calibre1\">那里有山有溪，可供你随意食宿游息。\u003c/p>\n","text":"那里有山有溪，可供你随意食宿游息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00282","html":"\u003cp class=\"epub-calibre1\">先到双唇咀嚼吮吸，如果那儿水枯山瘠，\u003c/p>\n","text":"先到双唇咀嚼吮吸，如果那儿水枯山瘠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00283","html":"\u003cp class=\"epub-calibre1\">再往下面游去，那儿有清泉涓涓草萋萋。\u003c/p>\n","text":"再往下面游去，那儿有清泉涓涓草萋萋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00284","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00285","html":"\u003cp class=\"epub-calibre1\">“这座囿里水草又丰美，游息又可意，\u003c/p>\n","text":"“这座囿里水草又丰美，游息又可意，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00286","html":"\u003cp class=\"epub-calibre1\">低谷有绿茵芊绵，平坡有密树阴翳，\u003c/p>\n","text":"低谷有绿茵芊绵，平坡有密树阴翳，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00287","html":"\u003cp class=\"epub-calibre1\">丛灌蒙茸交叶暗，丘阜圆圆微坟起，\u003c/p>\n","text":"丛灌蒙茸交叶暗，丘阜圆圆微坟起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00288","html":"\u003cp class=\"epub-calibre1\">给你又遮断了狂风，又挡住了暴雨。\u003c/p>\n","text":"给你又遮断了狂风，又挡住了暴雨。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00289","html":"\u003cp class=\"epub-calibre1\">苑囿既然这样美，那你为什么不作幼麑？\u003c/p>\n","text":"苑囿既然这样美，那你为什么不作幼麑？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00290","html":"\u003cp class=\"epub-calibre1\">纵有千条犬吠声狂，都决不能惊扰了你。”\u003c/p>\n","text":"纵有千条犬吠声狂，都决不能惊扰了你。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00291","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00292","html":"\u003cp class=\"epub-calibre1\">他听了这话微微一笑，好像表示鄙夷，\u003c/p>\n","text":"他听了这话微微一笑，好像表示鄙夷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00293","html":"\u003cp class=\"epub-calibre1\">于是他腮上，两个迷人的小酒窝现出；\u003c/p>\n","text":"于是他腮上，两个迷人的小酒窝现出；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00294","html":"\u003cp class=\"epub-calibre1\">那两个小圆坑儿，本是“爱”的精心绝艺，\u003c/p>\n","text":"那两个小圆坑儿，本是“爱”的精心绝艺，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00295","html":"\u003cp class=\"epub-calibre1\">为的自己遭不幸，能有个简单的坟墓。\u003c/p>\n","text":"为的自己遭不幸，能有个简单的坟墓。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00296","html":"\u003cp class=\"epub-calibre1\">但实在说来，他既然是“爱”，那他所在之处，\u003c/p>\n","text":"但实在说来，他既然是“爱”，那他所在之处，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00297","html":"\u003cp class=\"epub-calibre1\">就不会有死亡：这种情况他早预见先知。\u003c/p>\n","text":"就不会有死亡：这种情况他早预见先知。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00298","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00299","html":"\u003cp class=\"epub-calibre1\">这两个迷人的小圆窝，迷人的小圆坑，\u003c/p>\n","text":"这两个迷人的小圆窝，迷人的小圆坑，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00300","html":"\u003cp class=\"epub-calibre1\">像张着小嘴，使迷恋的爱后坠入其中。\u003c/p>\n","text":"像张着小嘴，使迷恋的爱后坠入其中。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00301","html":"\u003cp class=\"epub-calibre1\">她早就神志失常了，现在更神志不清；\u003c/p>\n","text":"她早就神志失常了，现在更神志不清；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00302","html":"\u003cp class=\"epub-calibre1\">她头一下就打闷了，又何用两下才成？\u003c/p>\n","text":"她头一下就打闷了，又何用两下才成？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00303","html":"\u003cp class=\"epub-calibre1\">可怜你，爱神，作法自毙，掉进自掘的陷阱，\u003c/p>\n","text":"可怜你，爱神，作法自毙，掉进自掘的陷阱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00304","html":"\u003cp class=\"epub-calibre1\">一死地迷上了对你只表示鄙夷的面孔。\u003c/p>\n","text":"一死地迷上了对你只表示鄙夷的面孔。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00305","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00306","html":"\u003cp class=\"epub-calibre1\">她现在该怎么办？还有什么话没说完？\u003c/p>\n","text":"她现在该怎么办？还有什么话没说完？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00307","html":"\u003cp class=\"epub-calibre1\">话都说完了，她的苦恼却越来越难堪。\u003c/p>\n","text":"话都说完了，她的苦恼却越来越难堪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00308","html":"\u003cp class=\"epub-calibre1\">时光过去了，她爱的那人却归心似箭，\u003c/p>\n","text":"时光过去了，她爱的那人却归心似箭，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00309","html":"\u003cp class=\"epub-calibre1\">从紧缠着他的玉臂中，用力挣脱羁绊。\u003c/p>\n","text":"从紧缠着他的玉臂中，用力挣脱羁绊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00310","html":"\u003cp class=\"epub-calibre1\">“求你，”她喊道，“把情面稍一顾，把心稍一软。”\u003c/p>\n","text":"“求你，”她喊道，“把情面稍一顾，把心稍一软。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00311","html":"\u003cp class=\"epub-calibre1\">他却不管，一跃而起，奔向骏马，想跨雕鞍。\u003c/p>\n","text":"他却不管，一跃而起，奔向骏马，想跨雕鞍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00312","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00313","html":"\u003cp class=\"epub-calibre1\">但是你看，在邻近一丛矮树林子里，\u003c/p>\n","text":"但是你看，在邻近一丛矮树林子里，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00314","html":"\u003cp class=\"epub-calibre1\">有匹捷尼\u003ca id=\"epub-part0043-w002\">\u003c/a>\u003ca href=\"#epub-part0043-m002\" data-source-anchor=\"m002\">\u003csup class=\"epub-calibre13\">[2]\u003c/sup>\u003c/a>骒马，口嫩神骏，精壮少比，\u003c/p>\n","text":"有匹捷尼[2]骒马，口嫩神骏，精壮少比，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00315","html":"\u003cp class=\"epub-calibre1\">瞥见阿都尼的骏骑，正用蹄子刨地，\u003c/p>\n","text":"瞥见阿都尼的骏骑，正用蹄子刨地，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00316","html":"\u003cp class=\"epub-calibre1\">就连忙跑出来，气喘吁吁，振鬣长嘶。\u003c/p>\n","text":"就连忙跑出来，气喘吁吁，振鬣长嘶。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00317","html":"\u003cp class=\"epub-calibre1\">那匹马首昂然的骏骑，本来在树上软系，\u003c/p>\n","text":"那匹马首昂然的骏骑，本来在树上软系，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00318","html":"\u003cp class=\"epub-calibre1\">一见了这样，忙扯断缰绳，一直向她跑去。\u003c/p>\n","text":"一见了这样，忙扯断缰绳，一直向她跑去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00319","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00320","html":"\u003cp class=\"epub-calibre1\">他威武地又蹦又踢，又腾跃，又长嘶。\u003c/p>\n","text":"他威武地又蹦又踢，又腾跃，又长嘶。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00321","html":"\u003cp class=\"epub-calibre1\">密织的马肚带，他一迸就两下分离。\u003c/p>\n","text":"密织的马肚带，他一迸就两下分离。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00322","html":"\u003cp class=\"epub-calibre1\">他那硬铁蹄，刬伤了生万物的大地，\u003c/p>\n","text":"他那硬铁蹄，刬伤了生万物的大地，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00323","html":"\u003cp class=\"epub-calibre1\">使地心发出回声，只有天上雷声可比。\u003c/p>\n","text":"使地心发出回声，只有天上雷声可比。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00324","html":"\u003cp class=\"epub-calibre1\">他嘴里的马嚼子，他一咬就都碎得像泥，\u003c/p>\n","text":"他嘴里的马嚼子，他一咬就都碎得像泥，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00325","html":"\u003cp class=\"epub-calibre1\">一下就完全制伏了用来制伏他的东西。\u003c/p>\n","text":"一下就完全制伏了用来制伏他的东西。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00326","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00327","html":"\u003cp class=\"epub-calibre1\">他两耳耸起；编结的长鬣本下垂拂披，\u003c/p>\n","text":"他两耳耸起；编结的长鬣本下垂拂披，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00328","html":"\u003cp class=\"epub-calibre1\">现在却在昂然拱起的长颈上直竖立；\u003c/p>\n","text":"现在却在昂然拱起的长颈上直竖立；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00329","html":"\u003cp class=\"epub-calibre1\">他的鼻子吸进去的，本是清新的空气，\u003c/p>\n","text":"他的鼻子吸进去的，本是清新的空气，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00330","html":"\u003cp class=\"epub-calibre1\">现在却像呼呼的闷炉，喷出一片水汽；\u003c/p>\n","text":"现在却像呼呼的闷炉，喷出一片水汽；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00331","html":"\u003cp class=\"epub-calibre1\">他的眼睛发出像火一般的光，闪烁斜视，\u003c/p>\n","text":"他的眼睛发出像火一般的光，闪烁斜视，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00332","html":"\u003cp class=\"epub-calibre1\">表示他的春心已经大动，情欲已经盛炽。\u003c/p>\n","text":"表示他的春心已经大动，情欲已经盛炽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00333","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00334","html":"\u003cp class=\"epub-calibre1\">他有时细步急蹴，好像要把脚步数；\u003c/p>\n","text":"他有时细步急蹴，好像要把脚步数；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00335","html":"\u003cp class=\"epub-calibre1\">威仪中有温柔含，骄傲中有谦虚露；\u003c/p>\n","text":"威仪中有温柔含，骄傲中有谦虚露；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00336","html":"\u003cp class=\"epub-calibre1\">忽然又半身直举，往前猛跳又猛扑，\u003c/p>\n","text":"忽然又半身直举，往前猛跳又猛扑，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00337","html":"\u003cp class=\"epub-calibre1\">仿佛说，你瞧瞧，我有多么大的气力！\u003c/p>\n","text":"仿佛说，你瞧瞧，我有多么大的气力！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00338","html":"\u003cp class=\"epub-calibre1\">我这是对站在我一旁的骒马显威武，\u003c/p>\n","text":"我这是对站在我一旁的骒马显威武，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00339","html":"\u003cp class=\"epub-calibre1\">好教她眼花缭乱，心生爱慕，作我的俘虏。\u003c/p>\n","text":"好教她眼花缭乱，心生爱慕，作我的俘虏。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00340","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00341","html":"\u003cp class=\"epub-calibre1\">他主人惊讶、忙乱、气愤，他一概不理论。\u003c/p>\n","text":"他主人惊讶、忙乱、气愤，他一概不理论。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00342","html":"\u003cp class=\"epub-calibre1\">他主人用“喂喂，别动！”哄他，他也耳朵沉。\u003c/p>\n","text":"他主人用“喂喂，别动！”哄他，他也耳朵沉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00343","html":"\u003cp class=\"epub-calibre1\">他哪里还管马刺刺得痛，马勒勒得紧？\u003c/p>\n","text":"他哪里还管马刺刺得痛，马勒勒得紧？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00344","html":"\u003cp class=\"epub-calibre1\">他哪里还管马衣是否美，马具是否新？\u003c/p>\n","text":"他哪里还管马衣是否美，马具是否新？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00345","html":"\u003cp class=\"epub-calibre1\">他只见所爱，别的全视而不见，听而不闻。\u003c/p>\n","text":"他只见所爱，别的全视而不见，听而不闻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00346","html":"\u003cp class=\"epub-calibre1\">因为在他那闪烁的眼光里，什么能够可心？\u003c/p>\n","text":"因为在他那闪烁的眼光里，什么能够可心？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00347","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00348","html":"\u003cp class=\"epub-calibre1\">画家若想画一匹骨肉匀停的骏马，\u003c/p>\n","text":"画家若想画一匹骨肉匀停的骏马，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00349","html":"\u003cp class=\"epub-calibre1\">使它比起真的活马来还要增身价，\u003c/p>\n","text":"使它比起真的活马来还要增身价，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00350","html":"\u003cp class=\"epub-calibre1\">那他的手笔，得比天工还精巧伟大，\u003c/p>\n","text":"那他的手笔，得比天工还精巧伟大，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00351","html":"\u003cp class=\"epub-calibre1\">使笔下的死马，远超过自然的活马。\u003c/p>\n","text":"使笔下的死马，远超过自然的活马。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00352","html":"\u003cp class=\"epub-calibre1\">现在这匹马，论起骨骼、色泽、气质、步伐，\u003c/p>\n","text":"现在这匹马，论起骨骼、色泽、气质、步伐，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00353","html":"\u003cp class=\"epub-calibre1\">胜过普通马，像画家的马，胜过天生的马。\u003c/p>\n","text":"胜过普通马，像画家的马，胜过天生的马。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00354","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00355","html":"\u003cp class=\"epub-calibre1\">蹄子圆，骹骨短，距毛蒙茸、丛杂而翩跹，\u003c/p>\n","text":"蹄子圆，骹骨短，距毛蒙茸、丛杂而翩跹，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00356","html":"\u003cp class=\"epub-calibre1\">胸脯阔，眼睛圆，头颅小，鼻孔宽，呼吸便，\u003c/p>\n","text":"胸脯阔，眼睛圆，头颅小，鼻孔宽，呼吸便，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00357","html":"\u003cp class=\"epub-calibre1\">两耳小而尖，头颈昂而弯，四足直而健，\u003c/p>\n","text":"两耳小而尖，头颈昂而弯，四足直而健，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00358","html":"\u003cp class=\"epub-calibre1\">鬣毛稀，尾毛密，皮肤光润，臀部肥又圆；\u003c/p>\n","text":"鬣毛稀，尾毛密，皮肤光润，臀部肥又圆；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00359","html":"\u003cp class=\"epub-calibre1\">看！马所应有的，他没有一样不具备完全，\u003c/p>\n","text":"看！马所应有的，他没有一样不具备完全，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00360","html":"\u003cp class=\"epub-calibre1\">只少个骑马的人，高踞他阔背上的华鞍。\u003c/p>\n","text":"只少个骑马的人，高踞他阔背上的华鞍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00361","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00362","html":"\u003cp class=\"epub-calibre1\">他有时往远处狂蹿，又站住脚回头看，\u003c/p>\n","text":"他有时往远处狂蹿，又站住脚回头看，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00363","html":"\u003cp class=\"epub-calibre1\">于是一根羽毛一战颤，他又往前猛颠。\u003c/p>\n","text":"于是一根羽毛一战颤，他又往前猛颠。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00364","html":"\u003cp class=\"epub-calibre1\">这一颠，都简直想和风争先后，赛快慢。\u003c/p>\n","text":"这一颠，都简直想和风争先后，赛快慢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00365","html":"\u003cp class=\"epub-calibre1\">但是他还是飞，还是跑，没有人敢断言；\u003c/p>\n","text":"但是他还是飞，还是跑，没有人敢断言；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00366","html":"\u003cp class=\"epub-calibre1\">因为劲风正掠着他的尾和鬣，鸣啸呼喊，\u003c/p>\n","text":"因为劲风正掠着他的尾和鬣，鸣啸呼喊，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00367","html":"\u003cp class=\"epub-calibre1\">把他的毛吹得像长翎的翅膀一般翩跹。\u003c/p>\n","text":"把他的毛吹得像长翎的翅膀一般翩跹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00368","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00369","html":"\u003cp class=\"epub-calibre1\">他朝着他的所爱斜视，冲着她长嘶。\u003c/p>\n","text":"他朝着他的所爱斜视，冲着她长嘶。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00370","html":"\u003cp class=\"epub-calibre1\">她也长嘶回报，好像懂得他的心意；\u003c/p>\n","text":"她也长嘶回报，好像懂得他的心意；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00371","html":"\u003cp class=\"epub-calibre1\">又像一般女性，见他求爱，把脸绷起，\u003c/p>\n","text":"又像一般女性，见他求爱，把脸绷起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00372","html":"\u003cp class=\"epub-calibre1\">故意作嫌恶的神气，假装狠心不理；\u003c/p>\n","text":"故意作嫌恶的神气，假装狠心不理；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00373","html":"\u003cp class=\"epub-calibre1\">对他的爱情厌弃，把他炽盛的春情鄙夷。\u003c/p>\n","text":"对他的爱情厌弃，把他炽盛的春情鄙夷。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00374","html":"\u003cp class=\"epub-calibre1\">他从她后面拥抱她，她就用蹄子使劲踢。\u003c/p>\n","text":"他从她后面拥抱她，她就用蹄子使劲踢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00375","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00376","html":"\u003cp class=\"epub-calibre1\">于是他就像个失意的人，抑郁又愁闷，\u003c/p>\n","text":"于是他就像个失意的人，抑郁又愁闷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00377","html":"\u003cp class=\"epub-calibre1\">把尾巴像倒垂的羽缨那样，下拂后臀，\u003c/p>\n","text":"把尾巴像倒垂的羽缨那样，下拂后臀，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00378","html":"\u003cp class=\"epub-calibre1\">给欲火烧得如化的那一部分作覆阴。\u003c/p>\n","text":"给欲火烧得如化的那一部分作覆阴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00379","html":"\u003cp class=\"epub-calibre1\">他又刨地，又愤怒地把苍蝇乱咬一阵。\u003c/p>\n","text":"他又刨地，又愤怒地把苍蝇乱咬一阵。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00380","html":"\u003cp class=\"epub-calibre1\">他的所爱，看见了他春情这样如狂似焚，\u003c/p>\n","text":"他的所爱，看见了他春情这样如狂似焚，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00381","html":"\u003cp class=\"epub-calibre1\">稍露怜心；他也由暴怒渐渐地变为斯文。\u003c/p>\n","text":"稍露怜心；他也由暴怒渐渐地变为斯文。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00382","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00383","html":"\u003cp class=\"epub-calibre1\">他那容易动怒的小主人家想去捉他，\u003c/p>\n","text":"他那容易动怒的小主人家想去捉他，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00384","html":"\u003cp class=\"epub-calibre1\">谁知那未经人骑的骒马，一见害了怕，\u003c/p>\n","text":"谁知那未经人骑的骒马，一见害了怕，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00385","html":"\u003cp class=\"epub-calibre1\">就连忙把他来撇下，惟恐自己被人抓。\u003c/p>\n","text":"就连忙把他来撇下，惟恐自己被人抓。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00386","html":"\u003cp class=\"epub-calibre1\">她前奔，他也后随，把阿都尼单独剩下。\u003c/p>\n","text":"她前奔，他也后随，把阿都尼单独剩下。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00387","html":"\u003cp class=\"epub-calibre1\">疯了一般蹿进树林子里面的是他们俩；\u003c/p>\n","text":"疯了一般蹿进树林子里面的是他们俩；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00388","html":"\u003cp class=\"epub-calibre1\">叫他们撂在后面的是想追他们的老鸦。\u003c/p>\n","text":"叫他们撂在后面的是想追他们的老鸦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00389","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00390","html":"\u003cp class=\"epub-calibre1\">阿都尼气得肚子发胀，一下坐在地上；\u003c/p>\n","text":"阿都尼气得肚子发胀，一下坐在地上；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00391","html":"\u003cp class=\"epub-calibre1\">一面大骂这匹不受拘管的畜生混账。\u003c/p>\n","text":"一面大骂这匹不受拘管的畜生混账。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00392","html":"\u003cp class=\"epub-calibre1\">现在又来了一次于爱后有利的时光，\u003c/p>\n","text":"现在又来了一次于爱后有利的时光，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00393","html":"\u003cp class=\"epub-calibre1\">可以用甜言蜜语给她的单思帮帮忙。\u003c/p>\n","text":"可以用甜言蜜语给她的单思帮帮忙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00394","html":"\u003cp class=\"epub-calibre1\">因为恋爱的人总说，若不让“爱”借重舌簧，\u003c/p>\n","text":"因为恋爱的人总说，若不让“爱”借重舌簧，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00395","html":"\u003cp class=\"epub-calibre1\">就是叫它受比平常三倍多的委屈冤枉。\u003c/p>\n","text":"就是叫它受比平常三倍多的委屈冤枉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00396","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00397","html":"\u003cp class=\"epub-calibre1\">一条河流完全壅障，水就流得更猖狂；\u003c/p>\n","text":"一条河流完全壅障，水就流得更猖狂；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00398","html":"\u003cp class=\"epub-calibre1\">一个闷炉丝毫不通气，火就着得更旺；\u003c/p>\n","text":"一个闷炉丝毫不通气，火就着得更旺；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00399","html":"\u003cp class=\"epub-calibre1\">密不告人的愁烦，也正是同样的情况；\u003c/p>\n","text":"密不告人的愁烦，也正是同样的情况；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00400","html":"\u003cp class=\"epub-calibre1\">自由畅谈，可以使“爱”的烈焰稍稍低降。\u003c/p>\n","text":"自由畅谈，可以使“爱”的烈焰稍稍低降。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00401","html":"\u003cp class=\"epub-calibre1\">但是如果一旦“爱”的辩护士都一声不响，\u003c/p>\n","text":"但是如果一旦“爱”的辩护士都一声不响，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00402","html":"\u003cp class=\"epub-calibre1\">那案中人除了伤心而亡，还有什么希望？\u003c/p>\n","text":"那案中人除了伤心而亡，还有什么希望？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00403","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00404","html":"\u003cp class=\"epub-calibre1\">他看见她来到，脸上另一阵又红又烧，\u003c/p>\n","text":"他看见她来到，脸上另一阵又红又烧，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00405","html":"\u003cp class=\"epub-calibre1\">就像要灭的炭火，让微风一下又吹着。\u003c/p>\n","text":"就像要灭的炭火，让微风一下又吹着。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00406","html":"\u003cp class=\"epub-calibre1\">他用帽子把他蹙着的额连忙遮盖牢，\u003c/p>\n","text":"他用帽子把他蹙着的额连忙遮盖牢，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00407","html":"\u003cp class=\"epub-calibre1\">眼睛瞅着无情的地，心里不知怎么好，\u003c/p>\n","text":"眼睛瞅着无情的地，心里不知怎么好，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00408","html":"\u003cp class=\"epub-calibre1\">也不管她还是并未近前，还是已经挨靠。\u003c/p>\n","text":"也不管她还是并未近前，还是已经挨靠。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00409","html":"\u003cp class=\"epub-calibre1\">因为他眼里的她，只值得从眼角那儿瞧。\u003c/p>\n","text":"因为他眼里的她，只值得从眼角那儿瞧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00410","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00411","html":"\u003cp class=\"epub-calibre1\">留心细看她那样匆匆忙忙，悄悄冥冥，\u003c/p>\n","text":"留心细看她那样匆匆忙忙，悄悄冥冥，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00412","html":"\u003cp class=\"epub-calibre1\">去就那顽梗任性的孩童，真是一奇景。\u003c/p>\n","text":"去就那顽梗任性的孩童，真是一奇景。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00413","html":"\u003cp class=\"epub-calibre1\">你看她脸上忽白忽红，红掩白、白减红，\u003c/p>\n","text":"你看她脸上忽白忽红，红掩白、白减红，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00414","html":"\u003cp class=\"epub-calibre1\">满心的冲突，都表现在脸色的斗争中。\u003c/p>\n","text":"满心的冲突，都表现在脸色的斗争中。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00415","html":"\u003cp class=\"epub-calibre1\">这一瞬间，她脸上还是灰白的；稍待片顷，\u003c/p>\n","text":"这一瞬间，她脸上还是灰白的；稍待片顷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00416","html":"\u003cp class=\"epub-calibre1\">它就要射出红火来，和天上的闪电相同。\u003c/p>\n","text":"它就要射出红火来，和天上的闪电相同。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00417","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00418","html":"\u003cp class=\"epub-calibre1\">她现在已经来到了他坐的那个地点，\u003c/p>\n","text":"她现在已经来到了他坐的那个地点，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00419","html":"\u003cp class=\"epub-calibre1\">就像卑躬屈节的男爱人，跪在他面前，\u003c/p>\n","text":"就像卑躬屈节的男爱人，跪在他面前，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00420","html":"\u003cp class=\"epub-calibre1\">用纤手把他的帽子，轻轻地撩在一边，\u003c/p>\n","text":"用纤手把他的帽子，轻轻地撩在一边，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00421","html":"\u003cp class=\"epub-calibre1\">另一只柔嫩的手，就摸他更柔嫩的脸。\u003c/p>\n","text":"另一只柔嫩的手，就摸他更柔嫩的脸。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00422","html":"\u003cp class=\"epub-calibre1\">他这脸经她一摸，就有她的纤指印出现，\u003c/p>\n","text":"他这脸经她一摸，就有她的纤指印出现，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00423","html":"\u003cp class=\"epub-calibre1\">像初雪松又软，一触就留下了斑深痕浅。\u003c/p>\n","text":"像初雪松又软，一触就留下了斑深痕浅。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00424","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00425","html":"\u003cp class=\"epub-calibre1\">哦，他们眼光交锋，多生动的一场战争！\u003c/p>\n","text":"哦，他们眼光交锋，多生动的一场战争！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00426","html":"\u003cp class=\"epub-calibre1\">她老满眼含情，望着他的眼哀求恳请。\u003c/p>\n","text":"她老满眼含情，望着他的眼哀求恳请。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00427","html":"\u003cp class=\"epub-calibre1\">他就满眼含嗔，好像没看见她的眼睛。\u003c/p>\n","text":"他就满眼含嗔，好像没看见她的眼睛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00428","html":"\u003cp class=\"epub-calibre1\">她老用眼传情，他就老用眼鄙视这情。\u003c/p>\n","text":"她老用眼传情，他就老用眼鄙视这情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00429","html":"\u003cp class=\"epub-calibre1\">这一出哑剧，一幕一幕地演得分分明明；\u003c/p>\n","text":"这一出哑剧，一幕一幕地演得分分明明；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00430","html":"\u003cp class=\"epub-calibre1\">她泪如雨倾，作剧中陪衬，更使剧情生动。\u003c/p>\n","text":"她泪如雨倾，作剧中陪衬，更使剧情生动。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00431","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00432","html":"\u003cp class=\"epub-calibre1\">她现在极尽温柔地握住了他的手，\u003c/p>\n","text":"她现在极尽温柔地握住了他的手，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00433","html":"\u003cp class=\"epub-calibre1\">就好像白雪筑起围墙，把百合拘囚；\u003c/p>\n","text":"就好像白雪筑起围墙，把百合拘囚；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00434","html":"\u003cp class=\"epub-calibre1\">又好像石膏圆箍，把象牙密裹紧扣。\u003c/p>\n","text":"又好像石膏圆箍，把象牙密裹紧扣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00435","html":"\u003cp class=\"epub-calibre1\">这样白的朋友，碰到这样白的对头！\u003c/p>\n","text":"这样白的朋友，碰到这样白的对头！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00436","html":"\u003cp class=\"epub-calibre1\">这场“美”与“美”的斗争，一面猛攻，一面严守，\u003c/p>\n","text":"这场“美”与“美”的斗争，一面猛攻，一面严守，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00437","html":"\u003cp class=\"epub-calibre1\">就好像两只银色的鸽子，喙交喙，口接口。\u003c/p>\n","text":"就好像两只银色的鸽子，喙交喙，口接口。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00438","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00439","html":"\u003cp class=\"epub-calibre1\">她的思想传达器官——喉舌又开始动作：\u003c/p>\n","text":"她的思想传达器官——喉舌又开始动作：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00440","html":"\u003cp class=\"epub-calibre1\">“哦，滚滚尘寰中，你这最秀美的过客，\u003c/p>\n","text":"“哦，滚滚尘寰中，你这最秀美的过客，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00441","html":"\u003cp class=\"epub-calibre1\">我恨不得我能变成你，你能变成我；\u003c/p>\n","text":"我恨不得我能变成你，你能变成我；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00442","html":"\u003cp class=\"epub-calibre1\">我心完好似你心，你心伤如我心多；\u003c/p>\n","text":"我心完好似你心，你心伤如我心多；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00443","html":"\u003cp class=\"epub-calibre1\">那样，你只报我以和颜，我便助你得解脱，\u003c/p>\n","text":"那样，你只报我以和颜，我便助你得解脱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00444","html":"\u003cp class=\"epub-calibre1\">即使我得因此舍上命，我也一定无吝色。”\u003c/p>\n","text":"即使我得因此舍上命，我也一定无吝色。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00445","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00446","html":"\u003cp class=\"epub-calibre1\">“还我的手，”他说，“你摸我的手什么道理？”\u003c/p>\n","text":"“还我的手，”他说，“你摸我的手什么道理？”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00447","html":"\u003cp class=\"epub-calibre1\">“还我的心，”她说，“那我就把你的手还你。\u003c/p>\n","text":"“还我的心，”她说，“那我就把你的手还你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00448","html":"\u003cp class=\"epub-calibre1\">不然，你的心就要使我的心变成铁石，\u003c/p>\n","text":"不然，你的心就要使我的心变成铁石，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00449","html":"\u003cp class=\"epub-calibre1\">变成铁石，它就要不理会动人的叹息，\u003c/p>\n","text":"变成铁石，它就要不理会动人的叹息，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00450","html":"\u003cp class=\"epub-calibre1\">这样，情人的呻吟，我也要听来绝不在意，\u003c/p>\n","text":"这样，情人的呻吟，我也要听来绝不在意，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00451","html":"\u003cp class=\"epub-calibre1\">因为阿都尼的心已使我的心变得狠戾。”\u003c/p>\n","text":"因为阿都尼的心已使我的心变得狠戾。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00452","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00453","html":"\u003cp class=\"epub-calibre1\">“你要点脸，”他喊道，“快放开手，别再纠缠。\u003c/p>\n","text":"“你要点脸，”他喊道，“快放开手，别再纠缠。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00454","html":"\u003cp class=\"epub-calibre1\">我这一天的乐事，算是全完。马也不见。\u003c/p>\n","text":"我这一天的乐事，算是全完。马也不见。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00455","html":"\u003cp class=\"epub-calibre1\">都是你，闹得我和马，两下里都不照面；\u003c/p>\n","text":"都是你，闹得我和马，两下里都不照面；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00456","html":"\u003cp class=\"epub-calibre1\">我说，你走开，单留下我在这儿想一番。\u003c/p>\n","text":"我说，你走开，单留下我在这儿想一番。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00457","html":"\u003cp class=\"epub-calibre1\">因为我一心一意、满头满脑、急忙地盘算，\u003c/p>\n","text":"因为我一心一意、满头满脑、急忙地盘算，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00458","html":"\u003cp class=\"epub-calibre1\">都想要叫我那匹骏马从骒马那儿回转。”\u003c/p>\n","text":"都想要叫我那匹骏马从骒马那儿回转。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00459","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00460","html":"\u003cp class=\"epub-calibre1\">“你的马，”她答道，“该走的路就是这一条，\u003c/p>\n","text":"“你的马，”她答道，“该走的路就是这一条，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00461","html":"\u003cp class=\"epub-calibre1\">因为他这是对柔情的强烈攻势回报。\u003c/p>\n","text":"因为他这是对柔情的强烈攻势回报。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00462","html":"\u003cp class=\"epub-calibre1\">‘爱’和炭相同，烧起来，得设法叫它冷却。\u003c/p>\n","text":"‘爱’和炭相同，烧起来，得设法叫它冷却。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00463","html":"\u003cp class=\"epub-calibre1\">让它任意着，那它就要把一颗心烧焦。\u003c/p>\n","text":"让它任意着，那它就要把一颗心烧焦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00464","html":"\u003cp class=\"epub-calibre1\">大海有崖岸，热烈的爱却没有边界范牢。\u003c/p>\n","text":"大海有崖岸，热烈的爱却没有边界范牢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00465","html":"\u003cp class=\"epub-calibre1\">所以你的马跑掉，并非奇事，不值得惊扰。\u003c/p>\n","text":"所以你的马跑掉，并非奇事，不值得惊扰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00466","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00467","html":"\u003cp class=\"epub-calibre1\">“他系在树上时，看着多么像驽骀下驷，\u003c/p>\n","text":"“他系在树上时，看着多么像驽骀下驷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00468","html":"\u003cp class=\"epub-calibre1\">仿佛一根皮带，就能治得他老老实实。\u003c/p>\n","text":"仿佛一根皮带，就能治得他老老实实。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00469","html":"\u003cp class=\"epub-calibre1\">但他一见他的所爱——青春应有的美侣，\u003c/p>\n","text":"但他一见他的所爱——青春应有的美侣，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00470","html":"\u003cp class=\"epub-calibre1\">他并没把那不足道的束缚放在眼里。\u003c/p>\n","text":"他并没把那不足道的束缚放在眼里。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00471","html":"\u003cp class=\"epub-calibre1\">他从他那拱起的颈上把缰绳一下甩去，\u003c/p>\n","text":"他从他那拱起的颈上把缰绳一下甩去，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00472","html":"\u003cp class=\"epub-calibre1\">使他的头、口、颈、胸，都脱去羁绊，获得舒适。\u003c/p>\n","text":"使他的头、口、颈、胸，都脱去羁绊，获得舒适。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00473","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00474","html":"\u003cp class=\"epub-calibre1\">“一个人看到他的所爱，裸体榻上横陈，\u003c/p>\n","text":"“一个人看到他的所爱，裸体榻上横陈，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00475","html":"\u003cp class=\"epub-calibre1\">雪白的床单，都比不上她肤色的玉润，\u003c/p>\n","text":"雪白的床单，都比不上她肤色的玉润，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00476","html":"\u003cp class=\"epub-calibre1\">那他岂肯只用饕餮的眼睛饱餐一顿，\u003c/p>\n","text":"那他岂肯只用饕餮的眼睛饱餐一顿，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00477","html":"\u003cp class=\"epub-calibre1\">而别的感官却能不同样地情不自禁？\u003c/p>\n","text":"而别的感官却能不同样地情不自禁？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00478","html":"\u003cp class=\"epub-calibre1\">冰雪凛冽，天气严寒，哪会有人过于小心，\u003c/p>\n","text":"冰雪凛冽，天气严寒，哪会有人过于小心，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00479","html":"\u003cp class=\"epub-calibre1\">见了热火，却远远躲着，不敢靠前去亲近？\u003c/p>\n","text":"见了热火，却远远躲着，不敢靠前去亲近？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00480","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00481","html":"\u003cp class=\"epub-calibre1\">“因此我的小哥哥，你不该骂骏马顽劣。\u003c/p>\n","text":"“因此我的小哥哥，你不该骂骏马顽劣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00482","html":"\u003cp class=\"epub-calibre1\">我反倒恳切地要求你跟他好好地学，\u003c/p>\n","text":"我反倒恳切地要求你跟他好好地学，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00483","html":"\u003cp class=\"epub-calibre1\">不要对送到门上来的快乐随便轻蔑。\u003c/p>\n","text":"不要对送到门上来的快乐随便轻蔑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00484","html":"\u003cp class=\"epub-calibre1\">他的行动就是你的模范，无须我喋喋。\u003c/p>\n","text":"他的行动就是你的模范，无须我喋喋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00485","html":"\u003cp class=\"epub-calibre1\">哦，你要学着恋爱；这个玩意简单又明确，\u003c/p>\n","text":"哦，你要学着恋爱；这个玩意简单又明确，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00486","html":"\u003cp class=\"epub-calibre1\">它还是一下学会了，就永远不会再忘却。”\u003c/p>\n","text":"它还是一下学会了，就永远不会再忘却。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00487","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00488","html":"\u003cp class=\"epub-calibre1\">“我不懂恋爱是什么，我也不想学，”他说，\u003c/p>\n","text":"“我不懂恋爱是什么，我也不想学，”他说，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00489","html":"\u003cp class=\"epub-calibre1\">“只有野猪我才爱，因为它能供我猎获。\u003c/p>\n","text":"“只有野猪我才爱，因为它能供我猎获。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00490","html":"\u003cp class=\"epub-calibre1\">我不要跟你强借，也不要你强借给我。\u003c/p>\n","text":"我不要跟你强借，也不要你强借给我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00491","html":"\u003cp class=\"epub-calibre1\">我对于‘爱’也爱，但只爱暴露它的龌龊。\u003c/p>\n","text":"我对于‘爱’也爱，但只爱暴露它的龌龊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00492","html":"\u003cp class=\"epub-calibre1\">因为我听人说，它只能跟‘死亡’讨点生活，\u003c/p>\n","text":"因为我听人说，它只能跟‘死亡’讨点生活，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00493","html":"\u003cp class=\"epub-calibre1\">它也哭也笑，但只一呼吸间，便一生度过。\u003c/p>\n","text":"它也哭也笑，但只一呼吸间，便一生度过。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00494","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00495","html":"\u003cp class=\"epub-calibre1\">“衣服还未裁好做完，有谁能就去穿？\u003c/p>\n","text":"“衣服还未裁好做完，有谁能就去穿？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00496","html":"\u003cp class=\"epub-calibre1\">半个瓣还没长出来的花，谁肯赏玩？\u003c/p>\n","text":"半个瓣还没长出来的花，谁肯赏玩？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00497","html":"\u003cp class=\"epub-calibre1\">生长发育的东西如受伤，虽只半点，\u003c/p>\n","text":"生长发育的东西如受伤，虽只半点，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00498","html":"\u003cp class=\"epub-calibre1\">都要盛年萎谢，不会长得璀璨绚烂。\u003c/p>\n","text":"都要盛年萎谢，不会长得璀璨绚烂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00499","html":"\u003cp class=\"epub-calibre1\">马驹年幼时，就叫他驮人负物，引重致远，\u003c/p>\n","text":"马驹年幼时，就叫他驮人负物，引重致远，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00500","html":"\u003cp class=\"epub-calibre1\">那他就要精力耗减，永远不能长得壮健。\u003c/p>\n","text":"那他就要精力耗减，永远不能长得壮健。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00501","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00502","html":"\u003cp class=\"epub-calibre1\">“我的手叫你攥得痛起来，咱们得分开。\u003c/p>\n","text":"“我的手叫你攥得痛起来，咱们得分开。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00503","html":"\u003cp class=\"epub-calibre1\">不要再瞎谈什么叫情，胡说什么叫爱。\u003c/p>\n","text":"不要再瞎谈什么叫情，胡说什么叫爱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00504","html":"\u003cp class=\"epub-calibre1\">你顶好撤围；我的心不能投降任屠宰；\u003c/p>\n","text":"你顶好撤围；我的心不能投降任屠宰；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00505","html":"\u003cp class=\"epub-calibre1\">它不会给向它猛攻的‘爱’，把城门开开。\u003c/p>\n","text":"它不会给向它猛攻的‘爱’，把城门开开。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00506","html":"\u003cp class=\"epub-calibre1\">请收起誓言、谀词和装出来的热泪满腮，\u003c/p>\n","text":"请收起誓言、谀词和装出来的热泪满腮，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00507","html":"\u003cp class=\"epub-calibre1\">因为它们在坚定的心里，不能当作炮台。”\u003c/p>\n","text":"因为它们在坚定的心里，不能当作炮台。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00508","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00509","html":"\u003cp class=\"epub-calibre1\">“怎么，你还会出声？”她说，“舌头还会活动？\u003c/p>\n","text":"“怎么，你还会出声？”她说，“舌头还会活动？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00510","html":"\u003cp class=\"epub-calibre1\">其实顶好你没有舌头，或者我两耳聋。\u003c/p>\n","text":"其实顶好你没有舌头，或者我两耳聋。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00511","html":"\u003cp class=\"epub-calibre1\">你像美人鱼这样一说，叫我加倍伤情。\u003c/p>\n","text":"你像美人鱼这样一说，叫我加倍伤情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00512","html":"\u003cp class=\"epub-calibre1\">我本来就心里沉重，听你这话更沉重。\u003c/p>\n","text":"我本来就心里沉重，听你这话更沉重。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00513","html":"\u003cp class=\"epub-calibre1\">和谐中有龃龉，一派仙乐却奏得极难听。\u003c/p>\n","text":"和谐中有龃龉，一派仙乐却奏得极难听。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00514","html":"\u003cp class=\"epub-calibre1\">耳边极美的乐声，却引起心里深创剧痛。\u003c/p>\n","text":"耳边极美的乐声，却引起心里深创剧痛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00515","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00516","html":"\u003cp class=\"epub-calibre1\">“假设说，我只有两只耳朵，却没有眼睛，\u003c/p>\n","text":"“假设说，我只有两只耳朵，却没有眼睛，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00517","html":"\u003cp class=\"epub-calibre1\">那你内在的美，我目虽不见，耳却能听。\u003c/p>\n","text":"那你内在的美，我目虽不见，耳却能听。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00518","html":"\u003cp class=\"epub-calibre1\">若我两耳聋，那你外表的美，如能看清，\u003c/p>\n","text":"若我两耳聋，那你外表的美，如能看清，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00519","html":"\u003cp class=\"epub-calibre1\">也照样能把我一切感受的器官打动。\u003c/p>\n","text":"也照样能把我一切感受的器官打动。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00520","html":"\u003cp class=\"epub-calibre1\">如果我也无耳、也无目，只有触觉还余剩，\u003c/p>\n","text":"如果我也无耳、也无目，只有触觉还余剩，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00521","html":"\u003cp class=\"epub-calibre1\">那我只凭触觉，也要对你产生热烈的爱情。\u003c/p>\n","text":"那我只凭触觉，也要对你产生热烈的爱情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00522","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00523","html":"\u003cp class=\"epub-calibre1\">“再假设，我连触觉也全都失去了功能，\u003c/p>\n","text":"“再假设，我连触觉也全都失去了功能，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00524","html":"\u003cp class=\"epub-calibre1\">听也听不见，摸也摸不着，看也看不清，\u003c/p>\n","text":"听也听不见，摸也摸不着，看也看不清，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00525","html":"\u003cp class=\"epub-calibre1\">单单剩下嗅觉一种，孤独地把职务行，\u003c/p>\n","text":"单单剩下嗅觉一种，孤独地把职务行，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00526","html":"\u003cp class=\"epub-calibre1\">那我对你，仍旧一样要有强烈的爱情。\u003c/p>\n","text":"那我对你，仍旧一样要有强烈的爱情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00527","html":"\u003cp class=\"epub-calibre1\">因你的脸发秀挺英，霞蔚云蒸，华升精腾，\u003c/p>\n","text":"因你的脸发秀挺英，霞蔚云蒸，华升精腾，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00528","html":"\u003cp class=\"epub-calibre1\">有芬芳气息喷涌，叫人嗅着，爱情油然生。\u003c/p>\n","text":"有芬芳气息喷涌，叫人嗅着，爱情油然生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00529","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00530","html":"\u003cp class=\"epub-calibre1\">“但你对这四种感官，既这样抚养滋息，\u003c/p>\n","text":"“但你对这四种感官，既这样抚养滋息，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00531","html":"\u003cp class=\"epub-calibre1\">那你对于味觉，该是怎样的华筵盛席？\u003c/p>\n","text":"那你对于味觉，该是怎样的华筵盛席？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00532","html":"\u003cp class=\"epub-calibre1\">它们难道不想要客无散日，杯无空时？\u003c/p>\n","text":"它们难道不想要客无散日，杯无空时？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00533","html":"\u003cp class=\"epub-calibre1\">难道不想要‘疑虑’，用双簧锁把门锁起，\u003c/p>\n","text":"难道不想要‘疑虑’，用双簧锁把门锁起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00534","html":"\u003cp class=\"epub-calibre1\">好叫‘嫉妒’，那不受欢迎、爱闹脾气的东西，\u003c/p>\n","text":"好叫‘嫉妒’，那不受欢迎、爱闹脾气的东西，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00535","html":"\u003cp class=\"epub-calibre1\">别偷偷地溜了进来，搅扰了它们的宴集？”\u003c/p>\n","text":"别偷偷地溜了进来，搅扰了它们的宴集？”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00536","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00537","html":"\u003cp class=\"epub-calibre1\">他那两扇鲜红的门——嘴唇——又一次敞开，\u003c/p>\n","text":"他那两扇鲜红的门——嘴唇——又一次敞开，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00538","html":"\u003cp class=\"epub-calibre1\">叫他要说的话，甜蜜地畅通不受阻碍；\u003c/p>\n","text":"叫他要说的话，甜蜜地畅通不受阻碍；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00539","html":"\u003cp class=\"epub-calibre1\">那就像清晓刚刚来，就出现了红云彩，\u003c/p>\n","text":"那就像清晓刚刚来，就出现了红云彩，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00540","html":"\u003cp class=\"epub-calibre1\">预示那海上船要沉没，陆上雨要成灾；\u003c/p>\n","text":"预示那海上船要沉没，陆上雨要成灾；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00541","html":"\u003cp class=\"epub-calibre1\">预示那鸟儿要受苦难，牧羊人要受损害；\u003c/p>\n","text":"预示那鸟儿要受苦难，牧羊人要受损害；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00542","html":"\u003cp class=\"epub-calibre1\">牧牛人和牛群要遭疾飘和狂飙的破坏。\u003c/p>\n","text":"牧牛人和牛群要遭疾飘和狂飙的破坏。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00543","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00544","html":"\u003cp class=\"epub-calibre1\">这种不吉的预兆，她留心注意早看到。\u003c/p>\n","text":"这种不吉的预兆，她留心注意早看到。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00545","html":"\u003cp class=\"epub-calibre1\">那就像暴雨之前，狂风一时停止怒号；\u003c/p>\n","text":"那就像暴雨之前，狂风一时停止怒号；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00546","html":"\u003cp class=\"epub-calibre1\">又像狼把牙一露，就知道他要开口嗥；\u003c/p>\n","text":"又像狼把牙一露，就知道他要开口嗥；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00547","html":"\u003cp class=\"epub-calibre1\">又像浆果一裂，就知道有黑水往外冒。\u003c/p>\n","text":"又像浆果一裂，就知道有黑水往外冒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00548","html":"\u003cp class=\"epub-calibre1\">枪子出了膛，还不是有人遭殃，要被打倒？\u003c/p>\n","text":"枪子出了膛，还不是有人遭殃，要被打倒？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00549","html":"\u003cp class=\"epub-calibre1\">所以，他还没开口，他的心思她就已猜着。\u003c/p>\n","text":"所以，他还没开口，他的心思她就已猜着。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00550","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00551","html":"\u003cp class=\"epub-calibre1\">她一看他这样的神色，便往地上跌倒。\u003c/p>\n","text":"她一看他这样的神色，便往地上跌倒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00552","html":"\u003cp class=\"epub-calibre1\">神色能使“爱”活人间，也能使“爱”赴阴曹，\u003c/p>\n","text":"神色能使“爱”活人间，也能使“爱”赴阴曹，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00553","html":"\u003cp class=\"epub-calibre1\">眉头一皱创伤生，嫣然一笑就创伤好。\u003c/p>\n","text":"眉头一皱创伤生，嫣然一笑就创伤好。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00554","html":"\u003cp class=\"epub-calibre1\">伤心人得到“爱”这样治疗，得说福气高。\u003c/p>\n","text":"伤心人得到“爱”这样治疗，得说福气高。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00555","html":"\u003cp class=\"epub-calibre1\">那个傻孩子，一见她这样，认为她真不妙，\u003c/p>\n","text":"那个傻孩子，一见她这样，认为她真不妙，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00556","html":"\u003cp class=\"epub-calibre1\">就用手拍她灰白的脸，直拍到脸生红潮。\u003c/p>\n","text":"就用手拍她灰白的脸，直拍到脸生红潮。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00557","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00558","html":"\u003cp class=\"epub-calibre1\">他满腹惊讶，刚打好的主意也变了卦，\u003c/p>\n","text":"他满腹惊讶，刚打好的主意也变了卦，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00559","html":"\u003cp class=\"epub-calibre1\">因为，他本来想对她来一番切责痛骂。\u003c/p>\n","text":"因为，他本来想对她来一番切责痛骂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00560","html":"\u003cp class=\"epub-calibre1\">但是狡黠的“爱”，却极巧妙地制人先发。\u003c/p>\n","text":"但是狡黠的“爱”，却极巧妙地制人先发。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00561","html":"\u003cp class=\"epub-calibre1\">我给“机警”祝福，因为它这样维护了她！\u003c/p>\n","text":"我给“机警”祝福，因为它这样维护了她！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00562","html":"\u003cp class=\"epub-calibre1\">她躺在草地上，呼吸停止，好像一下羞杀。\u003c/p>\n","text":"她躺在草地上，呼吸停止，好像一下羞杀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00563","html":"\u003cp class=\"epub-calibre1\">他给她渡气、接唇，到了她苏醒过来才罢。\u003c/p>\n","text":"他给她渡气、接唇，到了她苏醒过来才罢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00564","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00565","html":"\u003cp class=\"epub-calibre1\">他轻轻弯她的手指，使劲按她的脉息，\u003c/p>\n","text":"他轻轻弯她的手指，使劲按她的脉息，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00566","html":"\u003cp class=\"epub-calibre1\">他微微拍她的两腮，慢慢搓她的鼻子，\u003c/p>\n","text":"他微微拍她的两腮，慢慢搓她的鼻子，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00567","html":"\u003cp class=\"epub-calibre1\">轻轻揉她的嘴唇：总之想尽千方百计，\u003c/p>\n","text":"轻轻揉她的嘴唇：总之想尽千方百计，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00568","html":"\u003cp class=\"epub-calibre1\">要把他的狠心给她的创伤医疗救治。\u003c/p>\n","text":"要把他的狠心给她的创伤医疗救治。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00569","html":"\u003cp class=\"epub-calibre1\">他吻她。她呢，一见大喜，就乐得将计就计，\u003c/p>\n","text":"他吻她。她呢，一见大喜，就乐得将计就计，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00570","html":"\u003cp class=\"epub-calibre1\">老老实实地躺在那儿，好叫他吻个不止。\u003c/p>\n","text":"老老实实地躺在那儿，好叫他吻个不止。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00571","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00572","html":"\u003cp class=\"epub-calibre1\">原先的愁苦阴沉似夜，现已变为白日。\u003c/p>\n","text":"原先的愁苦阴沉似夜，现已变为白日。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00573","html":"\u003cp class=\"epub-calibre1\">她那碧波欲流的眼，似碧牖轻轻开启。\u003c/p>\n","text":"她那碧波欲流的眼，似碧牖轻轻开启。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00574","html":"\u003cp class=\"epub-calibre1\">那就像辉煌的朝日，穿着耀眼的新衣，\u003c/p>\n","text":"那就像辉煌的朝日，穿着耀眼的新衣，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00575","html":"\u003cp class=\"epub-calibre1\">使晨光欢畅，使大地呈现出一片喜气：\u003c/p>\n","text":"使晨光欢畅，使大地呈现出一片喜气：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00576","html":"\u003cp class=\"epub-calibre1\">就这样，如同丽日映辉得太空明朗美丽，\u003c/p>\n","text":"就这样，如同丽日映辉得太空明朗美丽，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00577","html":"\u003cp class=\"epub-calibre1\">她那一双美目，映辉得她的脸明艳美丽。\u003c/p>\n","text":"她那一双美目，映辉得她的脸明艳美丽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00578","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00579","html":"\u003cp class=\"epub-calibre1\">她的眼光，射到他那白净无须的脸上，\u003c/p>\n","text":"她的眼光，射到他那白净无须的脸上，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00580","html":"\u003cp class=\"epub-calibre1\">好像她的眼光，都从他那儿来的一样。\u003c/p>\n","text":"好像她的眼光，都从他那儿来的一样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00581","html":"\u003cp class=\"epub-calibre1\">若非他两眼因不悦而紧蹙，稍显微茫，\u003c/p>\n","text":"若非他两眼因不悦而紧蹙，稍显微茫，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00582","html":"\u003cp class=\"epub-calibre1\">从来没有过这样四只眼睛，交辉争光。\u003c/p>\n","text":"从来没有过这样四只眼睛，交辉争光。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00583","html":"\u003cp class=\"epub-calibre1\">她的眼，由于隔着晶莹的泪而放出光芒，\u003c/p>\n","text":"她的眼，由于隔着晶莹的泪而放出光芒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00584","html":"\u003cp class=\"epub-calibre1\">所以就好像夜晚月映清塘看来的景象。\u003c/p>\n","text":"所以就好像夜晚月映清塘看来的景象。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00585","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00586","html":"\u003cp class=\"epub-calibre1\">“哦！”她说，“我身在何方？在人间还是天上？\u003c/p>\n","text":"“哦！”她说，“我身在何方？在人间还是天上？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00587","html":"\u003cp class=\"epub-calibre1\">我在海里遭淹没？还是在火里受烧伤？\u003c/p>\n","text":"我在海里遭淹没？还是在火里受烧伤？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00588","html":"\u003cp class=\"epub-calibre1\">现是何时光？清晨明朗？还是昏夜漫长？\u003c/p>\n","text":"现是何时光？清晨明朗？还是昏夜漫长？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00589","html":"\u003cp class=\"epub-calibre1\">我还是一心想要活？还是一意愿死亡？\u003c/p>\n","text":"我还是一心想要活？还是一意愿死亡？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00590","html":"\u003cp class=\"epub-calibre1\">我刚才还活着，但却活得比死了还凄惶；\u003c/p>\n","text":"我刚才还活着，但却活得比死了还凄惶；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00591","html":"\u003cp class=\"epub-calibre1\">后来又死了，但在死中却得了生的欢畅。\u003c/p>\n","text":"后来又死了，但在死中却得了生的欢畅。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00592","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00593","html":"\u003cp class=\"epub-calibre1\">“你曾叫我死掉，我求你再叫我死一遭。\u003c/p>\n","text":"“你曾叫我死掉，我求你再叫我死一遭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00594","html":"\u003cp class=\"epub-calibre1\">你的眼受了恶师——你的狠心——的指教，\u003c/p>\n","text":"你的眼受了恶师——你的狠心——的指教，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00595","html":"\u003cp class=\"epub-calibre1\">只会把鄙夷的样子现，不屑的神色表，\u003c/p>\n","text":"只会把鄙夷的样子现，不屑的神色表，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00596","html":"\u003cp class=\"epub-calibre1\">因此我这颗可怜的心，你早已杀害了。\u003c/p>\n","text":"因此我这颗可怜的心，你早已杀害了。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00597","html":"\u003cp class=\"epub-calibre1\">我这一双眼，本来是女后我忠实的向导，\u003c/p>\n","text":"我这一双眼，本来是女后我忠实的向导，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00598","html":"\u003cp class=\"epub-calibre1\">如无你的嘴唇，也早就离开了我的躯壳。\u003c/p>\n","text":"如无你的嘴唇，也早就离开了我的躯壳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00599","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00600","html":"\u003cp class=\"epub-calibre1\">“为你双唇救了我，我祝它们长相接！\u003c/p>\n","text":"“为你双唇救了我，我祝它们长相接！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00601","html":"\u003cp class=\"epub-calibre1\">我祝它们鲜红永不褪，新装永不卸！\u003c/p>\n","text":"我祝它们鲜红永不褪，新装永不卸！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00602","html":"\u003cp class=\"epub-calibre1\">我祝它们存在时，青春永保无残缺！\u003c/p>\n","text":"我祝它们存在时，青春永保无残缺！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00603","html":"\u003cp class=\"epub-calibre1\">把疫疠从应降大灾的年月中祓除绝。\u003c/p>\n","text":"把疫疠从应降大灾的年月中祓除绝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00604","html":"\u003cp class=\"epub-calibre1\">这样，星象家尽管已把人们的生死判决，\u003c/p>\n","text":"这样，星象家尽管已把人们的生死判决，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00605","html":"\u003cp class=\"epub-calibre1\">你喘的气，却回天旋地，把人命留，瘟疫灭。\u003c/p>\n","text":"你喘的气，却回天旋地，把人命留，瘟疫灭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00606","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00607","html":"\u003cp class=\"epub-calibre1\">“你的香唇，曾在我的柔唇上留下甜印，\u003c/p>\n","text":"“你的香唇，曾在我的柔唇上留下甜印，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00608","html":"\u003cp class=\"epub-calibre1\">要叫这甜印永存，我订任何契约都肯，\u003c/p>\n","text":"要叫这甜印永存，我订任何契约都肯，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00609","html":"\u003cp class=\"epub-calibre1\">即使我得为此而卖身，我也完全甘心，\u003c/p>\n","text":"即使我得为此而卖身，我也完全甘心，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00610","html":"\u003cp class=\"epub-calibre1\">只要你肯出价购买，交易公平信用准。\u003c/p>\n","text":"只要你肯出价购买，交易公平信用准。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00611","html":"\u003cp class=\"epub-calibre1\">成交以后，如果你还怕会有伪币生纠纷，\u003c/p>\n","text":"成交以后，如果你还怕会有伪币生纠纷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00612","html":"\u003cp class=\"epub-calibre1\">那你就把印打上我这火漆般红的嘴唇。\u003c/p>\n","text":"那你就把印打上我这火漆般红的嘴唇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00613","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00614","html":"\u003cp class=\"epub-calibre1\">“你只付吻一千，我的心就永远归你管。\u003c/p>\n","text":"“你只付吻一千，我的心就永远归你管。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00615","html":"\u003cp class=\"epub-calibre1\">你还无须忙，可以一个一个从容清算。\u003c/p>\n","text":"你还无须忙，可以一个一个从容清算。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00616","html":"\u003cp class=\"epub-calibre1\">在我嘴上触一千下就成，有什么麻烦？\u003c/p>\n","text":"在我嘴上触一千下就成，有什么麻烦？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00617","html":"\u003cp class=\"epub-calibre1\">你能很快就把它们数好，把它们付完。\u003c/p>\n","text":"你能很快就把它们数好，把它们付完。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00618","html":"\u003cp class=\"epub-calibre1\">若到期交不上款，因受罚全数要加一翻，\u003c/p>\n","text":"若到期交不上款，因受罚全数要加一翻，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00619","html":"\u003cp class=\"epub-calibre1\">那也不过两千吻，于你又哪能算得困难？”\u003c/p>\n","text":"那也不过两千吻，于你又哪能算得困难？”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00620","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00621","html":"\u003cp class=\"epub-calibre1\">“美丽的爱后，”他说道，“你若有意和我好，\u003c/p>\n","text":"“美丽的爱后，”他说道，“你若有意和我好，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00622","html":"\u003cp class=\"epub-calibre1\">而我对你却老害臊，请原谅我年纪少。\u003c/p>\n","text":"而我对你却老害臊，请原谅我年纪少。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00623","html":"\u003cp class=\"epub-calibre1\">我还未经人道，所以别想和我通人道。\u003c/p>\n","text":"我还未经人道，所以别想和我通人道。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00624","html":"\u003cp class=\"epub-calibre1\">任何渔夫，都要把刚生出来的鱼苗饶；\u003c/p>\n","text":"任何渔夫，都要把刚生出来的鱼苗饶；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00625","html":"\u003cp class=\"epub-calibre1\">熟了的梅子自己就会掉，青梅却长得牢；\u003c/p>\n","text":"熟了的梅子自己就会掉，青梅却长得牢；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00626","html":"\u003cp class=\"epub-calibre1\">若是不熟就摘了，它会酸得你皱上眉梢。\u003c/p>\n","text":"若是不熟就摘了，它会酸得你皱上眉梢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00627","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00628","html":"\u003cp class=\"epub-calibre1\">“你瞧，人间的安慰者太阳，已脚步疲劳，\u003c/p>\n","text":"“你瞧，人间的安慰者太阳，已脚步疲劳，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00629","html":"\u003cp class=\"epub-calibre1\">在西方把他一天炎热的工作结束了；\u003c/p>\n","text":"在西方把他一天炎热的工作结束了；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00630","html":"\u003cp class=\"epub-calibre1\">夜的先行夜猫也尖声叫；天已经不早；\u003c/p>\n","text":"夜的先行夜猫也尖声叫；天已经不早；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00631","html":"\u003cp class=\"epub-calibre1\">牛和羊都已经进了圈，众鸟也都归了巢；\u003c/p>\n","text":"牛和羊都已经进了圈，众鸟也都归了巢；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00632","html":"\u003cp class=\"epub-calibre1\">乌黑的云彩天空罩，昼光淡淡，夕阴浩浩。\u003c/p>\n","text":"乌黑的云彩天空罩，昼光淡淡，夕阴浩浩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00633","html":"\u003cp class=\"epub-calibre1\">这都说，咱们道晚安而分手的时候来到。\u003c/p>\n","text":"这都说，咱们道晚安而分手的时候来到。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00634","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00635","html":"\u003cp class=\"epub-calibre1\">“现在我对你说声晚安，你也把礼还。\u003c/p>\n","text":"“现在我对你说声晚安，你也把礼还。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00636","html":"\u003cp class=\"epub-calibre1\">你若听我这句话，我就不吝一吻甜。”\u003c/p>\n","text":"你若听我这句话，我就不吝一吻甜。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00637","html":"\u003cp class=\"epub-calibre1\">于是她说了声晚安。他也果不食言，\u003c/p>\n","text":"于是她说了声晚安。他也果不食言，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00638","html":"\u003cp class=\"epub-calibre1\">未说再见，就使分离的甜蜜酬答实现。\u003c/p>\n","text":"未说再见，就使分离的甜蜜酬答实现。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00639","html":"\u003cp class=\"epub-calibre1\">她用两臂把他的脖子温柔地紧围力缠。\u003c/p>\n","text":"她用两臂把他的脖子温柔地紧围力缠。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00640","html":"\u003cp class=\"epub-calibre1\">于是成一体的他和她，成一个的脸和脸。\u003c/p>\n","text":"于是成一体的他和她，成一个的脸和脸。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00641","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00642","html":"\u003cp class=\"epub-calibre1\">他都没法儿喘气，就把身子力挣脱离，\u003c/p>\n","text":"他都没法儿喘气，就把身子力挣脱离，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00643","html":"\u003cp class=\"epub-calibre1\">挪开了红似珊瑚的唇，醇如玉醴的气。\u003c/p>\n","text":"挪开了红似珊瑚的唇，醇如玉醴的气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00644","html":"\u003cp class=\"epub-calibre1\">她那饥渴的嘴，早把美味吸了个十足；\u003c/p>\n","text":"她那饥渴的嘴，早把美味吸了个十足；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00645","html":"\u003cp class=\"epub-calibre1\">但虽淋漓尽致，她仍抱怨，说不过点滴。\u003c/p>\n","text":"但虽淋漓尽致，她仍抱怨，说不过点滴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00646","html":"\u003cp class=\"epub-calibre1\">他们一个饿得要晕去，一个饱得要胀死，\u003c/p>\n","text":"他们一个饿得要晕去，一个饱得要胀死，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00647","html":"\u003cp class=\"epub-calibre1\">这样，唇和唇一块紧粘，他和她一齐倒地。\u003c/p>\n","text":"这样，唇和唇一块紧粘，他和她一齐倒地。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00648","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00649","html":"\u003cp class=\"epub-calibre1\">强烈的情欲，把不再抵抗的牺牲捉住。\u003c/p>\n","text":"强烈的情欲，把不再抵抗的牺牲捉住。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00650","html":"\u003cp class=\"epub-calibre1\">她饕餮一般地大嚼，还是老嫌不满足。\u003c/p>\n","text":"她饕餮一般地大嚼，还是老嫌不满足。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00651","html":"\u003cp class=\"epub-calibre1\">她的唇乘胜征服，他的唇就听命屈服；\u003c/p>\n","text":"她的唇乘胜征服，他的唇就听命屈服；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00652","html":"\u003cp class=\"epub-calibre1\">战胜者不论要多少赎金，他都不吝惜。\u003c/p>\n","text":"战胜者不论要多少赎金，他都不吝惜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00653","html":"\u003cp class=\"epub-calibre1\">她那贪似鹰鹯的欲望，把价提得冲天起，\u003c/p>\n","text":"她那贪似鹰鹯的欲望，把价提得冲天起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00654","html":"\u003cp class=\"epub-calibre1\">不吸尽他唇上丰富的宝藏，就不能停止。\u003c/p>\n","text":"不吸尽他唇上丰富的宝藏，就不能停止。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00655","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00656","html":"\u003cp class=\"epub-calibre1\">她一旦尝到了战利品的甜蜜滋味，\u003c/p>\n","text":"她一旦尝到了战利品的甜蜜滋味，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00657","html":"\u003cp class=\"epub-calibre1\">就开始不顾一切，凶猛地暴掠穷追。\u003c/p>\n","text":"就开始不顾一切，凶猛地暴掠穷追。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00658","html":"\u003cp class=\"epub-calibre1\">她的脸腾腾冒热气，她的血滚滚沸。\u003c/p>\n","text":"她的脸腾腾冒热气，她的血滚滚沸。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00659","html":"\u003cp class=\"epub-calibre1\">不计一切的情欲，竟叫她放胆畅为！\u003c/p>\n","text":"不计一切的情欲，竟叫她放胆畅为！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00660","html":"\u003cp class=\"epub-calibre1\">把所有的一切都付诸流水，把理性击退；\u003c/p>\n","text":"把所有的一切都付诸流水，把理性击退；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00661","html":"\u003cp class=\"epub-calibre1\">忘了什么是害羞脸红，什么是名誉尽毁。\u003c/p>\n","text":"忘了什么是害羞脸红，什么是名誉尽毁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00662","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00663","html":"\u003cp class=\"epub-calibre1\">他叫她紧搂得又热闷、又困顿、又要晕，\u003c/p>\n","text":"他叫她紧搂得又热闷、又困顿、又要晕，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00664","html":"\u003cp class=\"epub-calibre1\">就像野鸟，抚弄得太久了，变得很驯顺；\u003c/p>\n","text":"就像野鸟，抚弄得太久了，变得很驯顺；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00665","html":"\u003cp class=\"epub-calibre1\">又像捷足的小鹿，被人穷追，精疲力尽；\u003c/p>\n","text":"又像捷足的小鹿，被人穷追，精疲力尽；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00666","html":"\u003cp class=\"epub-calibre1\">又像闹脾气的孩子，哄好了，不再耍浑。\u003c/p>\n","text":"又像闹脾气的孩子，哄好了，不再耍浑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00667","html":"\u003cp class=\"epub-calibre1\">所以他现在伏伏贴贴，不抵抗，也不逃遁。\u003c/p>\n","text":"所以他现在伏伏贴贴，不抵抗，也不逃遁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00668","html":"\u003cp class=\"epub-calibre1\">她虽不能尽所欲，却也尽所能大嚼一顿。\u003c/p>\n","text":"她虽不能尽所欲，却也尽所能大嚼一顿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00669","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00670","html":"\u003cp class=\"epub-calibre1\">黄蜡不论冻得多么硬，经抟弄都要熔，\u003c/p>\n","text":"黄蜡不论冻得多么硬，经抟弄都要熔，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00671","html":"\u003cp class=\"epub-calibre1\">最后只轻轻一按，还能变成万状千形。\u003c/p>\n","text":"最后只轻轻一按，还能变成万状千形。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00672","html":"\u003cp class=\"epub-calibre1\">本来无望的事，大胆尝试，往往能成功。\u003c/p>\n","text":"本来无望的事，大胆尝试，往往能成功。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00673","html":"\u003cp class=\"epub-calibre1\">特别在情场中，得寸进尺，更得凭勇猛。\u003c/p>\n","text":"特别在情场中，得寸进尺，更得凭勇猛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00674","html":"\u003cp class=\"epub-calibre1\">爱并不是一来就晕，和灰脸的懦夫相同；\u003c/p>\n","text":"爱并不是一来就晕，和灰脸的懦夫相同；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00675","html":"\u003cp class=\"epub-calibre1\">它的对象越扎手，它的进攻就该越起劲。\u003c/p>\n","text":"它的对象越扎手，它的进攻就该越起劲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00676","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00677","html":"\u003cp class=\"epub-calibre1\">他原先皱眉时，哦，她若轻易畏难而止，\u003c/p>\n","text":"他原先皱眉时，哦，她若轻易畏难而止，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00678","html":"\u003cp class=\"epub-calibre1\">那她就永也不会从他嘴上吸到玉醴。\u003c/p>\n","text":"那她就永也不会从他嘴上吸到玉醴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00679","html":"\u003cp class=\"epub-calibre1\">爱人一定不要叫疾言厉色击退驱逐。\u003c/p>\n","text":"爱人一定不要叫疾言厉色击退驱逐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00680","html":"\u003cp class=\"epub-calibre1\">玫瑰还不是一样被采撷，尽管它有刺？\u003c/p>\n","text":"玫瑰还不是一样被采撷，尽管它有刺？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00681","html":"\u003cp class=\"epub-calibre1\">即便用二十把锁，把“美”牢牢地锁在密室，\u003c/p>\n","text":"即便用二十把锁，把“美”牢牢地锁在密室，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00682","html":"\u003cp class=\"epub-calibre1\">“爱”也照旧能把锁个个打开而斩关直入。\u003c/p>\n","text":"“爱”也照旧能把锁个个打开而斩关直入。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00683","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00684","html":"\u003cp class=\"epub-calibre1\">为了把他赦宥，就势难再把他强拘留；\u003c/p>\n","text":"为了把他赦宥，就势难再把他强拘留；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00685","html":"\u003cp class=\"epub-calibre1\">原来那可怜的傻孩子，直哀求放他走；\u003c/p>\n","text":"原来那可怜的傻孩子，直哀求放他走；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00686","html":"\u003cp class=\"epub-calibre1\">因此上她就决定，不再把他硬拽死揪，\u003c/p>\n","text":"因此上她就决定，不再把他硬拽死揪，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00687","html":"\u003cp class=\"epub-calibre1\">和他告别，嘱咐他把她的心好好护守。\u003c/p>\n","text":"和他告别，嘱咐他把她的心好好护守。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00688","html":"\u003cp class=\"epub-calibre1\">因为她指着小爱神的弓作证，赌下大咒，\u003c/p>\n","text":"因为她指着小爱神的弓作证，赌下大咒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00689","html":"\u003cp class=\"epub-calibre1\">说她那颗心，早已牢牢地嵌在他的心头。\u003c/p>\n","text":"说她那颗心，早已牢牢地嵌在他的心头。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00690","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00691","html":"\u003cp class=\"epub-calibre1\">“甜蜜的孩子，”她说，“我今宵凄凉怎生过？\u003c/p>\n","text":"“甜蜜的孩子，”她说，“我今宵凄凉怎生过？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00692","html":"\u003cp class=\"epub-calibre1\">因为，相思折磨我，怎能叫我把两眼？\u003c/p>\n","text":"因为，相思折磨我，怎能叫我把两眼？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00693","html":"\u003cp class=\"epub-calibre1\">爱的主人，你说，明天你可能再见着我？\u003c/p>\n","text":"爱的主人，你说，明天你可能再见着我？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00694","html":"\u003cp class=\"epub-calibre1\">你说能吧，然后再把晤会的时间订妥。”\u003c/p>\n","text":"你说能吧，然后再把晤会的时间订妥。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00695","html":"\u003cp class=\"epub-calibre1\">他对她说，他明天不能和她作幽期密约，\u003c/p>\n","text":"他对她说，他明天不能和她作幽期密约，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00696","html":"\u003cp class=\"epub-calibre1\">因为他打算着和几个朋友把野猪猎获。\u003c/p>\n","text":"因为他打算着和几个朋友把野猪猎获。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00697","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00698","html":"\u003cp class=\"epub-calibre1\">“野猪！”她失声一喊；跟着她脸上的娇艳，\u003c/p>\n","text":"“野猪！”她失声一喊；跟着她脸上的娇艳，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00699","html":"\u003cp class=\"epub-calibre1\">一下就让灰白掩，好像薄纱明、轻罗软，\u003c/p>\n","text":"一下就让灰白掩，好像薄纱明、轻罗软，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00700","html":"\u003cp class=\"epub-calibre1\">笼得玫瑰羞晕浅。他的话叫她心惊战；\u003c/p>\n","text":"笼得玫瑰羞晕浅。他的话叫她心惊战；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00701","html":"\u003cp class=\"epub-calibre1\">她连忙用两臂，把他的脖子款搂紧挽，\u003c/p>\n","text":"她连忙用两臂，把他的脖子款搂紧挽，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00702","html":"\u003cp class=\"epub-calibre1\">她一面这样缠，一面带着他用力往后扳。\u003c/p>\n","text":"她一面这样缠，一面带着他用力往后扳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00703","html":"\u003cp class=\"epub-calibre1\">于是只见，她仰卧地上，他就伏在她胸前。\u003c/p>\n","text":"于是只见，她仰卧地上，他就伏在她胸前。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00704","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00705","html":"\u003cp class=\"epub-calibre1\">她现在才算真正来到风月寨、花柳阵。\u003c/p>\n","text":"她现在才算真正来到风月寨、花柳阵。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00706","html":"\u003cp class=\"epub-calibre1\">主将已经跨上了坐骑，要酣战把命拚。\u003c/p>\n","text":"主将已经跨上了坐骑，要酣战把命拚。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00707","html":"\u003cp class=\"epub-calibre1\">谁知道她所想的，只是空幻，难以成真。\u003c/p>\n","text":"谁知道她所想的，只是空幻，难以成真。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00708","html":"\u003cp class=\"epub-calibre1\">他虽已骑在她身上，却不肯挥鞭前进。\u003c/p>\n","text":"他虽已骑在她身上，却不肯挥鞭前进。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00709","html":"\u003cp class=\"epub-calibre1\">只弄得她的苦恼比坦塔罗斯\u003ca id=\"epub-part0043-w003\">\u003c/a>\u003ca href=\"#epub-part0043-m003\" data-source-anchor=\"m003\">\u003csup class=\"epub-calibre13\">[3]\u003c/sup>\u003c/a>还更难忍。\u003c/p>\n","text":"只弄得她的苦恼比坦塔罗斯[3]还更难忍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00710","html":"\u003cp class=\"epub-calibre1\">原来她虽到了乐土，却得不到乐趣半分。\u003c/p>\n","text":"原来她虽到了乐土，却得不到乐趣半分。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00711","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00712","html":"\u003cp class=\"epub-calibre1\">可怜的鸟，看见了画的葡萄，以假为真，\u003c/p>\n","text":"可怜的鸟，看见了画的葡萄，以假为真，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00713","html":"\u003cp class=\"epub-calibre1\">弄得眼睛胀得要破，肚子却饿得难忍。\u003c/p>\n","text":"弄得眼睛胀得要破，肚子却饿得难忍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00714","html":"\u003cp class=\"epub-calibre1\">她就像这样，爱不见答，因而苦恼万分，\u003c/p>\n","text":"她就像这样，爱不见答，因而苦恼万分，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00715","html":"\u003cp class=\"epub-calibre1\">如同那鸟，瞅着水果，却可望而不可近。\u003c/p>\n","text":"如同那鸟，瞅着水果，却可望而不可近。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00716","html":"\u003cp class=\"epub-calibre1\">她在他身上，既得不到她要的那股热劲，\u003c/p>\n","text":"她在他身上，既得不到她要的那股热劲，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00717","html":"\u003cp class=\"epub-calibre1\">她就不断地和他接吻，把他来撩拨勾引。\u003c/p>\n","text":"她就不断地和他接吻，把他来撩拨勾引。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00718","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00719","html":"\u003cp class=\"epub-calibre1\">但都不成。好爱后，这可不能随你的心。\u003c/p>\n","text":"但都不成。好爱后，这可不能随你的心。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00720","html":"\u003cp class=\"epub-calibre1\">一切可以尝试的办法，她都已经用尽。\u003c/p>\n","text":"一切可以尝试的办法，她都已经用尽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00721","html":"\u003cp class=\"epub-calibre1\">她费了如许唇舌，本应得到更多温存。\u003c/p>\n","text":"她费了如许唇舌，本应得到更多温存。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00722","html":"\u003cp class=\"epub-calibre1\">她是爱神，又正动爱劲，却得不到爱人。\u003c/p>\n","text":"她是爱神，又正动爱劲，却得不到爱人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00723","html":"\u003cp class=\"epub-calibre1\">“得了得了吧，”他说，“快放手。别挤得人要晕。\u003c/p>\n","text":"“得了得了吧，”他说，“快放手。别挤得人要晕。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00724","html":"\u003cp class=\"epub-calibre1\">你这样搂住了我，真毫无道理，绝无原因。”\u003c/p>\n","text":"你这样搂住了我，真毫无道理，绝无原因。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00725","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00726","html":"\u003cp class=\"epub-calibre1\">“如果你没告诉我，说要去把野猪猎获，\u003c/p>\n","text":"“如果你没告诉我，说要去把野猪猎获，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00727","html":"\u003cp class=\"epub-calibre1\">甜蜜的孩子，”她说，“你本来可以早走脱。\u003c/p>\n","text":"甜蜜的孩子，”她说，“你本来可以早走脱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00728","html":"\u003cp class=\"epub-calibre1\">哎呀，你可要当心。我想你这是不懂得，\u003c/p>\n","text":"哎呀，你可要当心。我想你这是不懂得，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00729","html":"\u003cp class=\"epub-calibre1\">用枪扎凶猛的野猪，都会有什么后果。\u003c/p>\n","text":"用枪扎凶猛的野猪，都会有什么后果。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00730","html":"\u003cp class=\"epub-calibre1\">它的牙老剑拔弩张，为的便于往快里磨，\u003c/p>\n","text":"它的牙老剑拔弩张，为的便于往快里磨，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00731","html":"\u003cp class=\"epub-calibre1\">磨快了，好学杀生的屠夫，把屠宰的活作。\u003c/p>\n","text":"磨快了，好学杀生的屠夫，把屠宰的活作。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00732","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00733","html":"\u003cp class=\"epub-calibre1\">“它拱起的背上，有刚鬃硬毛，列戟摆枪，\u003c/p>\n","text":"“它拱起的背上，有刚鬃硬毛，列戟摆枪，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00734","html":"\u003cp class=\"epub-calibre1\">密扎扎地直耸立，叫敌人看着心胆丧。\u003c/p>\n","text":"密扎扎地直耸立，叫敌人看着心胆丧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00735","html":"\u003cp class=\"epub-calibre1\">它的眼似萤火，怒起来便闪烁生光芒。\u003c/p>\n","text":"它的眼似萤火，怒起来便闪烁生光芒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00736","html":"\u003cp class=\"epub-calibre1\">它的嘴专会破坏，到处一掘就是坟圹。\u003c/p>\n","text":"它的嘴专会破坏，到处一掘就是坟圹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00737","html":"\u003cp class=\"epub-calibre1\">它受到了招惹，不论什么它都横冲直撞，\u003c/p>\n","text":"它受到了招惹，不论什么它都横冲直撞，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00738","html":"\u003cp class=\"epub-calibre1\">被它碰上，都要在它弯曲的长牙下身亡。\u003c/p>\n","text":"被它碰上，都要在它弯曲的长牙下身亡。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00739","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00740","html":"\u003cp class=\"epub-calibre1\">“它那肥壮的两膀，也有硬毛刚鬃武装，\u003c/p>\n","text":"“它那肥壮的两膀，也有硬毛刚鬃武装，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00741","html":"\u003cp class=\"epub-calibre1\">厚实坚强，你的枪尖扎不透，也刺不伤。\u003c/p>\n","text":"厚实坚强，你的枪尖扎不透，也刺不伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00742","html":"\u003cp class=\"epub-calibre1\">它那粗而短的脖子，也不容易损毫芒。\u003c/p>\n","text":"它那粗而短的脖子，也不容易损毫芒。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00743","html":"\u003cp class=\"epub-calibre1\">它怒气一发，连狮子它都看得很平常。\u003c/p>\n","text":"它怒气一发，连狮子它都看得很平常。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00744","html":"\u003cp class=\"epub-calibre1\">长着尖刺的荆棘丛，和密接互抱的灌莽，\u003c/p>\n","text":"长着尖刺的荆棘丛，和密接互抱的灌莽，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00745","html":"\u003cp class=\"epub-calibre1\">见它来也害怕，忙分开让路，叫它往前闯。\u003c/p>\n","text":"见它来也害怕，忙分开让路，叫它往前闯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00746","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00747","html":"\u003cp class=\"epub-calibre1\">“你这美貌的面孔，它绝对不知道敬重。\u003c/p>\n","text":"“你这美貌的面孔，它绝对不知道敬重。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00748","html":"\u003cp class=\"epub-calibre1\">虽然爱神的眼睛，对它痛爱、护惜、尊崇。\u003c/p>\n","text":"虽然爱神的眼睛，对它痛爱、护惜、尊崇。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00749","html":"\u003cp class=\"epub-calibre1\">你柔嫩的手、甜美的唇、水汪汪的眼睛，\u003c/p>\n","text":"你柔嫩的手、甜美的唇、水汪汪的眼睛，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00750","html":"\u003cp class=\"epub-calibre1\">完美得世上的人无不惊奇，它却不懂。\u003c/p>\n","text":"完美得世上的人无不惊奇，它却不懂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00751","html":"\u003cp class=\"epub-calibre1\">你若叫它得了手，哎呀，它可要斗狠逞凶！\u003c/p>\n","text":"你若叫它得了手，哎呀，它可要斗狠逞凶！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00752","html":"\u003cp class=\"epub-calibre1\">它要把你的美貌，像地上的草一样乱拱。\u003c/p>\n","text":"它要把你的美貌，像地上的草一样乱拱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00753","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00754","html":"\u003cp class=\"epub-calibre1\">“哦，让它在它那令人恶心的窝里躲着，\u003c/p>\n","text":"“哦，让它在它那令人恶心的窝里躲着，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00755","html":"\u003cp class=\"epub-calibre1\">‘美’和这样的恶魔，绝没有丝毫的瓜葛。\u003c/p>\n","text":"‘美’和这样的恶魔，绝没有丝毫的瓜葛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00756","html":"\u003cp class=\"epub-calibre1\">千万可别成心去和它麻烦，招灾惹祸。\u003c/p>\n","text":"千万可别成心去和它麻烦，招灾惹祸。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00757","html":"\u003cp class=\"epub-calibre1\">一个人听朋友的忠告，只有幸福快活。\u003c/p>\n","text":"一个人听朋友的忠告，只有幸福快活。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00758","html":"\u003cp class=\"epub-calibre1\">你一提起野猪的话来，我还并不是做作，\u003c/p>\n","text":"你一提起野猪的话来，我还并不是做作，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00759","html":"\u003cp class=\"epub-calibre1\">我真替你担惊受怕，吓得全身都直哆嗦。\u003c/p>\n","text":"我真替你担惊受怕，吓得全身都直哆嗦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00760","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00761","html":"\u003cp class=\"epub-calibre1\">“难道你没看见我的脸，一下变得灰白？\u003c/p>\n","text":"“难道你没看见我的脸，一下变得灰白？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00762","html":"\u003cp class=\"epub-calibre1\">难道你没看见我的眼，满含恐惧疑猜？\u003c/p>\n","text":"难道你没看见我的眼，满含恐惧疑猜？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00763","html":"\u003cp class=\"epub-calibre1\">难道我没晕过去，一下就栽倒在尘埃？\u003c/p>\n","text":"难道我没晕过去，一下就栽倒在尘埃？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00764","html":"\u003cp class=\"epub-calibre1\">你不是伏在我怀里？难道你没觉出来，\u003c/p>\n","text":"你不是伏在我怀里？难道你没觉出来，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00765","html":"\u003cp class=\"epub-calibre1\">我的心预知不妙，又跳又蹦，老不能安泰？\u003c/p>\n","text":"我的心预知不妙，又跳又蹦，老不能安泰？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00766","html":"\u003cp class=\"epub-calibre1\">只像地震一样，把在我身上的你都直筛？\u003c/p>\n","text":"只像地震一样，把在我身上的你都直筛？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00767","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00768","html":"\u003cp class=\"epub-calibre1\">“因为，‘爱’所在的心里，有好捣乱的‘妒忌’，\u003c/p>\n","text":"“因为，‘爱’所在的心里，有好捣乱的‘妒忌’，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00769","html":"\u003cp class=\"epub-calibre1\">自称为‘爱’的卫士，给它警戒，把它护持；\u003c/p>\n","text":"自称为‘爱’的卫士，给它警戒，把它护持；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00770","html":"\u003cp class=\"epub-calibre1\">要永远惹起虚惊，要永远煽动起叛逆；\u003c/p>\n","text":"要永远惹起虚惊，要永远煽动起叛逆；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00771","html":"\u003cp class=\"epub-calibre1\">在太平无事的时候，老大呼杀敌、杀敌；\u003c/p>\n","text":"在太平无事的时候，老大呼杀敌、杀敌；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00772","html":"\u003cp class=\"epub-calibre1\">使温存柔和的‘爱’，也把热劲头冷却减低，\u003c/p>\n","text":"使温存柔和的‘爱’，也把热劲头冷却减低，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00773","html":"\u003cp class=\"epub-calibre1\">像凉水和湿气，把腾腾的烈火压制灭熄。\u003c/p>\n","text":"像凉水和湿气，把腾腾的烈火压制灭熄。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00774","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00775","html":"\u003cp class=\"epub-calibre1\">“性情乖戾的奸细，贩卖战争的恶匪徒，\u003c/p>\n","text":"“性情乖戾的奸细，贩卖战争的恶匪徒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00776","html":"\u003cp class=\"epub-calibre1\">专把‘爱’的嫩蕾幼芽残害啮食的花蠹，\u003c/p>\n","text":"专把‘爱’的嫩蕾幼芽残害啮食的花蠹，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00777","html":"\u003cp class=\"epub-calibre1\">造谣生事、挑奸起火、搬是弄非的‘嫉妒’，\u003c/p>\n","text":"造谣生事、挑奸起火、搬是弄非的‘嫉妒’，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00778","html":"\u003cp class=\"epub-calibre1\">有时把真话传播，又有时把谎言散布。\u003c/p>\n","text":"有时把真话传播，又有时把谎言散布。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00779","html":"\u003cp class=\"epub-calibre1\">他在我的心里鼓动，在我的耳边上咕噜，\u003c/p>\n","text":"他在我的心里鼓动，在我的耳边上咕噜，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00780","html":"\u003cp class=\"epub-calibre1\">说我若是爱你，我就得为你的性命忧惧。\u003c/p>\n","text":"说我若是爱你，我就得为你的性命忧惧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00781","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00782","html":"\u003cp class=\"epub-calibre1\">“不但如此，他还在我眼前呈出幅画图。\u003c/p>\n","text":"“不但如此，他还在我眼前呈出幅画图。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00783","html":"\u003cp class=\"epub-calibre1\">画里出现的是一个愤怒凶暴的野猪，\u003c/p>\n","text":"画里出现的是一个愤怒凶暴的野猪，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00784","html":"\u003cp class=\"epub-calibre1\">在它那锋利的长牙下面，有一个形体，\u003c/p>\n","text":"在它那锋利的长牙下面，有一个形体，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00785","html":"\u003cp class=\"epub-calibre1\">和你的极相似，正仰面躺着，血肉模糊。\u003c/p>\n","text":"和你的极相似，正仰面躺着，血肉模糊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00786","html":"\u003cp class=\"epub-calibre1\">这血还把地上长的山花野卉濡染沾污，\u003c/p>\n","text":"这血还把地上长的山花野卉濡染沾污，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00787","html":"\u003cp class=\"epub-calibre1\">使它们悲伤哀毁，把身子低弯，把头低俯。\u003c/p>\n","text":"使它们悲伤哀毁，把身子低弯，把头低俯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00788","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00789","html":"\u003cp class=\"epub-calibre1\">“我现在只想到这种光景，就全身发抖，\u003c/p>\n","text":"“我现在只想到这种光景，就全身发抖，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00790","html":"\u003cp class=\"epub-calibre1\">如果我想的成了真事，那我该怎么受？\u003c/p>\n","text":"如果我想的成了真事，那我该怎么受？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00791","html":"\u003cp class=\"epub-calibre1\">这种想法，叫我这脆弱的心不禁血流。\u003c/p>\n","text":"这种想法，叫我这脆弱的心不禁血流。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00792","html":"\u003cp class=\"epub-calibre1\">‘忧愁’教给我，把未来的事，预先就看透。\u003c/p>\n","text":"‘忧愁’教给我，把未来的事，预先就看透。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00793","html":"\u003cp class=\"epub-calibre1\">因此，你若明天一定要去和野猪做对头，\u003c/p>\n","text":"因此，你若明天一定要去和野猪做对头，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00794","html":"\u003cp class=\"epub-calibre1\">我可预言：你要一下送命，我要一生发愁。\u003c/p>\n","text":"我可预言：你要一下送命，我要一生发愁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00795","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00796","html":"\u003cp class=\"epub-calibre1\">“你若非去行猎不可，那你可得听我说：\u003c/p>\n","text":"“你若非去行猎不可，那你可得听我说：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00797","html":"\u003cp class=\"epub-calibre1\">只可向胆怯会跑的小兔，放出狗一窝；\u003c/p>\n","text":"只可向胆怯会跑的小兔，放出狗一窝；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00798","html":"\u003cp class=\"epub-calibre1\">或者把狐狸捉，它们只凭狡猾谋逃脱；\u003c/p>\n","text":"或者把狐狸捉，它们只凭狡猾谋逃脱；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00799","html":"\u003cp class=\"epub-calibre1\">或者把小鹿逐，它们见了人只会闪躲。\u003c/p>\n","text":"或者把小鹿逐，它们见了人只会闪躲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00800","html":"\u003cp class=\"epub-calibre1\">你只可在丘原，把这类胆小的动物猎获，\u003c/p>\n","text":"你只可在丘原，把这类胆小的动物猎获，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00801","html":"\u003cp class=\"epub-calibre1\">还得骑着健壮的马，带着猎犬去把围合。\u003c/p>\n","text":"还得骑着健壮的马，带着猎犬去把围合。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00802","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00803","html":"\u003cp class=\"epub-calibre1\">“你若把目力弱的野兔赶起，你可注意，\u003c/p>\n","text":"“你若把目力弱的野兔赶起，你可注意，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00804","html":"\u003cp class=\"epub-calibre1\">看一下，那可怜的小东西，想逃避追敌，\u003c/p>\n","text":"看一下，那可怜的小东西，想逃避追敌，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00805","html":"\u003cp class=\"epub-calibre1\">怎样跑得比风还快，怎样想制胜出奇，\u003c/p>\n","text":"怎样跑得比风还快，怎样想制胜出奇，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00806","html":"\u003cp class=\"epub-calibre1\">拐千弯，转万角，闪躲腾挪，旁突又侧驰。\u003c/p>\n","text":"拐千弯，转万角，闪躲腾挪，旁突又侧驰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00807","html":"\u003cp class=\"epub-calibre1\">它在篱落的空隙间，进进出出，扑朔迷离，\u003c/p>\n","text":"它在篱落的空隙间，进进出出，扑朔迷离，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00808","html":"\u003cp class=\"epub-calibre1\">使它的敌人，像在迷宫里一样，错乱惊异。\u003c/p>\n","text":"使它的敌人，像在迷宫里一样，错乱惊异。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00809","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00810","html":"\u003cp class=\"epub-calibre1\">“它有时跑进羊群里，和它们混成一队，\u003c/p>\n","text":"“它有时跑进羊群里，和它们混成一队，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00811","html":"\u003cp class=\"epub-calibre1\">把嗅觉灵敏的猎狗，迷惑得不知其味；\u003c/p>\n","text":"把嗅觉灵敏的猎狗，迷惑得不知其味；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00812","html":"\u003cp class=\"epub-calibre1\">又有时，就躜到小山兔地下的深穴内，\u003c/p>\n","text":"又有时，就躜到小山兔地下的深穴内，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00813","html":"\u003cp class=\"epub-calibre1\">使高声叫唤的追敌，暂时停止了狂吠；\u003c/p>\n","text":"使高声叫唤的追敌，暂时停止了狂吠；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00814","html":"\u003cp class=\"epub-calibre1\">又有时就和鹿群合，叫人难分它属哪类。\u003c/p>\n","text":"又有时就和鹿群合，叫人难分它属哪类。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00815","html":"\u003cp class=\"epub-calibre1\">这真正是智谋出于急难，巧计生于临危。\u003c/p>\n","text":"这真正是智谋出于急难，巧计生于临危。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00816","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00817","html":"\u003cp class=\"epub-calibre1\">“因为这样，它的气味就和别的兽混杂，\u003c/p>\n","text":"“因为这样，它的气味就和别的兽混杂，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00818","html":"\u003cp class=\"epub-calibre1\">用鼻子嗅的猎狗，就无法断定哪是它，\u003c/p>\n","text":"用鼻子嗅的猎狗，就无法断定哪是它，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00819","html":"\u003cp class=\"epub-calibre1\">只好暂停吠声嘈杂，一直到忙搜紧查，\u003c/p>\n","text":"只好暂停吠声嘈杂，一直到忙搜紧查，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00820","html":"\u003cp class=\"epub-calibre1\">才又把失去了的气味找得分明不差。\u003c/p>\n","text":"才又把失去了的气味找得分明不差。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00821","html":"\u003cp class=\"epub-calibre1\">于是它们又狂吠起来，只闹得回声大发，\u003c/p>\n","text":"于是它们又狂吠起来，只闹得回声大发，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00822","html":"\u003cp class=\"epub-calibre1\">就好像另有一场追猎，正在天空里杂沓。\u003c/p>\n","text":"就好像另有一场追猎，正在天空里杂沓。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00823","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00824","html":"\u003cp class=\"epub-calibre1\">“这时，可怜的小兔，在远处的山上息足，\u003c/p>\n","text":"“这时，可怜的小兔，在远处的山上息足，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00825","html":"\u003cp class=\"epub-calibre1\">用后腿支身，叫前身拱起，把两耳耸立，\u003c/p>\n","text":"用后腿支身，叫前身拱起，把两耳耸立，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00826","html":"\u003cp class=\"epub-calibre1\">听一听它的敌人是否仍旧穷追紧逼。\u003c/p>\n","text":"听一听它的敌人是否仍旧穷追紧逼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00827","html":"\u003cp class=\"epub-calibre1\">霎时之间，它听见了它们的狂吠声起，\u003c/p>\n","text":"霎时之间，它听见了它们的狂吠声起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00828","html":"\u003cp class=\"epub-calibre1\">于是，它心里的难过，绝不能用笔墨表出。\u003c/p>\n","text":"于是，它心里的难过，绝不能用笔墨表出。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00829","html":"\u003cp class=\"epub-calibre1\">只有那病已不治、听见丧钟的人可以比。\u003c/p>\n","text":"只有那病已不治、听见丧钟的人可以比。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00830","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00831","html":"\u003cp class=\"epub-calibre1\">“这时只见那可怜的东西，满身露沾濡，\u003c/p>\n","text":"“这时只见那可怜的东西，满身露沾濡，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00832","html":"\u003cp class=\"epub-calibre1\">东逃西跑，侧奔横逸，曲里歪斜难踪迹。\u003c/p>\n","text":"东逃西跑，侧奔横逸，曲里歪斜难踪迹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00833","html":"\u003cp class=\"epub-calibre1\">丛丛恶荆棘，都往它那疲乏的腿上刺，\u003c/p>\n","text":"丛丛恶荆棘，都往它那疲乏的腿上刺，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00834","html":"\u003cp class=\"epub-calibre1\">处处黑影把它留，声声低响使它停止。\u003c/p>\n","text":"处处黑影把它留，声声低响使它停止。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00835","html":"\u003cp class=\"epub-calibre1\">因人一旦倒运，他就成了众人脚下的泥，\u003c/p>\n","text":"因人一旦倒运，他就成了众人脚下的泥，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00836","html":"\u003cp class=\"epub-calibre1\">而且一旦成泥，就没有人肯把他再拾起。\u003c/p>\n","text":"而且一旦成泥，就没有人肯把他再拾起。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00837","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00838","html":"\u003cp class=\"epub-calibre1\">“你好好地躺定，我还要说几句给你听。\u003c/p>\n","text":"“你好好地躺定，我还要说几句给你听。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00839","html":"\u003cp class=\"epub-calibre1\">别挣扎。我不许你起来，你挣扎也没用。\u003c/p>\n","text":"别挣扎。我不许你起来，你挣扎也没用。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00840","html":"\u003cp class=\"epub-calibre1\">我要你把猎野猪看作是可恨的事情。\u003c/p>\n","text":"我要你把猎野猪看作是可恨的事情。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00841","html":"\u003cp class=\"epub-calibre1\">因此，我大谈道理，不像我本来的光景，\u003c/p>\n","text":"因此，我大谈道理，不像我本来的光景，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00842","html":"\u003cp class=\"epub-calibre1\">以此喻彼，用彼比此，彼此相比，层出不穷，\u003c/p>\n","text":"以此喻彼，用彼比此，彼此相比，层出不穷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00843","html":"\u003cp class=\"epub-calibre1\">因为‘爱’，能对每样灾难悲愁，都解说阐明。\u003c/p>\n","text":"因为‘爱’，能对每样灾难悲愁，都解说阐明。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00844","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00845","html":"\u003cp class=\"epub-calibre1\">“我刚才说到了哪里？”他说：“不要管哪里。\u003c/p>\n","text":"“我刚才说到了哪里？”他说：“不要管哪里。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00846","html":"\u003cp class=\"epub-calibre1\">只要放我走，就不管哪里，都首尾整齐。\u003c/p>\n","text":"只要放我走，就不管哪里，都首尾整齐。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00847","html":"\u003cp class=\"epub-calibre1\">夜已经过去了。”她说：“哟，那有什么关系？”\u003c/p>\n","text":"夜已经过去了。”她说：“哟，那有什么关系？”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00848","html":"\u003cp class=\"epub-calibre1\">“我有几个朋友，”他说，“约好了正等我呢。\u003c/p>\n","text":"“我有几个朋友，”他说，“约好了正等我呢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00849","html":"\u003cp class=\"epub-calibre1\">现在这样黑，我走起来，一定要摔跤失足。”\u003c/p>\n","text":"现在这样黑，我走起来，一定要摔跤失足。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00850","html":"\u003cp class=\"epub-calibre1\">“夜是顶好的时候，”她说，“叫爱情使用目力。\u003c/p>\n","text":"“夜是顶好的时候，”她说，“叫爱情使用目力。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00851","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00852","html":"\u003cp class=\"epub-calibre1\">“不过你若真摔倒，哦，那你这样想才好：\u003c/p>\n","text":"“不过你若真摔倒，哦，那你这样想才好：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00853","html":"\u003cp class=\"epub-calibre1\">那是大地，爱你美貌，故意让你跌一跤，\u003c/p>\n","text":"那是大地，爱你美貌，故意让你跌一跤，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00854","html":"\u003cp class=\"epub-calibre1\">叫你嘴啃地，她好乘机偷着吻你一遭。\u003c/p>\n","text":"叫你嘴啃地，她好乘机偷着吻你一遭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00855","html":"\u003cp class=\"epub-calibre1\">即便君子，见了珍宝，也要眼馋把它盗。\u003c/p>\n","text":"即便君子，见了珍宝，也要眼馋把它盗。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00856","html":"\u003cp class=\"epub-calibre1\">因此，腼腆的狄安娜，用惨云愁雾把脸罩，\u003c/p>\n","text":"因此，腼腆的狄安娜，用惨云愁雾把脸罩，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00857","html":"\u003cp class=\"epub-calibre1\">否则也难保不偷吻你，把一生的誓言抛。\u003c/p>\n","text":"否则也难保不偷吻你，把一生的誓言抛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00858","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00859","html":"\u003cp class=\"epub-calibre1\">“我现在才懂得，今夜为什么这样黑。\u003c/p>\n","text":"“我现在才懂得，今夜为什么这样黑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00860","html":"\u003cp class=\"epub-calibre1\">这是狄安娜害羞，掩起银光而自晦。\u003c/p>\n","text":"这是狄安娜害羞，掩起银光而自晦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00861","html":"\u003cp class=\"epub-calibre1\">要等独出心裁的‘造化’被判逆天罪；\u003c/p>\n","text":"要等独出心裁的‘造化’被判逆天罪；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00862","html":"\u003cp class=\"epub-calibre1\">因为她从天上盗走模子，神圣尊贵，\u003c/p>\n","text":"因为她从天上盗走模子，神圣尊贵，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00863","html":"\u003cp class=\"epub-calibre1\">成心和上天反对，按照模子造出你的美，\u003c/p>\n","text":"成心和上天反对，按照模子造出你的美，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00864","html":"\u003cp class=\"epub-calibre1\">白天好叫太阳羞臊，夜里好叫月亮惭愧。\u003c/p>\n","text":"白天好叫太阳羞臊，夜里好叫月亮惭愧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00865","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00866","html":"\u003cp class=\"epub-calibre1\">“因为这样，狄安娜就把命运之神收买，\u003c/p>\n","text":"“因为这样，狄安娜就把命运之神收买，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00867","html":"\u003cp class=\"epub-calibre1\">叫她们把‘造化’的匠心绝艺摧毁破坏，\u003c/p>\n","text":"叫她们把‘造化’的匠心绝艺摧毁破坏，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00868","html":"\u003cp class=\"epub-calibre1\">在美中间掺杂上畸形病态，疵瑕丑怪，\u003c/p>\n","text":"在美中间掺杂上畸形病态，疵瑕丑怪，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00869","html":"\u003cp class=\"epub-calibre1\">使纯洁的完好，和腌臜的缺陷并肩排，\u003c/p>\n","text":"使纯洁的完好，和腌臜的缺陷并肩排，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00870","html":"\u003cp class=\"epub-calibre1\">使‘美’落入狂暴的厄运之手，被残酷虐待，\u003c/p>\n","text":"使‘美’落入狂暴的厄运之手，被残酷虐待，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00871","html":"\u003cp class=\"epub-calibre1\">使她逢不幸，遭苦难，备受烦恼，历尽灾害。\u003c/p>\n","text":"使她逢不幸，遭苦难，备受烦恼，历尽灾害。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00872","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00873","html":"\u003cp class=\"epub-calibre1\">“毒害生命的大疫，惑乱凶暴的狂易，\u003c/p>\n","text":"“毒害生命的大疫，惑乱凶暴的狂易，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00874","html":"\u003cp class=\"epub-calibre1\">发烧的热病，使人委靡疲敝的疟疾，\u003c/p>\n","text":"发烧的热病，使人委靡疲敝的疟疾，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00875","html":"\u003cp class=\"epub-calibre1\">耗损元气的痨瘵，如果沾染上身体，\u003c/p>\n","text":"耗损元气的痨瘵，如果沾染上身体，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00876","html":"\u003cp class=\"epub-calibre1\">便叫你血液沸腾，四肢痛楚骨支离；\u003c/p>\n","text":"便叫你血液沸腾，四肢痛楚骨支离；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00877","html":"\u003cp class=\"epub-calibre1\">还有生疮长疖，过饱伤食，罹忧患，遭悲凄，\u003c/p>\n","text":"还有生疮长疖，过饱伤食，罹忧患，遭悲凄，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00878","html":"\u003cp class=\"epub-calibre1\">都想置‘造化’于死地，只因她把美赋予了你。\u003c/p>\n","text":"都想置‘造化’于死地，只因她把美赋予了你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00879","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00880","html":"\u003cp class=\"epub-calibre1\">“这些疾病之内，即便是最轻微的一类，\u003c/p>\n","text":"“这些疾病之内，即便是最轻微的一类，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00881","html":"\u003cp class=\"epub-calibre1\">也都能够经一分钟的侵袭，把‘美’摧毁，\u003c/p>\n","text":"也都能够经一分钟的侵袭，把‘美’摧毁，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00882","html":"\u003cp class=\"epub-calibre1\">原先的俏形秀骨、雅韵清神、丽色香味，\u003c/p>\n","text":"原先的俏形秀骨、雅韵清神、丽色香味，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00883","html":"\u003cp class=\"epub-calibre1\">并非偏好的人，都要认为奇异珍贵，\u003c/p>\n","text":"并非偏好的人，都要认为奇异珍贵，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00884","html":"\u003cp class=\"epub-calibre1\">却一瞬就形销骨立，香消色褪，韵减神悴，\u003c/p>\n","text":"却一瞬就形销骨立，香消色褪，韵减神悴，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00885","html":"\u003cp class=\"epub-calibre1\">像山上的雪，在中午的太阳里一去不回。\u003c/p>\n","text":"像山上的雪，在中午的太阳里一去不回。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00886","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00887","html":"\u003cp class=\"epub-calibre1\">“那些终身不嫁的女娘，尽管贞洁贤良，\u003c/p>\n","text":"“那些终身不嫁的女娘，尽管贞洁贤良，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00888","html":"\u003cp class=\"epub-calibre1\">誓绝尘缘奉神祠，永伴经卷守庵堂；\u003c/p>\n","text":"誓绝尘缘奉神祠，永伴经卷守庵堂；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00889","html":"\u003cp class=\"epub-calibre1\">但是她们却一心想要世上发生人荒，\u003c/p>\n","text":"但是她们却一心想要世上发生人荒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00890","html":"\u003cp class=\"epub-calibre1\">不肯育子女，叫青年少得像凶岁食粮。\u003c/p>\n","text":"不肯育子女，叫青年少得像凶岁食粮。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00891","html":"\u003cp class=\"epub-calibre1\">咱们绝不学这种榜样。夜里辉煌的灯光，\u003c/p>\n","text":"咱们绝不学这种榜样。夜里辉煌的灯光，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00892","html":"\u003cp class=\"epub-calibre1\">本是把自己的油耗干了，才把人间照亮。\u003c/p>\n","text":"本是把自己的油耗干了，才把人间照亮。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00893","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00894","html":"\u003cp class=\"epub-calibre1\">“若你未曾把你的后嗣毁灭在幽暗里，\u003c/p>\n","text":"“若你未曾把你的后嗣毁灭在幽暗里，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00895","html":"\u003cp class=\"epub-calibre1\">那么按时光的正当要求，你该有后嗣。\u003c/p>\n","text":"那么按时光的正当要求，你该有后嗣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00896","html":"\u003cp class=\"epub-calibre1\">但像你现在这样，你的身体不是别的，\u003c/p>\n","text":"但像你现在这样，你的身体不是别的，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00897","html":"\u003cp class=\"epub-calibre1\">只是张着大嘴的坟墓，要把后嗣吞噬。\u003c/p>\n","text":"只是张着大嘴的坟墓，要把后嗣吞噬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00898","html":"\u003cp class=\"epub-calibre1\">如果真如此，那全世界就都要把你鄙夷，\u003c/p>\n","text":"如果真如此，那全世界就都要把你鄙夷，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00899","html":"\u003cp class=\"epub-calibre1\">因为你的骄傲，把这样美好的前途窒息。\u003c/p>\n","text":"因为你的骄傲，把这样美好的前途窒息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00900","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00901","html":"\u003cp class=\"epub-calibre1\">“因此你若是自生自灭，同样无人赞同。\u003c/p>\n","text":"“因此你若是自生自灭，同样无人赞同。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00902","html":"\u003cp class=\"epub-calibre1\">那是一种罪恶，坏过了兄弟阋墙之争，\u003c/p>\n","text":"那是一种罪恶，坏过了兄弟阋墙之争，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00903","html":"\u003cp class=\"epub-calibre1\">坏过了不顾一切的人们，自戕把命送，\u003c/p>\n","text":"坏过了不顾一切的人们，自戕把命送，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00904","html":"\u003cp class=\"epub-calibre1\">坏过了杀害亲子女的老子，绝灭人性。\u003c/p>\n","text":"坏过了杀害亲子女的老子，绝灭人性。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00905","html":"\u003cp class=\"epub-calibre1\">腐蚀的臭锈，能把深藏的宝物消耗干净，\u003c/p>\n","text":"腐蚀的臭锈，能把深藏的宝物消耗干净，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00906","html":"\u003cp class=\"epub-calibre1\">黄金如善于利用，却能把更多的黄金生。”\u003c/p>\n","text":"黄金如善于利用，却能把更多的黄金生。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00907","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00908","html":"\u003cp class=\"epub-calibre1\">“得了吧！”阿都尼喊，“别这样越说越没完。\u003c/p>\n","text":"“得了吧！”阿都尼喊，“别这样越说越没完。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00909","html":"\u003cp class=\"epub-calibre1\">你这是又要把无聊的老话搬了又搬。\u003c/p>\n","text":"你这是又要把无聊的老话搬了又搬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00910","html":"\u003cp class=\"epub-calibre1\">我那一吻，也算枉然，因为你说了不算。\u003c/p>\n","text":"我那一吻，也算枉然，因为你说了不算。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00911","html":"\u003cp class=\"epub-calibre1\">你净扭着人要把事办，那也只是枉然。\u003c/p>\n","text":"你净扭着人要把事办，那也只是枉然。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00912","html":"\u003cp class=\"epub-calibre1\">因为，情欲的秽乳母——黑脸的夜晚——看得见，\u003c/p>\n","text":"因为，情欲的秽乳母——黑脸的夜晚——看得见，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00913","html":"\u003cp class=\"epub-calibre1\">你的高论放得越多，你也就越让我讨厌。\u003c/p>\n","text":"你的高论放得越多，你也就越让我讨厌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00914","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00915","html":"\u003cp class=\"epub-calibre1\">“假使爱情能使你长出来舌头两万条，\u003c/p>\n","text":"“假使爱情能使你长出来舌头两万条，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00916","html":"\u003cp class=\"epub-calibre1\">每一条都比你还伶牙俐齿，能说会道，\u003c/p>\n","text":"每一条都比你还伶牙俐齿，能说会道，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00917","html":"\u003cp class=\"epub-calibre1\">像淫浪的美人鱼，唱得使人神魂颠倒，\u003c/p>\n","text":"像淫浪的美人鱼，唱得使人神魂颠倒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00918","html":"\u003cp class=\"epub-calibre1\">那我听来，也只能像耳旁风一样无效。\u003c/p>\n","text":"那我听来，也只能像耳旁风一样无效。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00919","html":"\u003cp class=\"epub-calibre1\">因为你要知道，我的耳朵给我的心保镖，\u003c/p>\n","text":"因为你要知道，我的耳朵给我的心保镖，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00920","html":"\u003cp class=\"epub-calibre1\">决不让任何淫词艳语，打进心房的内窍。\u003c/p>\n","text":"决不让任何淫词艳语，打进心房的内窍。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00921","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00922","html":"\u003cp class=\"epub-calibre1\">“怕的是，使人迷惑错乱的靡靡之音，\u003c/p>\n","text":"“怕的是，使人迷惑错乱的靡靡之音，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00923","html":"\u003cp class=\"epub-calibre1\">会深深侵入我这风平浪静的内心，\u003c/p>\n","text":"会深深侵入我这风平浪静的内心，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00924","html":"\u003cp class=\"epub-calibre1\">叫我这赤子的天真动情欲，生痴嗔，\u003c/p>\n","text":"叫我这赤子的天真动情欲，生痴嗔，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00925","html":"\u003cp class=\"epub-calibre1\">把它的内寝搅得不安静，扰攘纷纭。\u003c/p>\n","text":"把它的内寝搅得不安静，扰攘纷纭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00926","html":"\u003cp class=\"epub-calibre1\">哦，女后，我的心不想愁烦苦闷，长呻短吟，\u003c/p>\n","text":"哦，女后，我的心不想愁烦苦闷，长呻短吟，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00927","html":"\u003cp class=\"epub-calibre1\">它现在既然独寝，它只想能够睡得安稳。\u003c/p>\n","text":"它现在既然独寝，它只想能够睡得安稳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00928","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00929","html":"\u003cp class=\"epub-calibre1\">“所有你讲的道理，哪一点我不能驳斥？\u003c/p>\n","text":"“所有你讲的道理，哪一点我不能驳斥？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00930","html":"\u003cp class=\"epub-calibre1\">往危险那儿去的道路，永远光滑平直。\u003c/p>\n","text":"往危险那儿去的道路，永远光滑平直。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00931","html":"\u003cp class=\"epub-calibre1\">我对于‘爱’并不是一律厌弃。我恨的是：\u003c/p>\n","text":"我对于‘爱’并不是一律厌弃。我恨的是：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00932","html":"\u003cp class=\"epub-calibre1\">你那种不论生熟，人尽可夫的歪道理。\u003c/p>\n","text":"你那种不论生熟，人尽可夫的歪道理。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00933","html":"\u003cp class=\"epub-calibre1\">你说这是为生息繁育，这真是谬论怪议。\u003c/p>\n","text":"你说这是为生息繁育，这真是谬论怪议。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00934","html":"\u003cp class=\"epub-calibre1\">这是给淫行拉纤撮合，却用理由来文饰。\u003c/p>\n","text":"这是给淫行拉纤撮合，却用理由来文饰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00935","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00936","html":"\u003cp class=\"epub-calibre1\">“这不是‘爱’。因为自从世上的淫奔不才，\u003c/p>\n","text":"“这不是‘爱’。因为自从世上的淫奔不才，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00937","html":"\u003cp class=\"epub-calibre1\">硬把‘爱’的名义篡夺，‘爱’已往天上逃开。\u003c/p>\n","text":"硬把‘爱’的名义篡夺，‘爱’已往天上逃开。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00938","html":"\u003cp class=\"epub-calibre1\">‘淫’就假‘爱’的纯朴形态，把‘青春之美’害，\u003c/p>\n","text":"‘淫’就假‘爱’的纯朴形态，把‘青春之美’害，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00939","html":"\u003cp class=\"epub-calibre1\">使它的纯洁贞正，蒙了恶名，遭到指摘。\u003c/p>\n","text":"使它的纯洁贞正，蒙了恶名，遭到指摘。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00940","html":"\u003cp class=\"epub-calibre1\">这个暴戾的淫棍，把‘美’蹂躏，又把‘美’毁坏，\u003c/p>\n","text":"这个暴戾的淫棍，把‘美’蹂躏，又把‘美’毁坏，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00941","html":"\u003cp class=\"epub-calibre1\">就像毛虫把幼芽嫩叶那样残酷地对待。\u003c/p>\n","text":"就像毛虫把幼芽嫩叶那样残酷地对待。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00942","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00943","html":"\u003cp class=\"epub-calibre1\">“‘爱’使人安乐舒畅，就好像雨后的太阳，\u003c/p>\n","text":"“‘爱’使人安乐舒畅，就好像雨后的太阳，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00944","html":"\u003cp class=\"epub-calibre1\">‘淫’的后果，却像艳阳天变得雨骤风狂；\u003c/p>\n","text":"‘淫’的后果，却像艳阳天变得雨骤风狂；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00945","html":"\u003cp class=\"epub-calibre1\">‘爱’就像春日，永远使人温暖、新鲜、清爽，\u003c/p>\n","text":"‘爱’就像春日，永远使人温暖、新鲜、清爽，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00946","html":"\u003cp class=\"epub-calibre1\">‘淫’像冬天，夏天没完，就来得急急忙忙。\u003c/p>\n","text":"‘淫’像冬天，夏天没完，就来得急急忙忙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00947","html":"\u003cp class=\"epub-calibre1\">‘爱’永不使人餍，‘淫’却像饕餮，饱胀而死亡。\u003c/p>\n","text":"‘爱’永不使人餍，‘淫’却像饕餮，饱胀而死亡。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00948","html":"\u003cp class=\"epub-calibre1\">‘爱’永远像真理昭彰，‘淫’却永远骗人说谎。\u003c/p>\n","text":"‘爱’永远像真理昭彰，‘淫’却永远骗人说谎。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00949","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00950","html":"\u003cp class=\"epub-calibre1\">“我可以说的还很多，不过我不敢多说。\u003c/p>\n","text":"“我可以说的还很多，不过我不敢多说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00951","html":"\u003cp class=\"epub-calibre1\">讲的题目很古老，讲的人却年轻嘴拙。\u003c/p>\n","text":"讲的题目很古老，讲的人却年轻嘴拙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00952","html":"\u003cp class=\"epub-calibre1\">因此我这回却一点不错要和你别过。\u003c/p>\n","text":"因此我这回却一点不错要和你别过。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00953","html":"\u003cp class=\"epub-calibre1\">我满脸含羞又带愧，满腹忧繁又愁多，\u003c/p>\n","text":"我满脸含羞又带愧，满腹忧繁又愁多，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00954","html":"\u003cp class=\"epub-calibre1\">我听到了你这么些艳语淫词，猥亵邪恶，\u003c/p>\n","text":"我听到了你这么些艳语淫词，猥亵邪恶，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00955","html":"\u003cp class=\"epub-calibre1\">觉得实在龌龊污浊，两耳一直烧得似火。”\u003c/p>\n","text":"觉得实在龌龊污浊，两耳一直烧得似火。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00956","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00957","html":"\u003cp class=\"epub-calibre1\">他一面说，一面从她的香怀里挣脱，\u003c/p>\n","text":"他一面说，一面从她的香怀里挣脱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00958","html":"\u003cp class=\"epub-calibre1\">离开她那玉臂的拥抱，酥胸的揉搓，\u003c/p>\n","text":"离开她那玉臂的拥抱，酥胸的揉搓，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00959","html":"\u003cp class=\"epub-calibre1\">穿过昏暗的林隙，急忙往家里藏躲；\u003c/p>\n","text":"穿过昏暗的林隙，急忙往家里藏躲；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00960","html":"\u003cp class=\"epub-calibre1\">把爱后满怀痛苦地撂在那儿仰卧。\u003c/p>\n","text":"把爱后满怀痛苦地撂在那儿仰卧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00961","html":"\u003cp class=\"epub-calibre1\">你曾看见过明星一颗，在中天倏忽流过？\u003c/p>\n","text":"你曾看见过明星一颗，在中天倏忽流过？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00962","html":"\u003cp class=\"epub-calibre1\">爱后眼里的他，就那样在夜里一闪而没。\u003c/p>\n","text":"爱后眼里的他，就那样在夜里一闪而没。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00963","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00964","html":"\u003cp class=\"epub-calibre1\">他人虽去，他的余影仍把她的眼光摄。\u003c/p>\n","text":"他人虽去，他的余影仍把她的眼光摄。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00965","html":"\u003cp class=\"epub-calibre1\">像岸上的人，和刚上了船的朋友告别，\u003c/p>\n","text":"像岸上的人，和刚上了船的朋友告别，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00966","html":"\u003cp class=\"epub-calibre1\">老远看着；一直看到巨浪和天空相接，\u003c/p>\n","text":"老远看着；一直看到巨浪和天空相接，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00967","html":"\u003cp class=\"epub-calibre1\">排空直立，高如山岳，把他的视力隔绝。\u003c/p>\n","text":"排空直立，高如山岳，把他的视力隔绝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00968","html":"\u003cp class=\"epub-calibre1\">无情的昏沉黑夜，就这样把他的身形截，\u003c/p>\n","text":"无情的昏沉黑夜，就这样把他的身形截，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00969","html":"\u003cp class=\"epub-calibre1\">把她凝注的那个人包围吞噬，整个没灭。\u003c/p>\n","text":"把她凝注的那个人包围吞噬，整个没灭。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00970","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00971","html":"\u003cp class=\"epub-calibre1\">她迷惘怔忪，好像一个人因为不小心，\u003c/p>\n","text":"她迷惘怔忪，好像一个人因为不小心，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00972","html":"\u003cp class=\"epub-calibre1\">一下失手，把珍贵的珠宝掉入了巨浸；\u003c/p>\n","text":"一下失手，把珍贵的珠宝掉入了巨浸；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00973","html":"\u003cp class=\"epub-calibre1\">又像夜里的行人，走到阴森森的深林，\u003c/p>\n","text":"又像夜里的行人，走到阴森森的深林，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00974","html":"\u003cp class=\"epub-calibre1\">无端灯笼叫风吹灭，眼前只一片昏沉。\u003c/p>\n","text":"无端灯笼叫风吹灭，眼前只一片昏沉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00975","html":"\u003cp class=\"epub-calibre1\">她就那样仰卧在暗地里，目又呆，口又噤。\u003c/p>\n","text":"她就那样仰卧在暗地里，目又呆，口又噤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00976","html":"\u003cp class=\"epub-calibre1\">只因为失去了能给她指路的少年英俊。\u003c/p>\n","text":"只因为失去了能给她指路的少年英俊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00977","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00978","html":"\u003cp class=\"epub-calibre1\">于是她用手捶胸，从心里发出呻吟声。\u003c/p>\n","text":"于是她用手捶胸，从心里发出呻吟声。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00979","html":"\u003cp class=\"epub-calibre1\">四周围的幽岫深洞，好像也起了骚动，\u003c/p>\n","text":"四周围的幽岫深洞，好像也起了骚动，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00980","html":"\u003cp class=\"epub-calibre1\">把她的长吁短叹萦回周旋，往来传送。\u003c/p>\n","text":"把她的长吁短叹萦回周旋，往来传送。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00981","html":"\u003cp class=\"epub-calibre1\">跟着哀怨四处生，深沉低重，山震谷鸣。\u003c/p>\n","text":"跟着哀怨四处生，深沉低重，山震谷鸣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00982","html":"\u003cp class=\"epub-calibre1\">她发了几声唉唉，又说了二十声痛痛痛，\u003c/p>\n","text":"她发了几声唉唉，又说了二十声痛痛痛，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00983","html":"\u003cp class=\"epub-calibre1\">于是二十倍的二十声痛痛痛，和她呼应。\u003c/p>\n","text":"于是二十倍的二十声痛痛痛，和她呼应。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00984","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00985","html":"\u003cp class=\"epub-calibre1\">她听到回声起，就开始用号哭的调子，\u003c/p>\n","text":"她听到回声起，就开始用号哭的调子，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00986","html":"\u003cp class=\"epub-calibre1\">临时随口唱出一段凄楚动人的歌词：\u003c/p>\n","text":"临时随口唱出一段凄楚动人的歌词：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00987","html":"\u003cp class=\"epub-calibre1\">唱“爱”怎样使青年变奴隶，老人变呆痴，\u003c/p>\n","text":"唱“爱”怎样使青年变奴隶，老人变呆痴，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00988","html":"\u003cp class=\"epub-calibre1\">“爱”怎样是愚中有智、智中有愚的东西。\u003c/p>\n","text":"“爱”怎样是愚中有智、智中有愚的东西。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00989","html":"\u003cp class=\"epub-calibre1\">她的歌儿永远以哀伤结束，以悲痛终止。\u003c/p>\n","text":"她的歌儿永远以哀伤结束，以悲痛终止。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00990","html":"\u003cp class=\"epub-calibre1\">她的合唱队也永远同声应答，表示一致。\u003c/p>\n","text":"她的合唱队也永远同声应答，表示一致。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00991","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00992","html":"\u003cp class=\"epub-calibre1\">长夜已过，歌声还不断，真正叫人生厌。\u003c/p>\n","text":"长夜已过，歌声还不断，真正叫人生厌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00993","html":"\u003cp class=\"epub-calibre1\">情人的时光实际很长，虽然自觉很短。\u003c/p>\n","text":"情人的时光实际很长，虽然自觉很短。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00994","html":"\u003cp class=\"epub-calibre1\">他们那一套把戏，自己觉得趣味盎然，\u003c/p>\n","text":"他们那一套把戏，自己觉得趣味盎然，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00995","html":"\u003cp class=\"epub-calibre1\">就认为别人当此情此景，也同样喜欢。\u003c/p>\n","text":"就认为别人当此情此景，也同样喜欢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00996","html":"\u003cp class=\"epub-calibre1\">他们的情谈，往往开了头，絮叨叨、腻烦烦，\u003c/p>\n","text":"他们的情谈，往往开了头，絮叨叨、腻烦烦，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00997","html":"\u003cp class=\"epub-calibre1\">没人能听得全，也没人知道什么时候完。\u003c/p>\n","text":"没人能听得全，也没人知道什么时候完。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00998","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-00999","html":"\u003cp class=\"epub-calibre1\">除了无聊的声音，像唯唯否否不离口，\u003c/p>\n","text":"除了无聊的声音，像唯唯否否不离口，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01000","html":"\u003cp class=\"epub-calibre1\">还有什么和她把漫漫的长夜一同守？\u003c/p>\n","text":"还有什么和她把漫漫的长夜一同守？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01001","html":"\u003cp class=\"epub-calibre1\">这种声音一叫就应，就像酒保的尖喉，\u003c/p>\n","text":"这种声音一叫就应，就像酒保的尖喉，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01002","html":"\u003cp class=\"epub-calibre1\">对那种性情乖僻的顾客，强把趣儿凑。\u003c/p>\n","text":"对那种性情乖僻的顾客，强把趣儿凑。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01003","html":"\u003cp class=\"epub-calibre1\">她若说，非唯唯，是否否，它们也就说否否；\u003c/p>\n","text":"她若说，非唯唯，是否否，它们也就说否否；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01004","html":"\u003cp class=\"epub-calibre1\">她若说，是唯唯，非否否，它们决不说否否。\u003c/p>\n","text":"她若说，是唯唯，非否否，它们决不说否否。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01005","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01006","html":"\u003cp class=\"epub-calibre1\">看！云雀轻盈，蜷伏了一夜感到不受用，\u003c/p>\n","text":"看！云雀轻盈，蜷伏了一夜感到不受用，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01007","html":"\u003cp class=\"epub-calibre1\">从草地上带露的栖息处，盘上了天空，\u003c/p>\n","text":"从草地上带露的栖息处，盘上了天空，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01008","html":"\u003cp class=\"epub-calibre1\">把清晨唤醒。只见从清晨银色的前胸，\u003c/p>\n","text":"把清晨唤醒。只见从清晨银色的前胸，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01009","html":"\u003cp class=\"epub-calibre1\">太阳初升，威仪俨俨，步履安详，气度雍容。\u003c/p>\n","text":"太阳初升，威仪俨俨，步履安详，气度雍容。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01010","html":"\u003cp class=\"epub-calibre1\">目光四射，辉煌地看着下界的气象万种，\u003c/p>\n","text":"目光四射，辉煌地看着下界的气象万种，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01011","html":"\u003cp class=\"epub-calibre1\">把树巅山顶，都映得黄金一般灿烂光明。\u003c/p>\n","text":"把树巅山顶，都映得黄金一般灿烂光明。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01012","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01013","html":"\u003cp class=\"epub-calibre1\">维纳斯对太阳早安说连声，把他接迎：\u003c/p>\n","text":"维纳斯对太阳早安说连声，把他接迎：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01014","html":"\u003cp class=\"epub-calibre1\">“你这辉煌的天神，一切光明的主人翁，\u003c/p>\n","text":"“你这辉煌的天神，一切光明的主人翁，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01015","html":"\u003cp class=\"epub-calibre1\">每一盏明灯、每一颗明星所以亮晶晶，\u003c/p>\n","text":"每一盏明灯、每一颗明星所以亮晶晶，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01016","html":"\u003cp class=\"epub-calibre1\">都因你借与光明，否则只有黑暗昏暝。\u003c/p>\n","text":"都因你借与光明，否则只有黑暗昏暝。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01017","html":"\u003cp class=\"epub-calibre1\">如今有个孩童，虽是凡间女子所育所生，\u003c/p>\n","text":"如今有个孩童，虽是凡间女子所育所生，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01018","html":"\u003cp class=\"epub-calibre1\">能借给你光明，和你借给万物光明相同。”\u003c/p>\n","text":"能借给你光明，和你借给万物光明相同。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01019","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01020","html":"\u003cp class=\"epub-calibre1\">她这样说完，忙往一丛桃金娘林里赶，\u003c/p>\n","text":"她这样说完，忙往一丛桃金娘林里赶，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01021","html":"\u003cp class=\"epub-calibre1\">一心只想，清晨的时光已经过了大半，\u003c/p>\n","text":"一心只想，清晨的时光已经过了大半，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01022","html":"\u003cp class=\"epub-calibre1\">怎么没听见她的所爱，有任何消息传？\u003c/p>\n","text":"怎么没听见她的所爱，有任何消息传？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01023","html":"\u003cp class=\"epub-calibre1\">她倾耳细听，听他的号角和他的猎犬。\u003c/p>\n","text":"她倾耳细听，听他的号角和他的猎犬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01024","html":"\u003cp class=\"epub-calibre1\">于是果然听见它们一齐大声猛叫狂喊。\u003c/p>\n","text":"于是果然听见它们一齐大声猛叫狂喊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01025","html":"\u003cp class=\"epub-calibre1\">她顺着它们的这吠声，急忙跑去不怠慢。\u003c/p>\n","text":"她顺着它们的这吠声，急忙跑去不怠慢。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01026","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01027","html":"\u003cp class=\"epub-calibre1\">在她往前跑去的时候，路上的丛灌，\u003c/p>\n","text":"在她往前跑去的时候，路上的丛灌，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01028","html":"\u003cp class=\"epub-calibre1\">有的摸她的脖颈，有的就吻她的脸，\u003c/p>\n","text":"有的摸她的脖颈，有的就吻她的脸，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01029","html":"\u003cp class=\"epub-calibre1\">又有的抓住她的腿，叫她难把路趱。\u003c/p>\n","text":"又有的抓住她的腿，叫她难把路趱。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01030","html":"\u003cp class=\"epub-calibre1\">她用力挣脱了它们这种紧裹慢缠，\u003c/p>\n","text":"她用力挣脱了它们这种紧裹慢缠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01031","html":"\u003cp class=\"epub-calibre1\">就好像树林中的麑鹿，乳头胀得痛又酸，\u003c/p>\n","text":"就好像树林中的麑鹿，乳头胀得痛又酸，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01032","html":"\u003cp class=\"epub-calibre1\">连忙要赶到丛莽中藏着的麑鹿的身边。\u003c/p>\n","text":"连忙要赶到丛莽中藏着的麑鹿的身边。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01033","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01034","html":"\u003cp class=\"epub-calibre1\">她这时听出来，有大敌当前，背城死战，\u003c/p>\n","text":"她这时听出来，有大敌当前，背城死战，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01035","html":"\u003cp class=\"epub-calibre1\">就吃惊非浅；一个人，若忽遇毒蛇出现，\u003c/p>\n","text":"就吃惊非浅；一个人，若忽遇毒蛇出现，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01036","html":"\u003cp class=\"epub-calibre1\">吓人地盘着，把他的去路恰恰挡得严，\u003c/p>\n","text":"吓人地盘着，把他的去路恰恰挡得严，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01037","html":"\u003cp class=\"epub-calibre1\">他就要又哆嗦、又打战，挪一步都不敢；\u003c/p>\n","text":"他就要又哆嗦、又打战，挪一步都不敢；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01038","html":"\u003cp class=\"epub-calibre1\">她觉到，群犬的吠声表示它们畏缩不前。\u003c/p>\n","text":"她觉到，群犬的吠声表示它们畏缩不前。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01039","html":"\u003cp class=\"epub-calibre1\">也就同样眼前生花，耳里雷鸣，身上乱颤。\u003c/p>\n","text":"也就同样眼前生花，耳里雷鸣，身上乱颤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01040","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01041","html":"\u003cp class=\"epub-calibre1\">她现在知道，所猎的决非动物弱小，\u003c/p>\n","text":"她现在知道，所猎的决非动物弱小，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01042","html":"\u003cp class=\"epub-calibre1\">而一定是野猪粗暴，熊莽撞，狮骄傲。\u003c/p>\n","text":"而一定是野猪粗暴，熊莽撞，狮骄傲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01043","html":"\u003cp class=\"epub-calibre1\">因为吠声永远停在一处，又嘈又高，\u003c/p>\n","text":"因为吠声永远停在一处，又嘈又高，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01044","html":"\u003cp class=\"epub-calibre1\">猎狗就在那儿带着恐惧狂嗥大叫。\u003c/p>\n","text":"猎狗就在那儿带着恐惧狂嗥大叫。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01045","html":"\u003cp class=\"epub-calibre1\">原来它们看到了敌人那样地凶恶残暴，\u003c/p>\n","text":"原来它们看到了敌人那样地凶恶残暴，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01046","html":"\u003cp class=\"epub-calibre1\">便互相推让，谁都不肯去抢先登的功劳。\u003c/p>\n","text":"便互相推让，谁都不肯去抢先登的功劳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01047","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01048","html":"\u003cp class=\"epub-calibre1\">这样惨叫，让她的耳朵听来十分凄惶。\u003c/p>\n","text":"这样惨叫，让她的耳朵听来十分凄惶。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01049","html":"\u003cp class=\"epub-calibre1\">从耳朵传到心里，叫她心里也起惊慌。\u003c/p>\n","text":"从耳朵传到心里，叫她心里也起惊慌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01050","html":"\u003cp class=\"epub-calibre1\">她只吓得面失色，满腹疑虑事不吉祥，\u003c/p>\n","text":"她只吓得面失色，满腹疑虑事不吉祥，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01051","html":"\u003cp class=\"epub-calibre1\">腿软手颤，口呆目怔，足难移来身似僵，\u003c/p>\n","text":"腿软手颤，口呆目怔，足难移来身似僵，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01052","html":"\u003cp class=\"epub-calibre1\">四肢百骸齐解体，像兵士一遇主将败亡，\u003c/p>\n","text":"四肢百骸齐解体，像兵士一遇主将败亡，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01053","html":"\u003cp class=\"epub-calibre1\">便四下里乱逃乱窜，不敢再留在战场上。\u003c/p>\n","text":"便四下里乱逃乱窜，不敢再留在战场上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01054","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01055","html":"\u003cp class=\"epub-calibre1\">她这样身发抖、眼发直，兴奋得不自主。\u003c/p>\n","text":"她这样身发抖、眼发直，兴奋得不自主。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01056","html":"\u003cp class=\"epub-calibre1\">接着又把惊慌失措的感官鼓励安抚；\u003c/p>\n","text":"接着又把惊慌失措的感官鼓励安抚；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01057","html":"\u003cp class=\"epub-calibre1\">对它们说，它们这样怕，显与事实不符，\u003c/p>\n","text":"对它们说，它们这样怕，显与事实不符，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01058","html":"\u003cp class=\"epub-calibre1\">它们这是和小孩一样，无端自己恐怖；\u003c/p>\n","text":"它们这是和小孩一样，无端自己恐怖；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01059","html":"\u003cp class=\"epub-calibre1\">告诫它们不要这样全身哆嗦，骨麻筋酥。\u003c/p>\n","text":"告诫它们不要这样全身哆嗦，骨麻筋酥。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01060","html":"\u003cp class=\"epub-calibre1\">她说到这里，一眼瞥见了那被猎的野猪。\u003c/p>\n","text":"她说到这里，一眼瞥见了那被猎的野猪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01061","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01062","html":"\u003cp class=\"epub-calibre1\">只见它满口白沫吐，又满嘴红血污，\u003c/p>\n","text":"只见它满口白沫吐，又满嘴红血污，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01063","html":"\u003cp class=\"epub-calibre1\">似鲜奶和鲜血搀在一起，狼藉模糊。\u003c/p>\n","text":"似鲜奶和鲜血搀在一起，狼藉模糊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01064","html":"\u003cp class=\"epub-calibre1\">于是恐怖第二次在她全身上传布，\u003c/p>\n","text":"于是恐怖第二次在她全身上传布，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01065","html":"\u003cp class=\"epub-calibre1\">使她疯了一般，不知应该往哪里去。\u003c/p>\n","text":"使她疯了一般，不知应该往哪里去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01066","html":"\u003cp class=\"epub-calibre1\">她往前瞎跑一气，于是忽然一下又站住，\u003c/p>\n","text":"她往前瞎跑一气，于是忽然一下又站住，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01067","html":"\u003cp class=\"epub-calibre1\">跟着又跑回原处，大骂杀人该死的野畜。\u003c/p>\n","text":"跟着又跑回原处，大骂杀人该死的野畜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01068","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01069","html":"\u003cp class=\"epub-calibre1\">一千种恐怖，支使着她奔向一千条路。\u003c/p>\n","text":"一千种恐怖，支使着她奔向一千条路。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01070","html":"\u003cp class=\"epub-calibre1\">她乱跑，好像只为去而复来，来而复去。\u003c/p>\n","text":"她乱跑，好像只为去而复来，来而复去。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01071","html":"\u003cp class=\"epub-calibre1\">她的急劲儿，只有她的慢劲儿能够比。\u003c/p>\n","text":"她的急劲儿，只有她的慢劲儿能够比。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01072","html":"\u003cp class=\"epub-calibre1\">就像醉汉，仿佛不论何事，都用心考虑，\u003c/p>\n","text":"就像醉汉，仿佛不论何事，都用心考虑，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01073","html":"\u003cp class=\"epub-calibre1\">然而，他的脑子里却一样也没认真考虑，\u003c/p>\n","text":"然而，他的脑子里却一样也没认真考虑，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01074","html":"\u003cp class=\"epub-calibre1\">忙忙碌碌，乱抓一气，却半点也没有头绪。\u003c/p>\n","text":"忙忙碌碌，乱抓一气，却半点也没有头绪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01075","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01076","html":"\u003cp class=\"epub-calibre1\">她先看到，在一丛灌莽里，趴着狗一条，\u003c/p>\n","text":"她先看到，在一丛灌莽里，趴着狗一条，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01077","html":"\u003cp class=\"epub-calibre1\">她就对那疲乏的畜生把它的主人要。\u003c/p>\n","text":"她就对那疲乏的畜生把它的主人要。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01078","html":"\u003cp class=\"epub-calibre1\">又看到另一条，想把血淋淋的伤舔好，\u003c/p>\n","text":"又看到另一条，想把血淋淋的伤舔好，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01079","html":"\u003cp class=\"epub-calibre1\">因为治含毒素的伤，这种疗法最有效。\u003c/p>\n","text":"因为治含毒素的伤，这种疗法最有效。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01080","html":"\u003cp class=\"epub-calibre1\">又找到第三条，只见它面目凄怆神伤悼，\u003c/p>\n","text":"又找到第三条，只见它面目凄怆神伤悼，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01081","html":"\u003cp class=\"epub-calibre1\">她问它话，它只呜呜狂吠长嗥，作为回报。\u003c/p>\n","text":"她问它话，它只呜呜狂吠长嗥，作为回报。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01082","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01083","html":"\u003cp class=\"epub-calibre1\">它刚停止了这样逆心刺耳的长嗥，\u003c/p>\n","text":"它刚停止了这样逆心刺耳的长嗥，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01084","html":"\u003cp class=\"epub-calibre1\">另一个厚唇下垂的畜生，抑郁懊恼，\u003c/p>\n","text":"另一个厚唇下垂的畜生，抑郁懊恼，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01085","html":"\u003cp class=\"epub-calibre1\">也朝着苍天一阵一阵地呜呜哀号。\u003c/p>\n","text":"也朝着苍天一阵一阵地呜呜哀号。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01086","html":"\u003cp class=\"epub-calibre1\">于是一个接一个，都一齐开始狂叫；\u003c/p>\n","text":"于是一个接一个，都一齐开始狂叫；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01087","html":"\u003cp class=\"epub-calibre1\">原先直耸的尾巴，都紧贴身后往地上扫；\u003c/p>\n","text":"原先直耸的尾巴，都紧贴身后往地上扫；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01088","html":"\u003cp class=\"epub-calibre1\">咬伤了的耳朵直甩动，血涌不止似海潮。\u003c/p>\n","text":"咬伤了的耳朵直甩动，血涌不止似海潮。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01089","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01090","html":"\u003cp class=\"epub-calibre1\">你曾见过，世上有些可怜的愚夫俗子，\u003c/p>\n","text":"你曾见过，世上有些可怜的愚夫俗子，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01091","html":"\u003cp class=\"epub-calibre1\">看到妖魔鬼怪、异兆奇象，便惊慌失据，\u003c/p>\n","text":"看到妖魔鬼怪、异兆奇象，便惊慌失据，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01092","html":"\u003cp class=\"epub-calibre1\">带着恐惧之心，把它们长久观望注视，\u003c/p>\n","text":"带着恐惧之心，把它们长久观望注视，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01093","html":"\u003cp class=\"epub-calibre1\">一心只怕将要发生可怖的祸殃灾异。\u003c/p>\n","text":"一心只怕将要发生可怖的祸殃灾异。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01094","html":"\u003cp class=\"epub-calibre1\">同样，眼前的景象，叫她倒抽了一口凉气，\u003c/p>\n","text":"同样，眼前的景象，叫她倒抽了一口凉气，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01095","html":"\u003cp class=\"epub-calibre1\">接着又把气叹出，向死神大大发泄悲凄。\u003c/p>\n","text":"接着又把气叹出，向死神大大发泄悲凄。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01096","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01097","html":"\u003cp class=\"epub-calibre1\">“你这狰狞的魔君，枯肉巉巉，白骨嶙嶙，\u003c/p>\n","text":"“你这狰狞的魔君，枯肉巉巉，白骨嶙嶙，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01098","html":"\u003cp class=\"epub-calibre1\">专和爱做对头，狠毒的化身，”她骂死神。\u003c/p>\n","text":"专和爱做对头，狠毒的化身，”她骂死神。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01099","html":"\u003cp class=\"epub-calibre1\">“地上的毒蛇，世间的骷髅，连笑都吓人。\u003c/p>\n","text":"“地上的毒蛇，世间的骷髅，连笑都吓人。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01100","html":"\u003cp class=\"epub-calibre1\">你为何把美扼杀，把他的生命暗中侵？\u003c/p>\n","text":"你为何把美扼杀，把他的生命暗中侵？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01101","html":"\u003cp class=\"epub-calibre1\">他活着的时候，本来气息清香，容貌聪俊，\u003c/p>\n","text":"他活着的时候，本来气息清香，容貌聪俊，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01102","html":"\u003cp class=\"epub-calibre1\">能叫紫罗兰都增芬芳，玫瑰花都增艳润。\u003c/p>\n","text":"能叫紫罗兰都增芬芳，玫瑰花都增艳润。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01103","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01104","html":"\u003cp class=\"epub-calibre1\">“他若是死了——哦，不可能，他不可能死。\u003c/p>\n","text":"“他若是死了——哦，不可能，他不可能死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01105","html":"\u003cp class=\"epub-calibre1\">难道你看到他那样美，还不知自制？\u003c/p>\n","text":"难道你看到他那样美，还不知自制？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01106","html":"\u003cp class=\"epub-calibre1\">但也可能。因为你本来是有目无珠，\u003c/p>\n","text":"但也可能。因为你本来是有目无珠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01107","html":"\u003cp class=\"epub-calibre1\">你只狠毒恶辣地胡砍乱扎，视而无睹。\u003c/p>\n","text":"你只狠毒恶辣地胡砍乱扎，视而无睹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01108","html":"\u003cp class=\"epub-calibre1\">你的对象本是老迈衰弱，但你无的放矢，\u003c/p>\n","text":"你的对象本是老迈衰弱，但你无的放矢，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01109","html":"\u003cp class=\"epub-calibre1\">因此你的毒箭杀害了的却是一个孺子。\u003c/p>\n","text":"因此你的毒箭杀害了的却是一个孺子。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01110","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01111","html":"\u003cp class=\"epub-calibre1\">“你若曾经警告过他，他就会和你答话，\u003c/p>\n","text":"“你若曾经警告过他，他就会和你答话，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01112","html":"\u003cp class=\"epub-calibre1\">那样你听到了他，你的威力就要消煞。\u003c/p>\n","text":"那样你听到了他，你的威力就要消煞。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01113","html":"\u003cp class=\"epub-calibre1\">命运之神因你这一着，定要把你咒骂。\u003c/p>\n","text":"命运之神因你这一着，定要把你咒骂。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01114","html":"\u003cp class=\"epub-calibre1\">她们本来叫你除莠草，你却拔了鲜花。\u003c/p>\n","text":"她们本来叫你除莠草，你却拔了鲜花。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01115","html":"\u003cp class=\"epub-calibre1\">向他发的应该是爱神的金箭，色丽彩华，\u003c/p>\n","text":"向他发的应该是爱神的金箭，色丽彩华，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01116","html":"\u003cp class=\"epub-calibre1\">不应该是死神的黑箭，阴森地把他射杀。\u003c/p>\n","text":"不应该是死神的黑箭，阴森地把他射杀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01117","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01118","html":"\u003cp class=\"epub-calibre1\">“难道你饮泪解馋，才涌起如许的泪泉？\u003c/p>\n","text":"“难道你饮泪解馋，才涌起如许的泪泉？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01119","html":"\u003cp class=\"epub-calibre1\">悲愁的呻吟，于你会有什么好处可言？\u003c/p>\n","text":"悲愁的呻吟，于你会有什么好处可言？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01120","html":"\u003cp class=\"epub-calibre1\">那一双眼，本是教给许多眼如何顾盼，\u003c/p>\n","text":"那一双眼，本是教给许多眼如何顾盼，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01121","html":"\u003cp class=\"epub-calibre1\">你却为什么把它们断送，叫它们长眠？\u003c/p>\n","text":"你却为什么把它们断送，叫它们长眠？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01122","html":"\u003cp class=\"epub-calibre1\">现在造化不再理会你那操生死的大权，\u003c/p>\n","text":"现在造化不再理会你那操生死的大权，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01123","html":"\u003cp class=\"epub-calibre1\">因她最完美的天工，你已经狠毒地摧残。”\u003c/p>\n","text":"因她最完美的天工，你已经狠毒地摧残。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01124","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01125","html":"\u003cp class=\"epub-calibre1\">她说到这里，像绝望的人，悲不自胜，\u003c/p>\n","text":"她说到这里，像绝望的人，悲不自胜，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01126","html":"\u003cp class=\"epub-calibre1\">两眼怔忪，于是眼皮便像闸门合拢；\u003c/p>\n","text":"两眼怔忪，于是眼皮便像闸门合拢；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01127","html":"\u003cp class=\"epub-calibre1\">晶莹的眼泪，原先往香腮上汩汩直涌，\u003c/p>\n","text":"晶莹的眼泪，原先往香腮上汩汩直涌，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01128","html":"\u003cp class=\"epub-calibre1\">汇成两条水流，滴到酥胸，一时暂停。\u003c/p>\n","text":"汇成两条水流，滴到酥胸，一时暂停。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01129","html":"\u003cp class=\"epub-calibre1\">但是银色的雨，仍旧不断往闸门那儿冲，\u003c/p>\n","text":"但是银色的雨，仍旧不断往闸门那儿冲，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01130","html":"\u003cp class=\"epub-calibre1\">把闸门二次冲开，因泪的巨流汹涌势猛。\u003c/p>\n","text":"把闸门二次冲开，因泪的巨流汹涌势猛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01131","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01132","html":"\u003cp class=\"epub-calibre1\">看，她的泪和眼，你取我与，恐后争先：\u003c/p>\n","text":"看，她的泪和眼，你取我与，恐后争先：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01133","html":"\u003cp class=\"epub-calibre1\">泪从眼里晶莹落，眼又在泪里玲珑现，\u003c/p>\n","text":"泪从眼里晶莹落，眼又在泪里玲珑现，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01134","html":"\u003cp class=\"epub-calibre1\">同晶莹，两映掩，互相看着彼此的愁颜。\u003c/p>\n","text":"同晶莹，两映掩，互相看着彼此的愁颜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01135","html":"\u003cp class=\"epub-calibre1\">同情的叹息就把眼泪、泪眼，轻拂慢搌。\u003c/p>\n","text":"同情的叹息就把眼泪、泪眼，轻拂慢搌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01136","html":"\u003cp class=\"epub-calibre1\">但像风雨交加之日，风吹不停，雨下不完，\u003c/p>\n","text":"但像风雨交加之日，风吹不停，雨下不完，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01137","html":"\u003cp class=\"epub-calibre1\">因此，双颊刚被叹息吹干，随即泪痕阑干。\u003c/p>\n","text":"因此，双颊刚被叹息吹干，随即泪痕阑干。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01138","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01139","html":"\u003cp class=\"epub-calibre1\">在她无尽的伤悼中，不同的感情齐涌，\u003c/p>\n","text":"在她无尽的伤悼中，不同的感情齐涌，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01140","html":"\u003cp class=\"epub-calibre1\">像争强斗胜，看谁最能表现她的悲痛。\u003c/p>\n","text":"像争强斗胜，看谁最能表现她的悲痛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01141","html":"\u003cp class=\"epub-calibre1\">它们都受到收容，于是各自奋勇逞能，\u003c/p>\n","text":"它们都受到收容，于是各自奋勇逞能，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01142","html":"\u003cp class=\"epub-calibre1\">每一种都好像是其他那些的主人公，\u003c/p>\n","text":"每一种都好像是其他那些的主人公，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01143","html":"\u003cp class=\"epub-calibre1\">却一种也不能称雄；于是它们联合结盟，\u003c/p>\n","text":"却一种也不能称雄；于是它们联合结盟，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01144","html":"\u003cp class=\"epub-calibre1\">像乌云聚拢，商议怎么能召来暴雨狂风。\u003c/p>\n","text":"像乌云聚拢，商议怎么能召来暴雨狂风。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01145","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01146","html":"\u003cp class=\"epub-calibre1\">这时，她忽然听见远处猎人高声喊起，\u003c/p>\n","text":"这时，她忽然听见远处猎人高声喊起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01147","html":"\u003cp class=\"epub-calibre1\">从未有乳母的歌声能叫婴儿更欢喜。\u003c/p>\n","text":"从未有乳母的歌声能叫婴儿更欢喜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01148","html":"\u003cp class=\"epub-calibre1\">她原先想象之中的一切恐惧和疑虑，\u003c/p>\n","text":"她原先想象之中的一切恐惧和疑虑，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01149","html":"\u003cp class=\"epub-calibre1\">都叫这一声喊排斥；希望并非全绝迹。\u003c/p>\n","text":"都叫这一声喊排斥；希望并非全绝迹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01150","html":"\u003cp class=\"epub-calibre1\">这种死而复生的欢心，叫她又生出喜意，\u003c/p>\n","text":"这种死而复生的欢心，叫她又生出喜意，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01151","html":"\u003cp class=\"epub-calibre1\">奉承她说，喊出这一声的，一定是阿都尼。\u003c/p>\n","text":"奉承她说，喊出这一声的，一定是阿都尼。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01152","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01153","html":"\u003cp class=\"epub-calibre1\">于是她那像潮水的眼泪，回澜闭闸，\u003c/p>\n","text":"于是她那像潮水的眼泪，回澜闭闸，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01154","html":"\u003cp class=\"epub-calibre1\">在眼里暂藏，像在椟中的珍珠无价。\u003c/p>\n","text":"在眼里暂藏，像在椟中的珍珠无价。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01155","html":"\u003cp class=\"epub-calibre1\">只偶有晶莹明澈的泪珠，慢慢流下，\u003c/p>\n","text":"只偶有晶莹明澈的泪珠，慢慢流下，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01156","html":"\u003cp class=\"epub-calibre1\">但一到脸上就融化，好像不肯让它\u003c/p>\n","text":"但一到脸上就融化，好像不肯让它\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01157","html":"\u003cp class=\"epub-calibre1\">往肮脏的地面上流，往污秽的尘土中洒，\u003c/p>\n","text":"往肮脏的地面上流，往污秽的尘土中洒，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01158","html":"\u003cp class=\"epub-calibre1\">因为珠圆玉润的泪，怎能洗净地的邋遢？\u003c/p>\n","text":"因为珠圆玉润的泪，怎能洗净地的邋遢？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01159","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01160","html":"\u003cp class=\"epub-calibre1\">唉，不轻置信的爱，你好像难推诚相待，\u003c/p>\n","text":"唉，不轻置信的爱，你好像难推诚相待，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01161","html":"\u003cp class=\"epub-calibre1\">同时却又好像无言不採：看来真奇怪。\u003c/p>\n","text":"同时却又好像无言不採：看来真奇怪。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01162","html":"\u003cp class=\"epub-calibre1\">走极端、尽极限的是你的快乐和悲哀。\u003c/p>\n","text":"走极端、尽极限的是你的快乐和悲哀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01163","html":"\u003cp class=\"epub-calibre1\">绝望和希望，同样弄得你滑稽又痴呆。\u003c/p>\n","text":"绝望和希望，同样弄得你滑稽又痴呆。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01164","html":"\u003cp class=\"epub-calibre1\">你想入非非，把快乐胡琢磨，来宽慰心怀。\u003c/p>\n","text":"你想入非非，把快乐胡琢磨，来宽慰心怀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01165","html":"\u003cp class=\"epub-calibre1\">又离奇地琢磨悲哀，弄得自己死去活来。\u003c/p>\n","text":"又离奇地琢磨悲哀，弄得自己死去活来。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01166","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01167","html":"\u003cp class=\"epub-calibre1\">她现在把她已织成的东西又都拆开，\u003c/p>\n","text":"她现在把她已织成的东西又都拆开，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01168","html":"\u003cp class=\"epub-calibre1\">因为阿都尼还在，那死神就无可指摘。\u003c/p>\n","text":"因为阿都尼还在，那死神就无可指摘。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01169","html":"\u003cp class=\"epub-calibre1\">她刚才说他一钱不值并非她的本怀。\u003c/p>\n","text":"她刚才说他一钱不值并非她的本怀。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01170","html":"\u003cp class=\"epub-calibre1\">她现在给他那可恨的名字贴金敷彩。\u003c/p>\n","text":"她现在给他那可恨的名字贴金敷彩。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01171","html":"\u003cp class=\"epub-calibre1\">她叫他坟之国王，国王之坟，把他来推戴。\u003c/p>\n","text":"她叫他坟之国王，国王之坟，把他来推戴。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01172","html":"\u003cp class=\"epub-calibre1\">一切有生，他最尊贵，他应受到一切崇拜。\u003c/p>\n","text":"一切有生，他最尊贵，他应受到一切崇拜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01173","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01174","html":"\u003cp class=\"epub-calibre1\">“甜美的死神，”她说，“刚才的话都是胡扯。\u003c/p>\n","text":"“甜美的死神，”她说，“刚才的话都是胡扯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01175","html":"\u003cp class=\"epub-calibre1\">因为，我看到了野猪——那个残暴的家伙，\u003c/p>\n","text":"因为，我看到了野猪——那个残暴的家伙，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01176","html":"\u003cp class=\"epub-calibre1\">就吓得直打哆嗦，所以我请你原谅我。\u003c/p>\n","text":"就吓得直打哆嗦，所以我请你原谅我。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01177","html":"\u003cp class=\"epub-calibre1\">那东西，不懂什么叫仁慈，只一味凶恶。\u003c/p>\n","text":"那东西，不懂什么叫仁慈，只一味凶恶。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01178","html":"\u003cp class=\"epub-calibre1\">因此，温柔的黑阴影，我得对你把实话说：\u003c/p>\n","text":"因此，温柔的黑阴影，我得对你把实话说：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01179","html":"\u003cp class=\"epub-calibre1\">我怕我的所爱遭不幸，才对你大动唇舌。\u003c/p>\n","text":"我怕我的所爱遭不幸，才对你大动唇舌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01180","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01181","html":"\u003cp class=\"epub-calibre1\">“那不是我的错。野猪惹得我乱道胡说。\u003c/p>\n","text":"“那不是我的错。野猪惹得我乱道胡说。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01182","html":"\u003cp class=\"epub-calibre1\">无形影的掌权者，有怨气请对它发作。\u003c/p>\n","text":"无形影的掌权者，有怨气请对它发作。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01183","html":"\u003cp class=\"epub-calibre1\">侮辱冤枉你的，本是那个肮脏的家伙。\u003c/p>\n","text":"侮辱冤枉你的，本是那个肮脏的家伙。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01184","html":"\u003cp class=\"epub-calibre1\">我只受命执行，它才是诬蔑的主使者。\u003c/p>\n","text":"我只受命执行，它才是诬蔑的主使者。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01185","html":"\u003cp class=\"epub-calibre1\">悲痛本来有两条长舌。像女人那样软弱，\u003c/p>\n","text":"悲痛本来有两条长舌。像女人那样软弱，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01186","html":"\u003cp class=\"epub-calibre1\">若无十人的本领，就难把二舌制伏束缚。”\u003c/p>\n","text":"若无十人的本领，就难把二舌制伏束缚。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01187","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01188","html":"\u003cp class=\"epub-calibre1\">这样，她因为希望阿都尼还在世上，\u003c/p>\n","text":"这样，她因为希望阿都尼还在世上，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01189","html":"\u003cp class=\"epub-calibre1\">就把原先莽撞的恐惧疑虑渐渐扫光；\u003c/p>\n","text":"就把原先莽撞的恐惧疑虑渐渐扫光；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01190","html":"\u003cp class=\"epub-calibre1\">又因为希望他的美将来更灿烂辉煌，\u003c/p>\n","text":"又因为希望他的美将来更灿烂辉煌，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01191","html":"\u003cp class=\"epub-calibre1\">还卑躬屈节地把死神又奉承、又赞扬，\u003c/p>\n","text":"还卑躬屈节地把死神又奉承、又赞扬，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01192","html":"\u003cp class=\"epub-calibre1\">把死者的坟穴、墓志、碑碣、雕像和行状，\u003c/p>\n","text":"把死者的坟穴、墓志、碑碣、雕像和行状，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01193","html":"\u003cp class=\"epub-calibre1\">死神的胜利、凯旋和荣光，都大讲而特讲。\u003c/p>\n","text":"死神的胜利、凯旋和荣光，都大讲而特讲。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01194","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01195","html":"\u003cp class=\"epub-calibre1\">“哦，天帝啊，”她说，“我真正是拙笨愚蠢，\u003c/p>\n","text":"“哦，天帝啊，”她说，“我真正是拙笨愚蠢，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01196","html":"\u003cp class=\"epub-calibre1\">竟能因疑虑惊惧而思想乱，头脑昏，\u003c/p>\n","text":"竟能因疑虑惊惧而思想乱，头脑昏，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01197","html":"\u003cp class=\"epub-calibre1\">把活人当死人。其实他要永远长存，\u003c/p>\n","text":"把活人当死人。其实他要永远长存，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01198","html":"\u003cp class=\"epub-calibre1\">除非一切尽毁灭，天地万物共沉沦。\u003c/p>\n","text":"除非一切尽毁灭，天地万物共沉沦。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01199","html":"\u003cp class=\"epub-calibre1\">因为他若一旦死去，‘美’也就要同归于尽。\u003c/p>\n","text":"因为他若一旦死去，‘美’也就要同归于尽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01200","html":"\u003cp class=\"epub-calibre1\">‘美’若一死，宇宙也就要再一度混乱混沌。\u003c/p>\n","text":"‘美’若一死，宇宙也就要再一度混乱混沌。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01201","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01202","html":"\u003cp class=\"epub-calibre1\">“唉唉，痴傻的‘爱’，你老满怀的恐惧疑猜，\u003c/p>\n","text":"“唉唉，痴傻的‘爱’，你老满怀的恐惧疑猜，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01203","html":"\u003cp class=\"epub-calibre1\">就像身带珠宝的人，有盗贼四外徘徊；\u003c/p>\n","text":"就像身带珠宝的人，有盗贼四外徘徊；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01204","html":"\u003cp class=\"epub-calibre1\">耳不能闻、目不能见的琐细微小事态，\u003c/p>\n","text":"耳不能闻、目不能见的琐细微小事态，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01205","html":"\u003cp class=\"epub-calibre1\">你那忐忑的心却偏能胡测度，瞎悲哀。”\u003c/p>\n","text":"你那忐忑的心却偏能胡测度，瞎悲哀。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01206","html":"\u003cp class=\"epub-calibre1\">刚说到这里，只听得欢乐的号角声传来，\u003c/p>\n","text":"刚说到这里，只听得欢乐的号角声传来，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01207","html":"\u003cp class=\"epub-calibre1\">她于是不觉欢跃，虽然刚才还身在苦海。\u003c/p>\n","text":"她于是不觉欢跃，虽然刚才还身在苦海。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01208","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01209","html":"\u003cp class=\"epub-calibre1\">她嗖地跑去，就像鹞鹰一掣而不可制，\u003c/p>\n","text":"她嗖地跑去，就像鹞鹰一掣而不可制，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01210","html":"\u003cp class=\"epub-calibre1\">步履轻盈，经过的地方草都照旧直立。\u003c/p>\n","text":"步履轻盈，经过的地方草都照旧直立。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01211","html":"\u003cp class=\"epub-calibre1\">她正匆匆前奔，却不幸一下看在眼里：\u003c/p>\n","text":"她正匆匆前奔，却不幸一下看在眼里：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01212","html":"\u003cp class=\"epub-calibre1\">她那俊秀的所爱，在野猪的牙下身死。\u003c/p>\n","text":"她那俊秀的所爱，在野猪的牙下身死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01213","html":"\u003cp class=\"epub-calibre1\">她一见那样，双目立刻失明，好像受了电殛；\u003c/p>\n","text":"她一见那样，双目立刻失明，好像受了电殛；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01214","html":"\u003cp class=\"epub-calibre1\">又像星星不敢和白日争光，一下退避躲起；\u003c/p>\n","text":"又像星星不敢和白日争光，一下退避躲起；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01215","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01216","html":"\u003cp class=\"epub-calibre1\">又像一个蜗牛，柔嫩的触角一受打击，\u003c/p>\n","text":"又像一个蜗牛，柔嫩的触角一受打击，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01217","html":"\u003cp class=\"epub-calibre1\">就疼痛难忍，连忙缩回到自己的壳里，\u003c/p>\n","text":"就疼痛难忍，连忙缩回到自己的壳里，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01218","html":"\u003cp class=\"epub-calibre1\">在那儿蜷伏，如同憋死一样屏气敛息，\u003c/p>\n","text":"在那儿蜷伏，如同憋死一样屏气敛息，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01219","html":"\u003cp class=\"epub-calibre1\">过了好久好久，还不敢再把头角显露。\u003c/p>\n","text":"过了好久好久，还不敢再把头角显露。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01220","html":"\u003cp class=\"epub-calibre1\">她当时一看到他这样血淋漓、肉模糊，\u003c/p>\n","text":"她当时一看到他这样血淋漓、肉模糊，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01221","html":"\u003cp class=\"epub-calibre1\">她的眼睛就一下逃到头上幽暗的深处，\u003c/p>\n","text":"她的眼睛就一下逃到头上幽暗的深处，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01222","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01223","html":"\u003cp class=\"epub-calibre1\">在那儿它们把职务交卸，把光明委弃，\u003c/p>\n","text":"在那儿它们把职务交卸，把光明委弃，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01224","html":"\u003cp class=\"epub-calibre1\">全听凭她那骚动的脑府来安排处治。\u003c/p>\n","text":"全听凭她那骚动的脑府来安排处治。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01225","html":"\u003cp class=\"epub-calibre1\">脑府就叫它们和昏沉的夜做伴为侣，\u003c/p>\n","text":"脑府就叫它们和昏沉的夜做伴为侣，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01226","html":"\u003cp class=\"epub-calibre1\">不再看外面的景象，免得叫心府悲凄。\u003c/p>\n","text":"不再看外面的景象，免得叫心府悲凄。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01227","html":"\u003cp class=\"epub-calibre1\">因为她的心，像宝座上神魂无主的皇帝，\u003c/p>\n","text":"因为她的心，像宝座上神魂无主的皇帝，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01228","html":"\u003cp class=\"epub-calibre1\">受眼睛传来的启示，呻吟不止，愁苦欲死。\u003c/p>\n","text":"受眼睛传来的启示，呻吟不止，愁苦欲死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01229","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01230","html":"\u003cp class=\"epub-calibre1\">于是所有的臣子，也无不战栗俯伏，\u003c/p>\n","text":"于是所有的臣子，也无不战栗俯伏，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01231","html":"\u003cp class=\"epub-calibre1\">好像烈风闭在大地之下，硬夺出路，\u003c/p>\n","text":"好像烈风闭在大地之下，硬夺出路，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01232","html":"\u003cp class=\"epub-calibre1\">就引起了地震和海啸、山崩和水沸，\u003c/p>\n","text":"就引起了地震和海啸、山崩和水沸，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01233","html":"\u003cp class=\"epub-calibre1\">把人吓得身出冷汗，吓得心乱无主。\u003c/p>\n","text":"把人吓得身出冷汗，吓得心乱无主。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01234","html":"\u003cp class=\"epub-calibre1\">她的心就这样骚乱，使四肢百骸齐惊怖，\u003c/p>\n","text":"她的心就这样骚乱，使四肢百骸齐惊怖，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01235","html":"\u003cp class=\"epub-calibre1\">于是她的眼光又从潜伏的暗室中射出。\u003c/p>\n","text":"于是她的眼光又从潜伏的暗室中射出。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01236","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01237","html":"\u003cp class=\"epub-calibre1\">她又看见了本来不愿看的极惨奇丑：\u003c/p>\n","text":"她又看见了本来不愿看的极惨奇丑：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01238","html":"\u003cp class=\"epub-calibre1\">野猪在他的嫩腰上扎的那个大伤口。\u003c/p>\n","text":"野猪在他的嫩腰上扎的那个大伤口。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01239","html":"\u003cp class=\"epub-calibre1\">原先白如百合的地方，现在殷红渍透，\u003c/p>\n","text":"原先白如百合的地方，现在殷红渍透，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01240","html":"\u003cp class=\"epub-calibre1\">好像伤口为他悲痛，血泪喷洒无尽休。\u003c/p>\n","text":"好像伤口为他悲痛，血泪喷洒无尽休。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01241","html":"\u003cp class=\"epub-calibre1\">在他身旁，不论是花是草，不论是苗是莠，\u003c/p>\n","text":"在他身旁，不论是花是草，不论是苗是莠，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01242","html":"\u003cp class=\"epub-calibre1\">好像无不染上他的血，像他一样把血流。\u003c/p>\n","text":"好像无不染上他的血，像他一样把血流。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01243","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01244","html":"\u003cp class=\"epub-calibre1\">可怜的维纳斯，看到花草都惋惜、同情；\u003c/p>\n","text":"可怜的维纳斯，看到花草都惋惜、同情；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01245","html":"\u003cp class=\"epub-calibre1\">她的头垂在肩上，软绵绵地不能直挺。\u003c/p>\n","text":"她的头垂在肩上，软绵绵地不能直挺。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01246","html":"\u003cp class=\"epub-calibre1\">她只哑然无声伤悼，像癫了一般悲痛，\u003c/p>\n","text":"她只哑然无声伤悼，像癫了一般悲痛，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01247","html":"\u003cp class=\"epub-calibre1\">她的嗓子忘了如何发声，骨节也不会动。\u003c/p>\n","text":"她的嗓子忘了如何发声，骨节也不会动。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01248","html":"\u003cp class=\"epub-calibre1\">她的眼一直哭到现在，都哭得如痴似疯。\u003c/p>\n","text":"她的眼一直哭到现在，都哭得如痴似疯。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01249","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01250","html":"\u003cp class=\"epub-calibre1\">她对他的伤，目不转睛地一直细端详；\u003c/p>\n","text":"她对他的伤，目不转睛地一直细端详；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01251","html":"\u003cp class=\"epub-calibre1\">眼都看花了，把一处伤看作了三处伤。\u003c/p>\n","text":"眼都看花了，把一处伤看作了三处伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01252","html":"\u003cp class=\"epub-calibre1\">她对自己的眼申斥，说不该胡乱撒谎，\u003c/p>\n","text":"她对自己的眼申斥，说不该胡乱撒谎，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01253","html":"\u003cp class=\"epub-calibre1\">把完好的地方说成血肉模糊的模样。\u003c/p>\n","text":"把完好的地方说成血肉模糊的模样。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01254","html":"\u003cp class=\"epub-calibre1\">他的脸好似成了两个，肢体也像成了双；\u003c/p>\n","text":"他的脸好似成了两个，肢体也像成了双；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01255","html":"\u003cp class=\"epub-calibre1\">因为心里一慌，看东西就往往渺渺茫茫。\u003c/p>\n","text":"因为心里一慌，看东西就往往渺渺茫茫。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01256","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01257","html":"\u003cp class=\"epub-calibre1\">“只死了一个，我就已说不出来地悲痛，\u003c/p>\n","text":"“只死了一个，我就已说不出来地悲痛，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01258","html":"\u003cp class=\"epub-calibre1\">哪能受得了两个阿都尼身卧血泊中？\u003c/p>\n","text":"哪能受得了两个阿都尼身卧血泊中？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01259","html":"\u003cp class=\"epub-calibre1\">我已经无余气可再叹，无余泪可再倾。\u003c/p>\n","text":"我已经无余气可再叹，无余泪可再倾。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01260","html":"\u003cp class=\"epub-calibre1\">我两只眼火一样红，一颗心铅一般重。\u003c/p>\n","text":"我两只眼火一样红，一颗心铅一般重。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01261","html":"\u003cp class=\"epub-calibre1\">铅一般的心啊，顶好叫这火一样的眼烧熔！\u003c/p>\n","text":"铅一般的心啊，顶好叫这火一样的眼烧熔！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01262","html":"\u003cp class=\"epub-calibre1\">这样，我便可随热爱滴滴化去，了却一生。\u003c/p>\n","text":"这样，我便可随热爱滴滴化去，了却一生。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01263","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01264","html":"\u003cp class=\"epub-calibre1\">“唉！可怜的人世！你失去的是甚样珍异！\u003c/p>\n","text":"“唉！可怜的人世！你失去的是甚样珍异！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01265","html":"\u003cp class=\"epub-calibre1\">哪里还有秀美的人物值得瞻仰顾视？\u003c/p>\n","text":"哪里还有秀美的人物值得瞻仰顾视？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01266","html":"\u003cp class=\"epub-calibre1\">哪里还有语声能那样悦人耳，快人意？\u003c/p>\n","text":"哪里还有语声能那样悦人耳，快人意？\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01267","html":"\u003cp class=\"epub-calibre1\">不论将来，不论过去，你都再一无可取。\u003c/p>\n","text":"不论将来，不论过去，你都再一无可取。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01268","html":"\u003cp class=\"epub-calibre1\">花儿固然芬芳清逸，绚烂璀璨，鲜艳美丽，\u003c/p>\n","text":"花儿固然芬芳清逸，绚烂璀璨，鲜艳美丽，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01269","html":"\u003cp class=\"epub-calibre1\">但是真正甜蜜的美，却只和他同生共死。\u003c/p>\n","text":"但是真正甜蜜的美，却只和他同生共死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01270","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01271","html":"\u003cp class=\"epub-calibre1\">“从现在起，你再不需要披面纱，戴帽子，\u003c/p>\n","text":"“从现在起，你再不需要披面纱，戴帽子，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01272","html":"\u003cp class=\"epub-calibre1\">因为风和日，不会用尽方法想去吻你。\u003c/p>\n","text":"因为风和日，不会用尽方法想去吻你。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01273","html":"\u003cp class=\"epub-calibre1\">你本无可畏惧，只因为你本无可丢失。\u003c/p>\n","text":"你本无可畏惧，只因为你本无可丢失。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01274","html":"\u003cp class=\"epub-calibre1\">对于你，日只瞋之以目，风只嗤之以鼻。\u003c/p>\n","text":"对于你，日只瞋之以目，风只嗤之以鼻。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01275","html":"\u003cp class=\"epub-calibre1\">但阿都尼生的时候，多情的峭风和烈日，\u003c/p>\n","text":"但阿都尼生的时候，多情的峭风和烈日，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01276","html":"\u003cp class=\"epub-calibre1\">却像两个隐在暗处的贼，掠夺他的美丽。\u003c/p>\n","text":"却像两个隐在暗处的贼，掠夺他的美丽。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01277","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01278","html":"\u003cp class=\"epub-calibre1\">“因为如此，所以他才不得不戴帽子，\u003c/p>\n","text":"“因为如此，所以他才不得不戴帽子，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01279","html":"\u003cp class=\"epub-calibre1\">但辉煌的太阳，偏从帽子下面窥视。\u003c/p>\n","text":"但辉煌的太阳，偏从帽子下面窥视。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01280","html":"\u003cp class=\"epub-calibre1\">风也吹他的帽子，想要把帽子吹去，\u003c/p>\n","text":"风也吹他的帽子，想要把帽子吹去，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01281","html":"\u003cp class=\"epub-calibre1\">以便和他的鬈发游戏。于是他哭泣。\u003c/p>\n","text":"以便和他的鬈发游戏。于是他哭泣。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01282","html":"\u003cp class=\"epub-calibre1\">太阳和风一见他如此，便怜他年幼齿稚，\u003c/p>\n","text":"太阳和风一见他如此，便怜他年幼齿稚，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01283","html":"\u003cp class=\"epub-calibre1\">又看谁能把他的泪先擦干了，互相比试。\u003c/p>\n","text":"又看谁能把他的泪先擦干了，互相比试。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01284","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01285","html":"\u003cp class=\"epub-calibre1\">“狮子为赏识他的美，在篱后偷偷跟随，\u003c/p>\n","text":"“狮子为赏识他的美，在篱后偷偷跟随，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01286","html":"\u003cp class=\"epub-calibre1\">不敢露面儿，恐怕他见了惊吓而后退。\u003c/p>\n","text":"不敢露面儿，恐怕他见了惊吓而后退。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01287","html":"\u003cp class=\"epub-calibre1\">他唱歌的时候，猛虎听见了也都心醉，\u003c/p>\n","text":"他唱歌的时候，猛虎听见了也都心醉，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01288","html":"\u003cp class=\"epub-calibre1\">变得老实、温柔、驯顺，不像个兽中之魁。\u003c/p>\n","text":"变得老实、温柔、驯顺，不像个兽中之魁。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01289","html":"\u003cp class=\"epub-calibre1\">狼正大嚼牺牲，听到他说话的声音优美，\u003c/p>\n","text":"狼正大嚼牺牲，听到他说话的声音优美，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01290","html":"\u003cp class=\"epub-calibre1\">也停止了饕餮，一天都不再和羊羔作对。\u003c/p>\n","text":"也停止了饕餮，一天都不再和羊羔作对。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01291","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01292","html":"\u003cp class=\"epub-calibre1\">“他若溪边暂立闲行，把影子映在水中，\u003c/p>\n","text":"“他若溪边暂立闲行，把影子映在水中，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01293","html":"\u003cp class=\"epub-calibre1\">鱼都聚在影子上面，展金鳃唼喋涵泳。\u003c/p>\n","text":"鱼都聚在影子上面，展金鳃唼喋涵泳。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01294","html":"\u003cp class=\"epub-calibre1\">他在鸟儿跟前，鸟儿也又喜悦、又欢腾，\u003c/p>\n","text":"他在鸟儿跟前，鸟儿也又喜悦、又欢腾，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01295","html":"\u003cp class=\"epub-calibre1\">有的唱歌给他听，有的就用尖喙轻灵，\u003c/p>\n","text":"有的唱歌给他听，有的就用尖喙轻灵，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01296","html":"\u003cp class=\"epub-calibre1\">给他含来桑葚丛丛，或者樱桃又圆又红。\u003c/p>\n","text":"给他含来桑葚丛丛，或者樱桃又圆又红。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01297","html":"\u003cp class=\"epub-calibre1\">他把秀色供它们赏，它们就用果子回敬。\u003c/p>\n","text":"他把秀色供它们赏，它们就用果子回敬。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01298","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01299","html":"\u003cp class=\"epub-calibre1\">“但是这个狰狞龌龊、嘴如刺猬的野猪，\u003c/p>\n","text":"“但是这个狰狞龌龊、嘴如刺猬的野猪，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01300","html":"\u003cp class=\"epub-calibre1\">却老把眼睛瞅着地上，到处寻找坟墓。\u003c/p>\n","text":"却老把眼睛瞅着地上，到处寻找坟墓。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01301","html":"\u003cp class=\"epub-calibre1\">阿都尼秀美的好皮囊，它永无法目睹。\u003c/p>\n","text":"阿都尼秀美的好皮囊，它永无法目睹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01302","html":"\u003cp class=\"epub-calibre1\">你若不信，请看它要怎样迎接阿都尼：\u003c/p>\n","text":"你若不信，请看它要怎样迎接阿都尼：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01303","html":"\u003cp class=\"epub-calibre1\">如果它能看见他的脸，那我决深信不疑，\u003c/p>\n","text":"如果它能看见他的脸，那我决深信不疑，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01304","html":"\u003cp class=\"epub-calibre1\">它就一定想要吻他，而因吻他把他害死。\u003c/p>\n","text":"它就一定想要吻他，而因吻他把他害死。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01305","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01306","html":"\u003cp class=\"epub-calibre1\">“不错，不错，阿都尼就这样叫它害死：\u003c/p>\n","text":"“不错，不错，阿都尼就这样叫它害死：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01307","html":"\u003cp class=\"epub-calibre1\">原先他用尖枪，朝着野猪刺去之时，\u003c/p>\n","text":"原先他用尖枪，朝着野猪刺去之时，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01308","html":"\u003cp class=\"epub-calibre1\">野猪并没想要在他身上磨牙砺齿。\u003c/p>\n","text":"野猪并没想要在他身上磨牙砺齿。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01309","html":"\u003cp class=\"epub-calibre1\">它只想用接吻的方式，把他来阻止，\u003c/p>\n","text":"它只想用接吻的方式，把他来阻止，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01310","html":"\u003cp class=\"epub-calibre1\">哪知多情的野猪刚把嘴往他腰上一触，\u003c/p>\n","text":"哪知多情的野猪刚把嘴往他腰上一触，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01311","html":"\u003cp class=\"epub-calibre1\">就不知不觉，把牙扎到他那柔嫩的鼠蹊。\u003c/p>\n","text":"就不知不觉，把牙扎到他那柔嫩的鼠蹊。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01312","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01313","html":"\u003cp class=\"epub-calibre1\">“我得承认，我的牙若长得和野猪一样，\u003c/p>\n","text":"“我得承认，我的牙若长得和野猪一样，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01314","html":"\u003cp class=\"epub-calibre1\">那我早就要因为吻他而叫他把命丧。\u003c/p>\n","text":"那我早就要因为吻他而叫他把命丧。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01315","html":"\u003cp class=\"epub-calibre1\">他现已不在世上，他的青春大梦一场，\u003c/p>\n","text":"他现已不在世上，他的青春大梦一场，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01316","html":"\u003cp class=\"epub-calibre1\">永未给我的青春福祥，叫我更觉悲伤。”\u003c/p>\n","text":"永未给我的青春福祥，叫我更觉悲伤。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01317","html":"\u003cp class=\"epub-calibre1\">她说到这里，就一下倒在她站的那地方，\u003c/p>\n","text":"她说到这里，就一下倒在她站的那地方，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01318","html":"\u003cp class=\"epub-calibre1\">他开始凝固的血，也染在她美丽的脸上。\u003c/p>\n","text":"他开始凝固的血，也染在她美丽的脸上。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01319","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01320","html":"\u003cp class=\"epub-calibre1\">她往他唇上望，他的唇灰白非复旧样；\u003c/p>\n","text":"她往他唇上望，他的唇灰白非复旧样；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01321","html":"\u003cp class=\"epub-calibre1\">她拉他的手，他的手早已经僵硬冰凉；\u003c/p>\n","text":"她拉他的手，他的手早已经僵硬冰凉；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01322","html":"\u003cp class=\"epub-calibre1\">她在他耳旁低声细说她的忧怨悲伤，\u003c/p>\n","text":"她在他耳旁低声细说她的忧怨悲伤，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01323","html":"\u003cp class=\"epub-calibre1\">仿佛他的耳朵还能听见她哀诉愁肠；\u003c/p>\n","text":"仿佛他的耳朵还能听见她哀诉愁肠；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01324","html":"\u003cp class=\"epub-calibre1\">她把他紧紧贴在眼上的眼皮分掰成两，\u003c/p>\n","text":"她把他紧紧贴在眼上的眼皮分掰成两，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01325","html":"\u003cp class=\"epub-calibre1\">只见原先那两盏灯已经熄灭，昏暗无光。\u003c/p>\n","text":"只见原先那两盏灯已经熄灭，昏暗无光。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01326","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01327","html":"\u003cp class=\"epub-calibre1\">那本是两面明镜；她曾见自己的倩影，\u003c/p>\n","text":"那本是两面明镜；她曾见自己的倩影，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01328","html":"\u003cp class=\"epub-calibre1\">不止千回万遍，在那里面玲珑地反映。\u003c/p>\n","text":"不止千回万遍，在那里面玲珑地反映。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01329","html":"\u003cp class=\"epub-calibre1\">它们本是眼中之英，但一旦失去功能，\u003c/p>\n","text":"它们本是眼中之英，但一旦失去功能，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01330","html":"\u003cp class=\"epub-calibre1\">所有的美，就永远也起不了美的作用。\u003c/p>\n","text":"所有的美，就永远也起不了美的作用。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01331","html":"\u003cp class=\"epub-calibre1\">“你虽已死，白日却仍旧一样地清澈晶明，\u003c/p>\n","text":"“你虽已死，白日却仍旧一样地清澈晶明，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01332","html":"\u003cp class=\"epub-calibre1\">你万世的俊英啊！”她说，“这真是要我的命！\u003c/p>\n","text":"你万世的俊英啊！”她说，“这真是要我的命！\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01333","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01334","html":"\u003cp class=\"epub-calibre1\">“你今既已丧命，那我可以预言一通：\u003c/p>\n","text":"“你今既已丧命，那我可以预言一通：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01335","html":"\u003cp class=\"epub-calibre1\">从此以后，‘爱’要永远有‘忧愁’作随从；\u003c/p>\n","text":"从此以后，‘爱’要永远有‘忧愁’作随从；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01336","html":"\u003cp class=\"epub-calibre1\">它要永远有‘嫉妒’来把它服侍供奉。\u003c/p>\n","text":"它要永远有‘嫉妒’来把它服侍供奉。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01337","html":"\u003cp class=\"epub-calibre1\">它虽以甜蜜始，却永远要以烦恼终。\u003c/p>\n","text":"它虽以甜蜜始，却永远要以烦恼终。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01338","html":"\u003cp class=\"epub-calibre1\">凡情之所钟，永远要贵贱参差，高下难同，\u003c/p>\n","text":"凡情之所钟，永远要贵贱参差，高下难同，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01339","html":"\u003cp class=\"epub-calibre1\">因此，它的快乐永远要敌不过它的苦痛。\u003c/p>\n","text":"因此，它的快乐永远要敌不过它的苦痛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01340","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01341","html":"\u003cp class=\"epub-calibre1\">“它永要负心薄幸、反复无常、杨花水性；\u003c/p>\n","text":"“它永要负心薄幸、反复无常、杨花水性；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01342","html":"\u003cp class=\"epub-calibre1\">要在萌芽时，就一瞬间受摧残而凋零；\u003c/p>\n","text":"要在萌芽时，就一瞬间受摧残而凋零；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01343","html":"\u003cp class=\"epub-calibre1\">它要里面藏毒素，却用甜美粉饰外形，\u003c/p>\n","text":"它要里面藏毒素，却用甜美粉饰外形，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01344","html":"\u003cp class=\"epub-calibre1\">叫眼力最好的人，都受它的蒙骗欺哄；\u003c/p>\n","text":"叫眼力最好的人，都受它的蒙骗欺哄；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01345","html":"\u003cp class=\"epub-calibre1\">它能叫最强健精壮的变得最软弱无能；\u003c/p>\n","text":"它能叫最强健精壮的变得最软弱无能；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01346","html":"\u003cp class=\"epub-calibre1\">叫愚人伶牙俐齿，却叫智士不能出一声。\u003c/p>\n","text":"叫愚人伶牙俐齿，却叫智士不能出一声。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01347","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01348","html":"\u003cp class=\"epub-calibre1\">“它要锱铢必较，却又过分地放荡奢豪；\u003c/p>\n","text":"“它要锱铢必较，却又过分地放荡奢豪；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01349","html":"\u003cp class=\"epub-calibre1\">教给老迈龙钟的人飘飘然跳踊舞蹈，\u003c/p>\n","text":"教给老迈龙钟的人飘飘然跳踊舞蹈，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01350","html":"\u003cp class=\"epub-calibre1\">而好勇狠斗的强梁，却只能少安毋躁；\u003c/p>\n","text":"而好勇狠斗的强梁，却只能少安毋躁；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01351","html":"\u003cp class=\"epub-calibre1\">它把富人打倒，却给穷人财物和珠宝；\u003c/p>\n","text":"它把富人打倒，却给穷人财物和珠宝；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01352","html":"\u003cp class=\"epub-calibre1\">它温柔得一团棉软，又疯狂得大肆咆哮；\u003c/p>\n","text":"它温柔得一团棉软，又疯狂得大肆咆哮；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01353","html":"\u003cp class=\"epub-calibre1\">它叫老年人变成儿童，叫青年变得衰老。\u003c/p>\n","text":"它叫老年人变成儿童，叫青年变得衰老。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01354","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01355","html":"\u003cp class=\"epub-calibre1\">“无可恐惧的时候，它却偏偏要恐惧，\u003c/p>\n","text":"“无可恐惧的时候，它却偏偏要恐惧，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01356","html":"\u003cp class=\"epub-calibre1\">最应疑虑的时候，它却又毫不疑虑；\u003c/p>\n","text":"最应疑虑的时候，它却又毫不疑虑；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01357","html":"\u003cp class=\"epub-calibre1\">它一方面仁慈，另一方面却又狠戾；\u003c/p>\n","text":"它一方面仁慈，另一方面却又狠戾；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01358","html":"\u003cp class=\"epub-calibre1\">它好像最公平的时候，它就最诈欺；\u003c/p>\n","text":"它好像最公平的时候，它就最诈欺；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01359","html":"\u003cp class=\"epub-calibre1\">它最驯顺热烈的时候，它就最桀骜冷酷；\u003c/p>\n","text":"它最驯顺热烈的时候，它就最桀骜冷酷；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01360","html":"\u003cp class=\"epub-calibre1\">它叫懦夫变得大胆，却叫勇士变成懦夫。\u003c/p>\n","text":"它叫懦夫变得大胆，却叫勇士变成懦夫。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01361","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01362","html":"\u003cp class=\"epub-calibre1\">“它要激起战事，惹起一切可怕的变故；\u003c/p>\n","text":"“它要激起战事，惹起一切可怕的变故；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01363","html":"\u003cp class=\"epub-calibre1\">它要叫父子之间嫌隙日生，争端百出；\u003c/p>\n","text":"它要叫父子之间嫌隙日生，争端百出；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01364","html":"\u003cp class=\"epub-calibre1\">一切的不满，它全都尽力地护持扶助，\u003c/p>\n","text":"一切的不满，它全都尽力地护持扶助，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01365","html":"\u003cp class=\"epub-calibre1\">它们臭味相投，惟有干柴烈火可仿佛。\u003c/p>\n","text":"它们臭味相投，惟有干柴烈火可仿佛。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01366","html":"\u003cp class=\"epub-calibre1\">既然我的所爱还在少年，就叫死神召去，\u003c/p>\n","text":"既然我的所爱还在少年，就叫死神召去，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01367","html":"\u003cp class=\"epub-calibre1\">那么，一切情深的人都不许有爱的乐趣。”\u003c/p>\n","text":"那么，一切情深的人都不许有爱的乐趣。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01368","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01369","html":"\u003cp class=\"epub-calibre1\">她说到这里，躺在她旁边的那孩子，\u003c/p>\n","text":"她说到这里，躺在她旁边的那孩子，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01370","html":"\u003cp class=\"epub-calibre1\">慢慢地烟消雾散，只化得无踪无迹。\u003c/p>\n","text":"慢慢地烟消雾散，只化得无踪无迹。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01371","html":"\u003cp class=\"epub-calibre1\">于是，从他洒在地上的那片血泊里，\u003c/p>\n","text":"于是，从他洒在地上的那片血泊里，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01372","html":"\u003cp class=\"epub-calibre1\">一棵鲜红雪白相间的花一下涌起，\u003c/p>\n","text":"一棵鲜红雪白相间的花一下涌起，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01373","html":"\u003cp class=\"epub-calibre1\">非常地像他那种鲜丽红艳的圆圆血滴，\u003c/p>\n","text":"非常地像他那种鲜丽红艳的圆圆血滴，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01374","html":"\u003cp class=\"epub-calibre1\">在他那雪白的双颊上现出，分明又清晰。\u003c/p>\n","text":"在他那雪白的双颊上现出，分明又清晰。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01375","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01376","html":"\u003cp class=\"epub-calibre1\">她低下头去，闻那棵鲜花发出的香气。\u003c/p>\n","text":"她低下头去，闻那棵鲜花发出的香气。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01377","html":"\u003cp class=\"epub-calibre1\">她把这种香气和他当日喘的气比拟，\u003c/p>\n","text":"她把这种香气和他当日喘的气比拟，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01378","html":"\u003cp class=\"epub-calibre1\">她说：死亡既使阿都尼和她两下分离，\u003c/p>\n","text":"她说：死亡既使阿都尼和她两下分离，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01379","html":"\u003cp class=\"epub-calibre1\">那她的香怀就要从此永供这花栖息。\u003c/p>\n","text":"那她的香怀就要从此永供这花栖息。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01380","html":"\u003cp class=\"epub-calibre1\">她把花枝折，只见折的地方绿汁流不止。\u003c/p>\n","text":"她把花枝折，只见折的地方绿汁流不止。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01381","html":"\u003cp class=\"epub-calibre1\">她说，这就是花的泪水，为死去的他惋惜。\u003c/p>\n","text":"她说，这就是花的泪水，为死去的他惋惜。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01382","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01383","html":"\u003cp class=\"epub-calibre1\">“儿子已经很香，你父亲却比你还要香；\u003c/p>\n","text":"“儿子已经很香，你父亲却比你还要香；\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01384","html":"\u003cp class=\"epub-calibre1\">可怜的花，”她说，“你和你父亲完全相像，\u003c/p>\n","text":"可怜的花，”她说，“你和你父亲完全相像，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01385","html":"\u003cp class=\"epub-calibre1\">他就是有一丁点儿烦恼，就流泪悲伤。\u003c/p>\n","text":"他就是有一丁点儿烦恼，就流泪悲伤。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01386","html":"\u003cp class=\"epub-calibre1\">他抱定了自生自灭、自存自亡的愿望。\u003c/p>\n","text":"他抱定了自生自灭、自存自亡的愿望。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01387","html":"\u003cp class=\"epub-calibre1\">这也是你的愿望。不过有句话你不要忘：\u003c/p>\n","text":"这也是你的愿望。不过有句话你不要忘：\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01388","html":"\u003cp class=\"epub-calibre1\">他的血就把你化，我的怀就要把你抚养。\u003c/p>\n","text":"他的血就把你化，我的怀就要把你抚养。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01389","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01390","html":"\u003cp class=\"epub-calibre1\">“你父亲当日的床榻，就安在我的怀中，\u003c/p>\n","text":"“你父亲当日的床榻，就安在我的怀中，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01391","html":"\u003cp class=\"epub-calibre1\">你是他的继承人，这床理应归你受用。\u003c/p>\n","text":"你是他的继承人，这床理应归你受用。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01392","html":"\u003cp class=\"epub-calibre1\">所以，你要在这个软摇篮里安身立命。\u003c/p>\n","text":"所以，你要在这个软摇篮里安身立命。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01393","html":"\u003cp class=\"epub-calibre1\">我这跳动的心，要日夜给你把它摆动。\u003c/p>\n","text":"我这跳动的心，要日夜给你把它摆动。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01394","html":"\u003cp class=\"epub-calibre1\">我每一点钟里面要连一分钟也都不停，\u003c/p>\n","text":"我每一点钟里面要连一分钟也都不停，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01395","html":"\u003cp class=\"epub-calibre1\">和我甜蜜的所爱化的花接吻，把它抚弄。”\u003c/p>\n","text":"和我甜蜜的所爱化的花接吻，把它抚弄。”\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01396","html":"\u003cp class=\"epub-calibre1\">\u003cbr class=\"epub-calibre10\">\u003c/p>\n","text":"\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01397","html":"\u003cp class=\"epub-calibre1\">她对尘世已厌倦，就匆匆起身无留恋，\u003c/p>\n","text":"她对尘世已厌倦，就匆匆起身无留恋，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01398","html":"\u003cp class=\"epub-calibre1\">驾起那两只鸽子，要离开纷扰的人间。\u003c/p>\n","text":"驾起那两只鸽子，要离开纷扰的人间。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01399","html":"\u003cp class=\"epub-calibre1\">她在车上坐好，鸽子立刻往空中盘旋，\u003c/p>\n","text":"她在车上坐好，鸽子立刻往空中盘旋，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01400","html":"\u003cp class=\"epub-calibre1\">拉着香辇轻茜，通过天宇寥廓路漫漫，\u003c/p>\n","text":"拉着香辇轻茜，通过天宇寥廓路漫漫，\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01401","html":"\u003cp class=\"epub-calibre1\">朝着巴福斯\u003ca id=\"epub-part0043-w004\">\u003c/a>\u003ca href=\"#epub-part0043-m004\" data-source-anchor=\"m004\">\u003csup class=\"epub-calibre13\">[4]\u003c/sup>\u003c/a>的去程，把莽莽尘寰抛得远。\u003c/p>\n","text":"朝着巴福斯[4]的去程，把莽莽尘寰抛得远。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01402","html":"\u003cp class=\"epub-calibre1\">在那岛上，爱后打算静居深藏，不再露面。\u003c/p>\n","text":"在那岛上，爱后打算静居深藏，不再露面。\n","sourceAnchor":null,"tag":"p"}],"heading":"维纳斯与阿都尼","headingLevel":3,"sourceAnchor":"a1049"},{"id":"part0043-section-002","label":"注释","kind":"notes","blocks":[{"id":"part0043-01403","html":"\u003chr class=\"epub-calibre14\">","text":"","sourceAnchor":null,"tag":"hr"},{"id":"part0043-01404","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0043-m001\">\u003c/a>\u003ca href=\"#epub-part0043-w001\" data-source-anchor=\"w001\">[1]\u003c/a>那耳喀索斯（Narcissus），希腊神话里的美少年，他谁也不爱，只爱照映在泉水里自己的影子，为自己消瘦而死，化成水仙花。\u003c/p>\n","text":" [1]那耳喀索斯（Narcissus），希腊神话里的美少年，他谁也不爱，只爱照映在泉水里自己的影子，为自己消瘦而死，化成水仙花。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01405","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0043-m002\">\u003c/a>\u003ca href=\"#epub-part0043-w002\" data-source-anchor=\"w002\">[2]\u003c/a>产于西班牙的一种矮马。\u003c/p>\n","text":" [2]产于西班牙的一种矮马。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01406","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0043-m003\">\u003c/a>\u003ca href=\"#epub-part0043-w003\" data-source-anchor=\"w003\">[3]\u003c/a>宙斯的儿子，因杀子珀罗普斯以饷天神，被罚入冥土永受饥渴之苦，虽然身子浸在水中，头上悬着鲜果，但都永远可望而不可即。\u003c/p>\n","text":" [3]宙斯的儿子，因杀子珀罗普斯以饷天神，被罚入冥土永受饥渴之苦，虽然身子浸在水中，头上悬着鲜果，但都永远可望而不可即。\n","sourceAnchor":null,"tag":"p"},{"id":"part0043-01407","html":"\u003cp class=\"epub-note\"> \u003ca id=\"epub-part0043-m004\">\u003c/a>\u003ca href=\"#epub-part0043-w004\" data-source-anchor=\"w004\">[4]\u003c/a>塞浦路斯岛上的古城名，建有维纳斯神庙。\u003c/p>\n","text":" [4]塞浦路斯岛上的古城名，建有维纳斯神庙。\n","sourceAnchor":null,"tag":"p"}],"heading":"","headingLevel":null,"sourceAnchor":null}],"language":"zh","alignment":"none","source":{"type":"user-provided-epub","title":"莎士比亚全集","publisher":"人民文学出版社","isbn":"978-7-02-010568-7","epubSha256":"e0385e88e1428b9accb344d45650a0f52ea1d917cbb12009036b2fb32fd9b747","attribution":"朱生豪等译（逐作保留原书署名）","path":"text/part0043.html","blockCount":1408,"imageCount":1,"textSha256":"e10c866373b53a7b84336444c882275c5a0a0949bcfd0ab1b1b04e50a621bf09","anchorSections":{"a1047":"part0043-section-000","a1048":"part0043-section-000","a1049":"part0043-section-001","w001":"part0043-section-001","w002":"part0043-section-001","w003":"part0043-section-001","w004":"part0043-section-001","m001":"part0043-section-002","m002":"part0043-section-002","m003":"part0043-section-002","m004":"part0043-section-002"},"note":"用户提供的多译者 EPUB；保留原书署名、注释与图像。未作逐句双语对齐。"}};
